var CONTINUT_GEOMETRIE={};
CONTINUT_GEOMETRIE["suma-unghiurilor-unui-triunghi"]={definitie:"<div class=\"def-box\"><strong>Ipoteză:</strong> Fie orice triunghi ABC cu unghiurile interioare α (la A), β (la B) și γ (la C).<br><br><strong>Concluzie:</strong> Indiferent de forma triunghiului, suma celor trei unghiuri este mereu 180°.</div>",formula_display:"α + β + γ = 180°",diagrama:"<svg viewBox=\"0 0 340 230\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><line x1=\"170\" y1=\"25\" x2=\"45\" y2=\"205\" stroke=\"#1a1510\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"305\" y2=\"205\" stroke=\"#1a1510\" stroke-width=\"2\"/><line x1=\"45\" y1=\"205\" x2=\"305\" y2=\"205\" stroke=\"#1a1510\" stroke-width=\"2\"/><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">A</text><text x=\"30\" y=\"213\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">B</text><text x=\"318\" y=\"213\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">C</text><text x=\"170\" y=\"60\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"rgba(30,58,95,0.9)\">α</text><text x=\"79\" y=\"198\" font-size=\"13\" font-style=\"italic\" fill=\"rgba(45,90,61,0.9)\">β</text><text x=\"276\" y=\"198\" font-size=\"13\" font-style=\"italic\" fill=\"rgba(196,92,48,0.9)\">γ</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">α + β + γ = 180°</text></svg>",intuitiv_text:"Desenează un triunghi pe o foaie și taie cele trei colțuri cu foarfeca. Așază cele trei vârfuri unul lângă altul, ca piesele unui puzzle. <span class=\"hl\">Cele trei colțuri se unesc mereu într-o linie dreaptă</span> - ca un drum fără nicio cotitură. Asta înseamnă că suma lor este 180 de grade, întotdeauna, la orice triunghi ai desena, mare sau mic, subțire sau gras.",intuitiv_nota:"Valabilă în geometria euclidiană. Pe suprafața unui glob, suma poate depăși 180° (geometrie sferică), ceea ce permite navigația și GPS-ul.",exercitii:[{"q":"Un triunghi are unghiurile α = 60° și β = 75°. Cât măsoară al treilea unghi, γ?","pasi":["Știm că, în orice triunghi, suma celor trei unghiuri este mereu 180°.","Adunăm cele două unghiuri cunoscute: 60° + 75° = 135°.","Scădem din 180° ca să aflăm unghiul care lipsește: 180° − 135° = 45°."],"r":"✓ γ = <strong>45°</strong>. Verificare: 60°+75°+45° = 180° ✔"},{"q":"Un triunghi isoscel are unghiurile de la bază egale (α = β), iar unghiul din vârf este γ = 40°. Cât măsoară fiecare unghi de la bază?","pasi":["Scădem unghiul din vârf din 180°, ca să aflăm cât rămâne pentru celelalte două unghiuri: 180° − 40° = 140°.","Cele două unghiuri rămase sunt egale între ele, deci împărțim la 2: 140° ÷ 2 = 70°."],"r":"✓ α = β = <strong>70°</strong>"},{"q":"Câte grade are fiecare unghi al unui triunghi echilateral, unde toate cele trei unghiuri sunt egale?","pasi":["Notăm fiecare unghi cu x, pentru că toate trei sunt egale.","Suma lor trebuie să fie 180°, deci scriem: x + x + x = 180°, adică 3x = 180°.","Împărțim la 3: x = 60°."],"r":"✓ Fiecare unghi are <strong>60°</strong>. De aceea triunghiul echilateral pare mereu „rotunjor”, fără colțuri ascuțite sau turtite."},{"q":"Adevărat sau fals: un triunghi poate avea un unghi de 170° și un unghi de 20°.","pasi":["Adunăm cele două unghiuri date: 170° + 20° = 190°.","Dar suma tuturor celor trei unghiuri ale unui triunghi nu poate depăși niciodată 180° - și aici doar două unghiuri depășesc deja acest total."],"r":"✓ <strong>Fals</strong>. Un asemenea triunghi nu poate exista, pentru că doar două dintre unghiuri ar depăși deja 180°."},{"q":"Un acoperiș în formă de triunghi are la bază două unghiuri egale de 65° fiecare, acolo unde se sprijină pe pereți. Ce unghi are vârful acoperișului?","pasi":["Adunăm cele două unghiuri de la bază: 65° + 65° = 130°.","Scădem din 180° ca să aflăm unghiul din vârf: 180° − 130° = 50°."],"r":"✓ Unghiul din vârful acoperișului este <strong>50°</strong>."}]};
CONTINUT_GEOMETRIE["teorema-lui-pitagora"]={definitie:"<div class=\"def-box\"><strong>Ipoteză:</strong> Fie un triunghi dreptunghic cu catetele <em>a</em>, <em>b</em> și ipotenuza <em>c</em> (latura opusă unghiului drept).<br><br><strong>Concluzie:</strong> Suma pătratelor catetelor egalează pătratul ipotenuzei.</div>",formula_display:"a² + b² = c²",diagrama:"<svg viewBox=\"30 25 270 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"130,175 130,115 70,115 70,175\" fill=\"rgba(30,58,95,0.12)\" stroke=\"rgba(30,58,95,0.5)\" stroke-width=\"1.5\"/><text x=\"100\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"rgba(30,58,95,0.8)\">a²</text><polygon points=\"130,175 210,175 210,255 130,255\" fill=\"rgba(45,90,61,0.12)\" stroke=\"rgba(45,90,61,0.5)\" stroke-width=\"1.5\"/><text x=\"170\" y=\"220\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"rgba(45,90,61,0.8)\">b²</text><polygon points=\"130,115 210,175 270,95 190,35\" fill=\"rgba(200,146,42,0.13)\" stroke=\"rgba(200,146,42,0.6)\" stroke-width=\"1.5\"/><text x=\"204\" y=\"108\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"rgba(150,100,10,0.9)\">c²</text><polygon points=\"130,115 210,175 130,175\" fill=\"rgba(26,21,16,0.04)\" stroke=\"#1a1510\" stroke-width=\"2\"/><polyline points=\"130,165 140,165 140,175\" fill=\"none\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><text x=\"118\" y=\"150\" text-anchor=\"end\" font-size=\"14\" font-style=\"italic\" font-weight=\"600\" fill=\"#1a1510\">a</text><text x=\"170\" y=\"192\" text-anchor=\"middle\" font-size=\"14\" font-style=\"italic\" font-weight=\"600\" fill=\"#1a1510\">b</text><text x=\"183\" y=\"138\" font-size=\"14\" font-style=\"italic\" font-weight=\"600\" fill=\"#1a1510\">c</text></svg>",intuitiv_text:"Imaginează-ți trei covorașe pătrate, câte unul lipit de fiecare latură a unui triunghi cu un colț drept (exact ca un colț de carte sau de fereastră). <span class=\"hl\">Dacă tai cele două covorașe mici în bucăți și le așezi peste covorașul mare, îl acoperă exact, fără să rămână loc gol și fără să se suprapună.</span> Se întâmplă mereu, la orice triunghi cu colț drept, oricât de mare sau de mic ar fi el.",intuitiv_nota:"Tripletul (3,4,5) era folosit de constructorii din Egiptul antic (~2000 î.Hr.) cu o frânghie cu 12 noduri egale pentru a trasa unghiuri drepte perfecte.",exercitii:[{"q":"Catetele unui triunghi dreptunghic sunt a = 3 și b = 4. Cât măsoară ipotenuza c?","pasi":["Ridicăm la pătrat cele două catete și le adunăm: 3² + 4² = 9 + 16 = 25.","Ipotenuza este radical din această sumă: c = √25 = 5."],"r":"✓ c = <strong>5</strong>. Este tripletul clasic (3, 4, 5)."},{"q":"Ipotenuza unui triunghi dreptunghic este c = 10, iar o catetă este a = 6. Cât măsoară cealaltă catetă, b?","pasi":["De data asta pornim invers: din pătratul ipotenuzei scădem pătratul catetei cunoscute: 10² − 6² = 100 − 36 = 64.","Cealaltă catetă este radical din acest rezultat: b = √64 = 8."],"r":"✓ b = <strong>8</strong>. Tripletul (6, 8, 10) este dublul lui (3, 4, 5)."},{"q":"Un triunghi dreptunghic isoscel are ambele catete egale cu 1 (jumătate dintr-un pătrat tăiat pe diagonală). Cât măsoară ipotenuza?","pasi":["Adunăm pătratele catetelor egale: 1² + 1² = 1 + 1 = 2.","Ipotenuza este c = √2 ≈ 1,41 - un număr care nu se termină niciodată exact."],"r":"✓ c = <strong>√2 ≈ 1,41</strong>. Așa arată diagonala oricărui pătrat cu latura 1."},{"q":"Un triunghi are laturile 7, 24 și 25. Este el un triunghi dreptunghic?","pasi":["Ridicăm la pătrat cele două laturi mai mici și le adunăm: 7² + 24² = 49 + 576 = 625.","Comparăm cu pătratul laturii celei mai mari: 25² = 625.","Cele două rezultate sunt egale, deci relația lui Pitagora este verificată."],"r":"✓ <strong>Da</strong>, este dreptunghic. (7, 24, 25) este un triplet pitagoreic."},{"q":"O scară de 13 metri este sprijinită de un perete, cu piciorul scării la 5 metri distanță de perete. La ce înălțime pe perete ajunge scara?","pasi":["Scara este ipotenuza unui triunghi dreptunghic, iar distanța de la perete este o catetă: 5 metri.","Scădem pătratul catetei cunoscute din pătratul ipotenuzei: 13² − 5² = 169 − 25 = 144.","Înălțimea este radical din acest rezultat: √144 = 12."],"r":"✓ Scara ajunge la <strong>12 metri</strong> înălțime pe perete."}]};
CONTINUT_GEOMETRIE["teorema-lui-thales"]={definitie:"<div class=\"def-box\"><strong>Ipoteză:</strong> O dreaptă MN paralelă cu latura BC a triunghiului ABC intersectează laturile AB și AC în M și N.<br><br><strong>Concluzie:</strong> MN împarte AB și AC în segmente proporționale.</div>",formula_display:"AM/MB = AN/NC",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"310\"><line x1=\"170\" y1=\"20\" x2=\"50\" y2=\"210\" stroke=\"#1a1510\" stroke-width=\"2\"/><line x1=\"170\" y1=\"20\" x2=\"300\" y2=\"210\" stroke=\"#1a1510\" stroke-width=\"2\"/><line x1=\"50\" y1=\"210\" x2=\"300\" y2=\"210\" stroke=\"#1a1510\" stroke-width=\"2\"/><line x1=\"120\" y1=\"100\" x2=\"225\" y2=\"100\" stroke=\"#c45c30\" stroke-width=\"2\"/><circle cx=\"120\" cy=\"100\" r=\"3.5\" fill=\"#c45c30\"/><circle cx=\"225\" cy=\"100\" r=\"3.5\" fill=\"#c45c30\"/><text x=\"170\" y=\"13\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">A</text><text x=\"38\" y=\"222\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">B</text><text x=\"304\" y=\"222\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">C</text><text x=\"108\" y=\"97\" font-size=\"13\" font-weight=\"600\" fill=\"#c45c30\">M</text><text x=\"229\" y=\"97\" font-size=\"13\" font-weight=\"600\" fill=\"#c45c30\">N</text><text x=\"170\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">AM/MB = AN/NC</text></svg>",intuitiv_text:"Imaginează-ți un brăduț de Crăciun și umbra lui pe zăpadă, într-o zi însorită. Dacă pui lângă el un băț mic, vertical, umbra bățului și umbra bradului cresc <span class=\"hl\">mereu în aceeași proporție</span> - dacă bradul e de 10 ori mai înalt decât bățul, și umbra lui va fi tot de 10 ori mai lungă. La fel funcționează orice linie trasă paralel cu baza unui triunghi: ea împarte celelalte două laturi exact în aceeași proporție, ca o umbră.",intuitiv_nota:"Thales a măsurat înălțimea piramidelor comparând umbra sa cu umbra piramidei - la momentul zilei când umbra oricărui obiect era egală cu înălțimea sa.",exercitii:[{"q":"MN este paralelă cu BC. Știm AM = 4, MB = 6 și NC = 9. Cât măsoară AN?","pasi":["Pentru că MN∥BC, cele două laturi sunt împărțite în aceeași proporție: AM/MB = AN/NC.","Înlocuim ce știm: 4/6 = AN/9.","Simplificăm 4/6 la 2/3, apoi calculăm: AN = 9 × 2/3 = 6."],"r":"✓ AN = <strong>6</strong>. Verificare: 4/6 = 6/9 = 2/3 ✔"},{"q":"MN∥BC, iar linia mijlocie are lungimea MN = 4, cu AM = 5 și MB = 10. Cât măsoară BC?","pasi":["Raportul dintre AM și toată latura AB este 5/(5+10) = 5/15 = 1/3.","Pentru că MN∥BC, MN este aceeași fracțiune din BC: MN/BC = 1/3.","Rezolvăm pentru BC: BC = MN × 3 = 4 × 3 = 12."],"r":"✓ BC = <strong>12</strong>"},{"q":"M este exact mijlocul laturii AB, iar AN = 7. Cât măsoară NC, în cazul acesta special?","pasi":["Dacă M este mijlocul lui AB, atunci AM = MB, deci raportul AM/MB = 1.","Teorema spune că AN/NC = AM/MB = 1, deci AN = NC."],"r":"✓ NC = <strong>7</strong>. Când M e mijlocul unei laturi, N este automat mijlocul celeilalte."},{"q":"Adevărat sau fals: dacă MN taie laturile AB și AC dar nu este paralelă cu BC, segmentele tot sunt proporționale (AM/MB = AN/NC).","pasi":["Teorema lui Thales cere explicit ca MN să fie paralelă cu a treia latură, BC.","Fără paralelism, cele două rapoarte pot fi complet diferite - proporționalitatea nu mai este garantată."],"r":"✓ <strong>Fals</strong>. Paralelismul este condiția esențială, nu un detaliu opțional."},{"q":"Un băț vertical de 1 metru are, la amiază, o umbră de 2 metri. În același moment, un copac are o umbră de 8 metri. Cât de înalt este copacul?","pasi":["Bățul și copacul, împreună cu umbrele lor, formează triunghiuri asemenea (razele soarelui sunt practic paralele).","Raportul înălțime/umbră este același pentru amândouă: 1/2 = h/8.","Rezolvăm pentru h: h = 8 × 1/2 = 4."],"r":"✓ Copacul are <strong>4 metri</strong>. Exact metoda folosită de Thales pentru a măsura piramidele din Egipt."}]};
CONTINUT_GEOMETRIE["teorema-bisectoarei"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Bisectoarea unghiului A al triunghiului ABC intersectează latura opusă BC în punctul D, împărțind-o în raportul laturilor adiacente.</div>",formula_display:"BD/DC = AB/AC",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,20 50,205 300,205\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"20\" x2=\"210\" y2=\"205\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"210\" cy=\"205\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"36\" y=\"218\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"306\" y=\"218\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"210\" y=\"222\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">D</text><path d=\"M 150 45 A 20 20 0 0 1 190 45\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.2\"/><path d=\"M 190 45 A 20 20 0 0 1 190 70\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.2\"/><text x=\"170\" y=\"35\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">egale</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">BD/DC = AB/AC</text></svg>",intuitiv_text:"Imaginează-ți că despici perfect pe din două un colț de pizza, cu un cuțit care taie exact pe mijlocul unghiului. <span class=\"hl\">Cuțitul nu cade la mijlocul marginii opuse decât dacă cele două laturi ale colțului sunt egale</span> - dacă o latură e mai lungă, cuțitul „trage” punctul de tăiere mai aproape de latura scurtă. Bisectoarea împarte mereu latura opusă exact în proporția celor două laturi alăturate ei.",intuitiv_nota:"Teorema este folosită în construcții geometrice cu rigla și compasul pentru a împărți un segment în raport dat.",exercitii:[{"q":"În triunghiul ABC, bisectoarea din A întâlnește BC în D. Știm AB = 6, AC = 4 și BC = 10. Cât măsoară BD și DC?","pasi":["Teorema bisectoarei spune că BD/DC = AB/AC = 6/4 = 3/2.","BD și DC împreună fac toată latura: BD + DC = 10.","Împărțim 10 în părți proporționale cu 3 și 2 (adică 5 părți în total): fiecare parte = 2, deci BD = 3×2 = 6 și DC = 2×2 = 4."],"r":"✓ BD = <strong>6</strong>, DC = <strong>4</strong>"},{"q":"Bisectoarea din A împarte BC astfel încât BD = 3 și DC = 5, iar AC = 10. Cât măsoară AB?","pasi":["Pornim de la relația teoremei: BD/DC = AB/AC.","Înlocuim: 3/5 = AB/10.","Rezolvăm pentru AB: AB = 10 × 3/5 = 6."],"r":"✓ AB = <strong>6</strong>"},{"q":"Într-un triunghi isoscel cu AB = AC, unde cade punctul D pe BC?","pasi":["Aplicăm teorema: BD/DC = AB/AC = AB/AB = 1.","Un raport de 1 înseamnă că BD = DC, adică D împarte BC exact în două părți egale."],"r":"✓ D este <strong>mijlocul lui BC</strong>. La triunghiul isoscel, bisectoarea din vârf este și mediană."},{"q":"Adevărat sau fals: bisectoarea unui unghi al triunghiului împarte întotdeauna latura opusă exact la mijloc.","pasi":["Din exercițiile anterioare am văzut că BD/DC = AB/AC, nu neapărat 1.","Doar atunci când AB = AC (triunghi isoscel pe acel vârf) bisectoarea cade la mijloc; în general, cele două laturi diferă."],"r":"✓ <strong>Fals</strong>. Bisectoarea cade la mijloc doar în cazul special al triunghiului isoscel."},{"q":"Doi copii, Ana și Bogdan, țin capetele unei frânghii lungi de 12 metri legate de un stâlp. Ana este la 9 metri de stâlp, Bogdan la 3 metri. Dacă un al treilea copil stă exact pe linia bisectoarei dintre ei, în ce raport împarte el frânghia?","pasi":["Distanțele copiilor față de stâlp joacă rolul laturilor AB = 9 și AC = 3 din teoremă.","Raportul în care este împărțit segmentul dintre ei este BD/DC = AB/AC = 9/3 = 3/1."],"r":"✓ Raportul este <strong>3:1</strong>, mai aproape de Bogdan (latura mai scurtă)."}]};
CONTINUT_GEOMETRIE["legea-cosinusurilor"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Într-un triunghi cu laturile a, b, c și unghiurile opuse A, B, C, pătratul fiecărei laturi egal cu suma pătratelor celorlalte două laturi minus dublul produsului lor cu cosinusul unghiului cuprins.</div>",formula_display:"a² = b² + c² − 2bc·cosA",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"90,205 300,205 190,30\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><text x=\"90\" y=\"222\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"222\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"190\" y=\"22\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"195\" y=\"55\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">A</text><text x=\"195\" y=\"200\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">c</text><text x=\"140\" y=\"130\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">b</text><text x=\"250\" y=\"130\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">a</text><text x=\"190\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">a² = b² + c² − 2bc·cosA</text></svg>",intuitiv_text:"Când un triunghi are un colț drept, folosim Pitagora. Dar ce facem când colțul e „strâmb” - mai ascuțit sau mai deschis decât un colț drept? <span class=\"hl\">Legea cosinusurilor este un Pitagora „corectat”</span>: ia formula obișnuită a²+b²+c² și adaugă o corecție care ține cont de cât de deschis este unghiul dintre cele două laturi. Dacă unghiul este chiar de 90°, corecția dispare complet și rămânem cu Pitagora.",intuitiv_nota:"Utilizată în topografie, navigație și fizică pentru a calcula distanțe și unghiuri în triunghiuri obtuze sau ascuțite.",exercitii:[{"q":"Un triunghi are laturile b = 5, c = 7 și unghiul dintre ele A = 60°. Cât măsoară latura a, opusă acestui unghi?","pasi":["Aplicăm formula: a² = b² + c² − 2bc·cosA.","Înlocuim numerele: a² = 25 + 49 − 2×5×7×cos60° = 74 − 70×0,5 = 74 − 35 = 39.","Extragem radical: a = √39 ≈ 6,24."],"r":"✓ a ≈ <strong>6,24</strong>"},{"q":"Un triunghi are laturile a = 8, b = 5 și c = 7. Cât măsoară unghiul A, opus laturii a?","pasi":["Rearanjăm formula ca să scoatem cosinusul: cosA = (b² + c² − a²) / (2bc).","Înlocuim: cosA = (25 + 49 − 64) / (2×5×7) = 10/70 = 1/7.","Folosim funcția inversă arccos pentru a afla unghiul: A = arccos(1/7) ≈ 81,8°."],"r":"✓ A ≈ <strong>81,8°</strong>"},{"q":"Ce se întâmplă cu legea cosinusurilor dacă unghiul A este chiar 90°?","pasi":["Știm că cos90° = 0.","Termenul de corecție −2bc·cosA devine −2bc×0 = 0 și dispare din formulă.","Rămâne exact a² = b² + c², adică teorema lui Pitagora."],"r":"✓ Legea cosinusurilor <strong>devine teorema lui Pitagora</strong> - Pitagora este doar un caz particular."},{"q":"Adevărat sau fals: dacă unghiul A este obtuz (mai mare de 90°), latura a este mai scurtă decât ar fi la un unghi drept.","pasi":["Pentru unghiuri obtuze, cosA este negativ, deci −2bc·cosA devine pozitiv și se adaugă la b²+c².","Asta face ca a² - și deci a - să fie mai mare decât în cazul unghiului drept, nu mai mic."],"r":"✓ <strong>Fals</strong>. Un unghi obtuz face latura opusă mai lungă, nu mai scurtă."},{"q":"Doi drumeți pornesc din același punct: unul merge 7 km spre est, celălalt 9 km pe o direcție care face un unghi de 120° cu prima. Cât de departe unul de celălalt ajung?","pasi":["Cele două trasee sunt laturile b = 7 și c = 9 ale unui triunghi, cu unghiul A = 120° între ele.","Aplicăm legea cosinusurilor, știind că cos120° = −0,5: a² = 49 + 81 − 2×7×9×(−0,5) = 130 + 63 = 193.","Extragem radical: a = √193 ≈ 13,89."],"r":"✓ Distanța dintre drumeți este de aproximativ <strong>13,89 km</strong>."}]};
CONTINUT_GEOMETRIE["legea-sinusurilor"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Raportul dintre orice latură a unui triunghi și sinusul unghiului opus este constant, egal cu diametrul cercului circumscris.</div>",formula_display:"a/sinA = b/sinB = c/sinC = 2R",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"120\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/><polygon points=\"170,25 85,175 275,155\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"70\" y=\"182\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"280\" y=\"150\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><circle cx=\"170\" cy=\"120\" r=\"2.5\" fill=\"#c8922a\"/><text x=\"176\" y=\"115\" font-size=\"11\" fill=\"#c8922a\">O</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">a/sinA = b/sinB = c/sinC = 2R</text></svg>",intuitiv_text:"Toate triunghiurile desenate în același cerc, cu aceeași coardă (adică aceeași latură), au ceva în comun: <span class=\"hl\">raportul dintre orice latură și sinusul unghiului opus ei este mereu același număr, egal cu diametrul cercului care trece prin toate cele trei vârfuri.</span> E ca și cum cercul ar „măsura” în secret toate laturile și unghiurile deodată, indiferent de forma triunghiului.",intuitiv_nota:"Folosită în triangulația geodezică, navigație maritimă și astronomie pentru a determina distanțe inaccesibile.",exercitii:[{"q":"Într-un triunghi, a = 10, A = 30° și B = 45°. Cât măsoară latura b?","pasi":["Legea sinusurilor spune că a/sinA = b/sinB.","Calculăm mai întâi raportul comun: a/sinA = 10/sin30° = 10/0,5 = 20.","Aflăm b din acest raport: b = 20 × sin45° = 20 × (√2/2) = 10√2 ≈ 14,14."],"r":"✓ b = <strong>10√2 ≈ 14,14</strong>"},{"q":"Într-un triunghi, latura a = 6 este opusă unghiului A = 60°. Cât măsoară raza R a cercului circumscris?","pasi":["Pornim de la formula: 2R = a/sinA.","Înlocuim: 2R = 6/sin60° = 6/(√3/2) = 12/√3 = 4√3.","Împărțim la 2 ca să aflăm R: R = 2√3 ≈ 3,46."],"r":"✓ R = <strong>2√3 ≈ 3,46</strong>"},{"q":"Un triunghi dreptunghic are unghiul drept A = 90° și ipotenuza a = 10. Cât măsoară raza cercului circumscris?","pasi":["La unghi drept, sin90° = 1, deci formula devine 2R = a/1 = a.","R = a/2 = 10/2 = 5."],"r":"✓ R = <strong>5</strong>. La triunghiul dreptunghic, raza circumscrisă este mereu jumătate din ipotenuză."},{"q":"Adevărat sau fals: dacă doi elevi desenează triunghiuri diferite, dar înscrise în cercuri de aceeași rază R, atunci un unghi de 30° va avea mereu, în ambele triunghiuri, aceeași latură opusă.","pasi":["Din legea sinusurilor: latura opusă unui unghi de 30° este a = 2R·sin30° = R (pentru orice triunghi înscris în acel cerc).","Cum R este fixat, valoarea lui a este aceeași, indiferent de forma restului triunghiului."],"r":"✓ <strong>Adevărat</strong>. Latura depinde doar de R și de unghi, nu de restul figurii."},{"q":"Un topograf măsoară un unghi de 120° între două repere și unghiul de 30° dintre al doilea reper și un al treilea punct, aflat la 8 km de al doilea reper. Cât de departe este al treilea punct de primul reper (latura c)?","pasi":["Punem datele în triunghi: latura cunoscută b = 8, opusă unghiului B = 120°; căutăm latura c, opusă unghiului C = 30°.","Legea sinusurilor: c/sinC = b/sinB, deci c = 8 × sin30° / sin120° = 8 × 0,5 / (√3/2) = 4 / (√3/2) = 8/√3.","Calculăm: 8/√3 ≈ 4,62."],"r":"✓ Distanța este de aproximativ <strong>4,62 km</strong>."}]};
CONTINUT_GEOMETRIE["formula-lui-heron"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria unui triunghi cu laturile a, b, c se calculează prin semiperimetrul s=(a+b+c)/2, fără a cunoaște unghiurile sau înălțimile.</div>",formula_display:"S = √(s(s−a)(s−b)(s−c)), s=(a+b+c)/2",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"60,200 300,200 190,35\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><text x=\"60\" y=\"216\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"216\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"190\" y=\"27\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"115\" y=\"125\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">c</text><text x=\"255\" y=\"125\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">b</text><text x=\"180\" y=\"216\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">a</text><text x=\"180\" y=\"120\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#c8922a\">S</text><text x=\"190\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = √(s(s−a)(s−b)(s−c))</text></svg>",intuitiv_text:"Ca să afli câtă hârtie colorată ai nevoie pentru un triunghi, de obicei trebuie să știi cât de „înalt” este el. Dar formula lui Heron face un truc: <span class=\"hl\">dacă îi spui doar cele trei lungimi ale laturilor, fără să măsori nicio înălțime, ea îți spune exact aria.</span> Mai întâi aduni cele trei laturi și împarți la doi (asta se numește semiperimetru), apoi faci un calcul cu acel număr - și aria apare, ca prin magie.",intuitiv_nota:"Heron din Alexandria a demonstrat formula în lucrarea „Metrica” (~60 d.Hr.). Este utilizată în cartografie și topografie.",exercitii:[{"q":"Un triunghi are laturile a = 3, b = 4, c = 5. Calculează aria cu formula lui Heron.","pasi":["Calculăm semiperimetrul: s = (3+4+5)/2 = 6.","Aplicăm formula: S = √(s(s−a)(s−b)(s−c)) = √(6×3×2×1) = √36.","Extragem radical: S = 6."],"r":"✓ S = <strong>6</strong>. (Se potrivește, pentru că 3-4-5 e triunghi dreptunghic: S = 3×4/2 = 6 ✔)"},{"q":"Un triunghi cu laturile a = 13, b = 14, c = 15 are aria 84 (poți verifica prin Heron). Dacă păstrăm a și b la fel, dar mărim latura c, aria crește sau scade?","pasi":["Mărind c, semiperimetrul s crește, dar factorul (s−c) scade.","Câtă vreme triunghiul rămâne valid (inegalitatea triunghiului respectată), aria crește pe măsură ce triunghiul se „deschide”, până aproape de limita în care devine degenerat (turtit)."],"r":"✓ Aria <strong>crește</strong>, apoi scade brusc spre 0 când triunghiul aproape se turtește (a+b≈c)."},{"q":"Un triunghi echilateral are toate laturile egale cu a. Ce se întâmplă cu formula lui Heron în acest caz special?","pasi":["Semiperimetrul este s = 3a/2, iar fiecare factor (s−a) devine 3a/2 − a = a/2.","Formula devine S = √(3a/2 × a/2 × a/2 × a/2) = √(3a⁴/16) = a²√3/4."],"r":"✓ S = <strong>a²√3/4</strong> - formula cunoscută a ariei triunghiului echilateral."},{"q":"Adevărat sau fals: formula lui Heron funcționează pentru orice trei numere pozitive a, b, c, indiferent de valorile lor.","pasi":["Formula presupune că a, b, c sunt laturile unui triunghi real, ceea ce cere ca inegalitatea triunghiului să fie respectată (suma oricăror două laturi &gt; a treia).","Dacă, de exemplu, a=1, b=1, c=10, expresia de sub radical devine negativă, iar radicalul nu are sens (nu există un asemenea triunghi)."],"r":"✓ <strong>Fals</strong>. Cele trei numere trebuie să poată forma efectiv un triunghi."},{"q":"Un teren triunghiular are laturile de 6 m, 8 m și 10 m. Un grădinar vrea să știe câți metri pătrați de gazon trebuie să cumpere.","pasi":["Calculăm semiperimetrul: s = (6+8+10)/2 = 12.","Aplicăm Heron: S = √(12×6×4×2) = √576 = 24."],"r":"✓ Grădinarul are nevoie de <strong>24 m²</strong> de gazon."}]};
CONTINUT_GEOMETRIE["teorema-medianei-in-triunghi"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Lungimea medianei mₐ din vârful A la mijlocul M al laturii BC, exprimată prin laturile triunghiului.</div>",formula_display:"mₐ² = (2b² + 2c² − a²) / 4",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 60,200 300,200\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"180\" y2=\"200\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"180\" cy=\"200\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"46\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"184\" y=\"214\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">M</text><text x=\"182\" y=\"120\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">mₐ</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">mₐ² = (2b² + 2c² − a²)/4</text></svg>",intuitiv_text:"Mediana e firul care unește un colț al triunghiului exact cu mijlocul laturii din fața lui. <span class=\"hl\">Lungimea ei nu depinde doar de latura pe care cade, ci „simte” toate cele trei laturi ale triunghiului</span> - ca și cum ar fi un fir întins care se lasă tras de fiecare colț în parte. De aceea formula ei folosește toate trei lungimile, nu doar una.",intuitiv_nota:"Apollonius a demonstrat că suma pătratelor celor trei mediane este egală cu trei sferturi din suma pătratelor laturilor.",exercitii:[{"q":"Un triunghi are laturile a = 6, b = 5, c = 7. Cât măsoară mediana mₐ, dusă spre latura a?","pasi":["Aplicăm formula: mₐ² = (2b² + 2c² − a²) / 4.","Înlocuim: mₐ² = (2×25 + 2×49 − 36) / 4 = (50 + 98 − 36) / 4 = 112/4 = 28.","Extragem radical: mₐ = √28 = 2√7 ≈ 5,29."],"r":"✓ mₐ ≈ <strong>5,29</strong>"},{"q":"Un triunghi are a = 10, b = c (este isoscel), iar mediana mₐ = 6. Cât măsoară b?","pasi":["Cu b = c, formula se simplifică: mₐ² = (4b² − a²)/4 = b² − a²/4.","Înlocuim: 36 = b² − 100/4 = b² − 25, deci b² = 61.","Extragem radical: b = √61 ≈ 7,81."],"r":"✓ b ≈ <strong>7,81</strong>"},{"q":"Ce se întâmplă cu mediana mₐ dintr-un triunghi dreptunghic 3-4-5, dusă chiar spre ipotenuza a = 5?","pasi":["Aplicăm formula cu b = 3, c = 4, a = 5: mₐ² = (2×9 + 2×16 − 25)/4 = (18+32−25)/4 = 25/4.","Extragem radical: mₐ = 2,5.","Observăm că 2,5 este exact jumătate din ipotenuza 5."],"r":"✓ mₐ = <strong>2,5</strong> = a/2. La orice triunghi dreptunghic, mediana spre ipotenuză e jumătate din ipotenuză."},{"q":"Adevărat sau fals: mediana dintr-un vârf împarte întotdeauna triunghiul în două triunghiuri cu arii egale.","pasi":["Mediana unește vârful cu mijlocul laturii opuse, deci cele două triunghiuri formate au baze egale (jumătățile laturii) și aceeași înălțime (din vârf).","Arie = bază × înălțime / 2, iar bazele egale și înălțimea comună dau arii egale."],"r":"✓ <strong>Adevărat</strong>. Orice mediană împarte triunghiul în două jumătăți de arii egale."},{"q":"Un triunghi are laturile a = 8, b = 6, c = 6. O rudă de-a ta spune că mediana spre a este mai lungă decât 4. Are dreptate?","pasi":["Aplicăm formula: mₐ² = (2×36 + 2×36 − 64)/4 = (72+72−64)/4 = 80/4 = 20.","Extragem radical: mₐ = √20 = 2√5 ≈ 4,47.","Comparăm cu 4: 4,47 &gt; 4."],"r":"✓ <strong>Da</strong>, are dreptate: mₐ ≈ <strong>4,47</strong>, mai mare decât 4."}]};
CONTINUT_GEOMETRIE["aria-paralelogramului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria unui paralelogram cu baza b, înălțimea h și laturile a, b cu unghiul cuprins α.</div>",formula_display:"S = b·h = a·b·sinα",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"70,180 250,180 290,50 110,50\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"110\" y1=\"50\" x2=\"110\" y2=\"180\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><text x=\"116\" y=\"120\" font-size=\"12\" fill=\"#c8922a\">h</text><text x=\"160\" y=\"196\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">b</text><text x=\"66\" y=\"192\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"254\" y=\"192\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"294\" y=\"45\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"100\" y=\"45\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">D</text><text x=\"170\" y=\"212\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = b · h</text></svg>",intuitiv_text:"Un paralelogram e ca un dreptunghi care s-a „aplecat” într-o parte, de parcă cineva l-ar fi împins ușor. <span class=\"hl\">Dacă tai triunghiul care iese în afară dintr-o parte și îl muți exact în locul gol de partea cealaltă, obții un dreptunghi cu exact aceeași arie</span>. De asta, aria paralelogramului se calculează la fel ca a dreptunghiului: bază ori înălțime.",intuitiv_nota:"Această proprietate este baza calculului determinanților 2×2: |det[a,b]| = aria paralelogramului format de vectorii a și b.",exercitii:[{"q":"Un paralelogram are baza b = 8 și înălțimea h = 5. Calculează aria.","pasi":["Aplicăm formula: S = b × h.","Înlocuim: S = 8 × 5 = 40."],"r":"✓ S = <strong>40</strong>"},{"q":"Un paralelogram are aria S = 48 și baza b = 12. Cât măsoară înălțimea h?","pasi":["Rearanjăm formula: h = S/b.","Înlocuim: h = 48/12 = 4."],"r":"✓ h = <strong>4</strong>"},{"q":"Un romb (caz special de paralelogram, cu toate laturile egale) are diagonalele d₁ = 10 și d₂ = 6. Calculează aria folosind formula specifică rombului.","pasi":["La romb, diagonalele sunt perpendiculare, iar aria se calculează diferit: S = (d₁ × d₂) / 2.","Înlocuim: S = (10×6)/2 = 30."],"r":"✓ S = <strong>30</strong>. Rombul e un paralelogram special, cu formulă proprie de arie."},{"q":"Adevărat sau fals: dacă doi paralelograme au aceeași bază și aceeași înălțime, au automat aceeași arie, chiar dacă sunt „înclinate” diferit.","pasi":["Aria unui paralelogram depinde doar de bază și de înălțime, S = b×h, nu de cât de mult este „aplecat”.","Doi paralelograme cu aceeași bază și înălțime au deci aceeași arie, indiferent de unghiul de înclinare."],"r":"✓ <strong>Adevărat</strong>."},{"q":"Un teren în formă de paralelogram are laturile a = 6 m și b = 10 m, cu unghiul dintre ele de 30°. Calculează aria.","pasi":["Când nu avem înălțimea direct, folosim formula alternativă S = a×b×sin(unghi).","Înlocuim: S = 6×10×sin30° = 60×0,5 = 30."],"r":"✓ Terenul are <strong>30 m²</strong>."}]};
CONTINUT_GEOMETRIE["aria-trapezului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria trapezului cu bazele paralele a și b și înălțimea h.</div>",formula_display:"S = (a + b) · h / 2",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"90,180 260,180 220,50 130,50\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"130\" y1=\"50\" x2=\"130\" y2=\"180\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><text x=\"136\" y=\"120\" font-size=\"12\" fill=\"#c8922a\">h</text><text x=\"175\" y=\"196\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">a (bază mare)</text><text x=\"175\" y=\"44\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">b (bază mică)</text><text x=\"170\" y=\"212\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = (a+b)·h / 2</text></svg>",intuitiv_text:"Un trapez are o bază mare jos și una mică sus, ca o felie de tort sau un acoperiș de șură. <span class=\"hl\">Aria lui este exact media celor două baze, înmulțită cu înălțimea</span> - ca și cum ai „netezi” trapezul până devine un dreptunghi cu o latură egală cu media dintre baza mare și cea mică.",intuitiv_nota:"Formula apare în integrarea numerică (regula trapezului) care aproximează integrala printr-o sumă de trapeze.",exercitii:[{"q":"Un trapez are bazele a = 6 și b = 10, iar înălțimea h = 4. Calculează aria.","pasi":["Aplicăm formula: S = (a+b) × h / 2.","Înlocuim: S = (6+10) × 4 / 2 = 16 × 2 = 32."],"r":"✓ S = <strong>32</strong>"},{"q":"Un trapez are aria S = 40, înălțimea h = 5 și baza mare a = 6. Cât măsoară baza mică b?","pasi":["Pornim de la formula și înlocuim ce știm: 40 = (6+b) × 5 / 2.","Înmulțim ambele părți cu 2: 80 = (6+b) × 5, deci 6+b = 16.","Rezolvăm pentru b: b = 10."],"r":"✓ b = <strong>10</strong>"},{"q":"Ce se întâmplă cu formula trapezului dacă cele două baze devin egale, a = b (adică trapezul devine dreptunghi)?","pasi":["Înlocuim b cu a: S = (a+a) × h / 2 = 2a × h / 2 = a × h.","Aceasta este exact formula ariei dreptunghiului: latură × înălțime."],"r":"✓ Formula devine <strong>S = a·h</strong>, adică aria dreptunghiului - dreptunghiul e un trapez special."},{"q":"Adevărat sau fals: dacă mărești doar înălțimea unui trapez, păstrând bazele fixe, aria se dublează dacă dublezi înălțimea.","pasi":["În formula S = (a+b)×h/2, înălțimea h apare la puterea întâi, înmulțind direct restul expresiei.","Dacă dublăm h, întregul produs se dublează, deci și aria se dublează."],"r":"✓ <strong>Adevărat</strong>."},{"q":"Un teren în formă de trapez are bazele de 20 m și 32 m, iar înălțimea (distanța dintre cele două laturi paralele) este 15 m. Câți metri pătrați are terenul?","pasi":["Aplicăm formula: S = (20+32) × 15 / 2.","Calculăm: S = 52 × 15 / 2 = 780/2 = 390."],"r":"✓ Terenul are <strong>390 m²</strong>."}]};
CONTINUT_GEOMETRIE["unghiul-inscris-in-semicerc"]={definitie:"<div class=\"def-box\"><strong>Enunț (Teorema lui Thales despre cerc):</strong> Dacă AB este diametrul unui cerc și C este orice alt punct al cercului, atunci unghiul ACB este drept.</div>",formula_display:"∡ACB = 90° (AB diametru)",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"130\" r=\"90\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"80\" y1=\"130\" x2=\"260\" y2=\"130\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"80\" y1=\"130\" x2=\"170\" y2=\"40\" stroke=\"#c8922a\" stroke-width=\"2\"/><line x1=\"260\" y1=\"130\" x2=\"170\" y2=\"40\" stroke=\"#c8922a\" stroke-width=\"2\"/><polyline points=\"160,50 170,60 180,50\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><circle cx=\"170\" cy=\"130\" r=\"2.5\" fill=\"#1e3a5f\"/><text x=\"66\" y=\"148\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"266\" y=\"148\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"170\" y=\"30\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"176\" y=\"126\" font-size=\"11\" fill=\"#1e3a5f\">O</text><text x=\"170\" y=\"205\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">∡ACB = 90° (AB diametru)</text></svg>",intuitiv_text:"Imaginează-ți un cerc desenat pe podea, cu un baston pus exact pe mijloc, dintr-o margine în cealaltă (acesta este diametrul). Oriunde ai pune un al treilea copil pe marginea cercului și ai întinde sfori spre cele două capete ale bastonului, <span class=\"hl\">colțul format la copil este mereu exact un colț drept, ca de carte</span>.",intuitiv_nota:"Chiar Thales a demonstrat această teoremă, iar legenda spune că, de bucurie pentru descoperire, a sacrificat un bou ca ofrandă.",exercitii:[{"q":"AB=10 (diametru). AC=6. Găsește BC.","pasi":["Pentru că AB este diametru, unghiul ACB este drept, conform teoremei.","Aplicăm teorema lui Pitagora în triunghiul dreptunghic ACB: AC²+BC²=AB².","Înlocuim: 6²+BC²=10², adică 36+BC²=100, deci BC²=64.","Extragem radical: BC=8."],"r":"✓ BC = <strong>8</strong>"},{"q":"C este pe cerc, AB diametru. Unghiul CAB=40°. Găsește unghiul CBA.","pasi":["Unghiul ACB este drept, pentru că este înscris în semicerc.","Suma unghiurilor din triunghiul ACB este 180°, deci CAB+CBA=180°−90°=90°.","Scădem: CBA=90°−40°=50°."],"r":"✓ CBA = <strong>50°</strong>"},{"q":"Ce se întâmplă cu triunghiul ACB dacă punctul C alunecă pe cerc tot mai aproape de vârful A?","pasi":["Unghiul ACB rămâne mereu 90°, indiferent unde se află C pe cerc, cât timp C este diferit de A și de B.","Dar latura AC devine tot mai scurtă, iar triunghiul se „turtește” tot mai mult.","Când C ajunge exact în A, triunghiul dispare complet - nu mai există trei vârfuri distincte."],"r":"✓ Unghiul rămâne <strong>90°</strong> mereu, dar triunghiul devine tot mai turtit; la limită (C=A) nu mai există triunghi."},{"q":"Adevărat sau fals: dacă punctul C nu este pe cerc, ci undeva strict în interiorul discului, iar AB rămâne diametru, unghiul ACB este tot 90°.","pasi":["Teorema unghiului înscris în semicerc este valabilă doar pentru puncte C aflate exact pe cerc.","Dacă C este în interiorul discului, unghiul ACB devine mai mare de 90° (obtuz) - punctul „vede” diametrul sub un unghi mai larg."],"r":"✓ <strong>Fals</strong>. În interiorul cercului, unghiul ACB este obtuz, nu drept."},{"q":"Un desenator vrea să traseze un unghi drept perfect, fără echer, folosind doar compasul și rigla. Cum poate folosi această teoremă?","pasi":["Desenează un cerc oarecare și alege un diametru AB (o linie dreaptă prin centru).","Alege orice alt punct C pe cerc și îl unește cu A și cu B.","Conform teoremei, unghiul ACB este garantat drept, indiferent de punctul C ales."],"r":"✓ Orice punct C de pe cerc, unit cu capetele unui diametru, formează un <strong>unghi drept</strong> - o metodă veche de construcție geometrică."}]};
CONTINUT_GEOMETRIE["relatia-unghi-inscris-central"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Unghiul central (cu vârful în centru) și unghiul înscris (cu vârful pe cerc) care subtind același arc au raportul 2:1.</div>",formula_display:"∡ înscris = (1/2) · ∡ central",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"120\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"170\" y1=\"120\" x2=\"80.7\" y2=\"152.5\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><line x1=\"170\" y1=\"120\" x2=\"259.3\" y2=\"152.5\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><line x1=\"170\" y1=\"25\" x2=\"80.7\" y2=\"152.5\" stroke=\"#c8922a\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"259.3\" y2=\"152.5\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"170\" cy=\"120\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"176\" y=\"116\" font-size=\"12\" font-weight=\"600\" fill=\"#1e3a5f\">O</text><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#c8922a\">A</text><text x=\"62\" y=\"158\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"266\" y=\"158\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"185\" y=\"105\" font-size=\"11\" fill=\"#1e3a5f\">central</text><text x=\"170\" y=\"205\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">∡A = (1/2)·∡O</text></svg>",intuitiv_text:"Gândește-te la o felie de pizza. <span class=\"hl\">Dacă stai chiar în centrul pizzei, felia pare mult mai „deschisă” decât atunci când te uiți la ea de pe marginea farfuriei</span>, dintr-un alt punct. Unghiul văzut din centru este mereu de două ori mai mare decât unghiul văzut de pe marginea cercului, pentru aceeași felie (același arc).",intuitiv_nota:"Euclid a demonstrat această relație în Cartea III din Elemente, iar proprietatea stă la baza construcțiilor geometrice cu rigla și compasul.",exercitii:[{"q":"Unghiul central pe un arc este 80°. Cât măsoară unghiul înscris pe același arc?","pasi":["Unghiul înscris este întotdeauna jumătate din unghiul central care subîntinde același arc.","Calculăm: unghi înscris = 80°/2 = 40°."],"r":"✓ Unghiul înscris = <strong>40°</strong>"},{"q":"Un unghi înscris măsoară 35°. Cât măsoară unghiul central corespunzător?","pasi":["Din relație rezultă că unghiul central este dublul unghiului înscris.","Calculăm: unghi central = 2×35° = 70°."],"r":"✓ Unghiul central = <strong>70°</strong>"},{"q":"Un arc mic BC are 120°. Dacă vârful unghiului înscris este chiar pe acest arc mic (deci el subîntinde arcul mare, opus), cât măsoară unghiul înscris?","pasi":["Vârful fiind pe arcul mic de 120°, unghiul înscris subîntinde arcul mare, opus lui.","Arcul mare este 360°−120°=240°.","Unghiul înscris = 240°/2=120°."],"r":"✓ <strong>120°</strong>. Unghiul poate fi mai mare decât arcul pe care stă vârful lui, pentru că el „vede” arcul opus."},{"q":"Adevărat sau fals: toate unghiurile înscrise care subîntind același arc au aceeași măsură, indiferent unde este vârful lor pe cercul mare.","pasi":["Toate aceste unghiuri sunt egale cu jumătate din același unghi central, care este fix.","Cum toate se calculează din aceeași jumătate a unghiului central, sunt egale între ele, indiferent de poziția vârfului pe arcul mare."],"r":"✓ <strong>Adevărat</strong>. Este o consecință directă a relației 2:1."},{"q":"Patrulaterul ABCD este inscriptibil (înscris într-un cerc). Unghiul A măsoară 80°. Cât măsoară unghiul C, opus lui?","pasi":["Într-un patrulater inscriptibil, unghiurile opuse au mereu suma 180° - o consecință a relației unghi înscris/central aplicată pe cele două arcuri complementare.","Scădem: unghiul C = 180°−80°=100°."],"r":"✓ Unghiul C = <strong>100°</strong>"}]};
CONTINUT_GEOMETRIE["lungimea-arcului-de-cerc"]={definitie:"<div class=\"def-box\"><strong>Formulă:</strong> Lungimea arcului de cerc cu raza r corespunzând unui unghi central α (în radiani).</div>",formula_display:"l = r · α",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"130\" r=\"90\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><path d=\"M 170 40 A 90 90 0 0 1 247.9 85\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3.5\"/><line x1=\"170\" y1=\"130\" x2=\"170\" y2=\"40\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><line x1=\"170\" y1=\"130\" x2=\"247.9\" y2=\"85\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><circle cx=\"170\" cy=\"130\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"176\" y=\"126\" font-size=\"12\" font-weight=\"600\" fill=\"#1e3a5f\">O</text><text x=\"176\" y=\"70\" font-size=\"12\" fill=\"#1e3a5f\">r</text><text x=\"190\" y=\"115\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">α</text><text x=\"240\" y=\"70\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">l</text><text x=\"170\" y=\"205\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">l = r · α</text></svg>",intuitiv_text:"Gândește-te la o pizza rotundă și la o singură felie tăiată din ea. <span class=\"hl\">Marginea rotunjită a feliei este doar o bucată din toată circumferința pizzei</span> - exact aceeași fracțiune cât reprezintă unghiul feliei din tot cercul (360°). Dacă felia e un sfert din pizza, marginea ei rotunjită este un sfert din toată circumferința.",intuitiv_nota:"Conversia grade↔radiani se face astfel: α[rad]=α[°]×π/180. Un radian este unghiul pentru care lungimea arcului este egală cu raza.",exercitii:[{"q":"r=10, unghiul central este 60°. Calculează lungimea arcului.","pasi":["Formula l=r×α cere unghiul în radiani, așa că mai întâi convertim: α=60°×π/180=π/3 radiani.","Aplicăm formula: l=10×π/3≈10.47."],"r":"✓ l ≈ <strong>10.47</strong>"},{"q":"l=12, r=4. Găsește unghiul α (în radiani și aproximativ în grade).","pasi":["Rearanjăm formula: α=l/r.","Înlocuim: α=12/4=3 radiani.","Convertim în grade: α=3×180/π≈171.9°."],"r":"✓ α = <strong>3 radiani ≈ 171.9°</strong>"},{"q":"Ce se întâmplă cu formula arcului dacă unghiul acoperă tot cercul (α=2π radiani)?","pasi":["Înlocuim α=2π în formula l=r×α: l=r×2π=2πr.","Această valoare este exact formula circumferinței întregului cerc."],"r":"✓ Formula devine <strong>l=2πr</strong> - arcul „complet” este chiar circumferința cercului."},{"q":"Adevărat sau fals: dacă dublezi raza unui cerc, păstrând unghiul α neschimbat, lungimea arcului se dublează și ea.","pasi":["În formula l=r×α, unghiul α rămâne fix, iar r apare la puterea întâi.","Dublarea lui r dublează întregul produs r×α, deci și l se dublează."],"r":"✓ <strong>Adevărat</strong>."},{"q":"Un cal este legat cu o frânghie de 5 metri de un stâlp, într-un colț de pajiște unde poate să pască doar pe un sfert de cerc (α=π/2) în jurul stâlpului. Ce lungime are marginea rotundă a zonei în care poate ajunge calul?","pasi":["Raza mișcării calului este chiar lungimea frânghiei: r=5 metri.","Unghiul disponibil este un sfert de cerc: α=π/2.","Aplicăm formula: l=5×π/2≈7.85."],"r":"✓ Marginea rotundă are aproximativ <strong>7.85 metri</strong>."}]};
CONTINUT_GEOMETRIE["aria-sectorului-circular"]={definitie:"<div class=\"def-box\"><strong>Formulă:</strong> Aria sectorului circular cu raza r și unghi central α (radiani).</div>",formula_display:"S = r²α / 2",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"130\" r=\"90\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><path d=\"M 170 130 L 170 40 A 90 90 0 0 1 247.9 85 Z\" fill=\"rgba(200,146,42,0.25)\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"170\" cy=\"130\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"176\" y=\"126\" font-size=\"12\" font-weight=\"600\" fill=\"#1e3a5f\">O</text><text x=\"176\" y=\"80\" font-size=\"12\" fill=\"#1e3a5f\">r</text><text x=\"200\" y=\"128\" font-size=\"13\" font-weight=\"700\" fill=\"#c8922a\">S</text><text x=\"190\" y=\"105\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">α</text><text x=\"170\" y=\"205\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = r²α / 2</text></svg>",intuitiv_text:"Gândește-te tot la felia de pizza. <span class=\"hl\">Aria unei felii este aceeași fracțiune din toată pizza cât reprezintă unghiul feliei din 360°</span>. O felie de un sfert de cerc are un sfert din toată aria pizzei - nu trebuie să tai și să cântărești, e suficient să știi unghiul.",intuitiv_nota:"Formula apare în fizică pentru a calcula energia cinetică de rotație și în statistică pentru grafice „plăcintă” (pie charts).",exercitii:[{"q":"r=6, α=π/3. Calculează aria sectorului.","pasi":["Aplicăm formula: S=r²α/2.","Înlocuim: S=36×(π/3)/2=6π≈18.85."],"r":"✓ S = <strong>6π ≈ 18.85</strong>"},{"q":"Aria sectorului este S=25π, iar raza este r=10. Găsește unghiul α, în grade.","pasi":["Rearanjăm formula: α=2S/r².","Înlocuim: α=2×25π/100=π/2 radiani.","Convertim în grade: π/2=90°."],"r":"✓ α = <strong>90°</strong>"},{"q":"Ce se întâmplă cu formula sectorului dacă unghiul acoperă tot cercul (α=2π)?","pasi":["Înlocuim: S=r²×2π/2=πr².","Această valoare este exact formula ariei întregului disc."],"r":"✓ Formula devine <strong>S=πr²</strong> - sectorul „complet” este chiar discul întreg."},{"q":"Adevărat sau fals: un sector cu unghiul dublu față de alt sector (aceeași rază) are exact dublul ariei.","pasi":["În formula S=r²α/2, raza r este fixă, iar α apare la puterea întâi.","Dacă dublăm α, produsul r²α se dublează, deci și S se dublează."],"r":"✓ <strong>Adevărat</strong>."},{"q":"Un stropitor de grădină udă iarba pe un sector cu raza de 8 metri și unghiul de 90° (un sfert de cerc). Câți metri pătrați de iarbă udă?","pasi":["Convertim unghiul: 90°=π/2 radiani.","Aplicăm formula: S=64×(π/2)/2=16π≈50.27."],"r":"✓ Stropitorul udă aproximativ <strong>50.27 m²</strong>."}]};
CONTINUT_GEOMETRIE["puterea-unui-punct-fata-de-cerc"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă dintr-un punct P se duc două drepte care intersectează un cerc în perechile {A,B} și {C,D}, produsul PA·PB este egal cu PC·PD.</div>",formula_display:"PA · PB = PC · PD",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"190\" cy=\"120\" r=\"70\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><line x1=\"60\" y1=\"180\" x2=\"258.9\" y2=\"107.6\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><line x1=\"60\" y1=\"180\" x2=\"228.9\" y2=\"61.75\" stroke=\"#c8922a\" stroke-width=\"1.8\"/><circle cx=\"60\" cy=\"180\" r=\"3\" fill=\"#1a1510\"/><circle cx=\"129.3\" cy=\"154.8\" r=\"3\" fill=\"#1e3a5f\"/><circle cx=\"258.9\" cy=\"107.6\" r=\"3\" fill=\"#1e3a5f\"/><circle cx=\"122\" cy=\"136.6\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"228.9\" cy=\"61.75\" r=\"3\" fill=\"#c8922a\"/><text x=\"44\" y=\"196\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">P</text><text x=\"112\" y=\"150\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"264\" y=\"104\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"106\" y=\"132\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">C</text><text x=\"232\" y=\"54\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">D</text><text x=\"170\" y=\"210\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">PA·PB = PC·PD</text></svg>",intuitiv_text:"Imaginează-ți un punct P în afara unui lac rotund, iar tu tragi două sfori diferite din P, care ambele trec prin lac și ies pe partea cealaltă. <span class=\"hl\">Dacă înmulțești distanța până unde intră sfoara cu distanța până unde iese, obții mereu același număr</span>, indiferent prin ce parte a lacului treci - acest număr se numește puterea punctului P.",intuitiv_nota:"Dacă cunoaștem lungimea tangentei PT (PT²=p) și o secantă, putem calcula cealaltă secantă - o relație care stă la baza construcțiilor inverse din geometria proiectivă.",exercitii:[{"q":"PA=4, PB=9 pe o secantă din P. O altă secantă din P are PD=6. Găsește PC.","pasi":["Puterea punctului P este aceeași pentru orice secantă dusă din P, deci PA×PB=PC×PD.","Calculăm primul produs: PA×PB=4×9=36.","Rezolvăm ecuația: PC×6=36, deci PC=6."],"r":"✓ PC = <strong>6</strong>"},{"q":"Din P se duce o tangentă cu PT=6 și o secantă cu PA=4. Găsește PB, cealaltă intersecție a secantei.","pasi":["Pentru o tangentă și o secantă din același punct, relația este PT²=PA×PB.","Calculăm: PT²=6²=36.","Rezolvăm: 4×PB=36, deci PB=9."],"r":"✓ PB = <strong>9</strong>"},{"q":"Punctul P este exterior unui cerc, la distanța d=10 de centru, iar raza cercului este r=6. Găsește puterea punctului și lungimea tangentei din P.","pasi":["Puterea punctului față de cerc este p=d²−r².","Calculăm: p=10²−6²=100−36=64.","Lungimea tangentei este radical din putere: PT=√64=8."],"r":"✓ Puterea = <strong>64</strong>, iar tangenta PT = <strong>8</strong>"},{"q":"Adevărat sau fals: dacă punctul P se află chiar pe cerc, puterea sa față de cerc este 0.","pasi":["Puterea se calculează ca p=d²−r², unde d este distanța de la P la centru.","Dacă P este pe cerc, atunci d=r, deci p=r²−r²=0."],"r":"✓ <strong>Adevărat</strong>. Orice secantă prin P pe cerc „intersectează” cercul chiar în P, cu produs 0."},{"q":"Într-un teren circular, două alei drepte se intersectează într-un punct P din interior. Pe prima alee, distanțele de la P la marginile terenului sunt PA=2 m și PB=10 m. Pe a doua alee, distanța de la P la o margine este PC=4 m. Cât este distanța PD până la cealaltă margine?","pasi":["Chiar dacă P este în interiorul cercului, produsul distanțelor este constant pentru orice coardă prin P: PA×PB=PC×PD.","Calculăm primul produs: PA×PB=2×10=20.","Rezolvăm ecuația PC×PD=20, adică 4×PD=20, de unde PD=5."],"r":"✓ PD = <strong>5 metri</strong>"}]};
CONTINUT_GEOMETRIE["doua-tangente-dintr-un-punct-exterior"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Din orice punct P exterior unui cerc cu centrul O și raza r se pot duce exact două tangente, iar lungimile lor sunt egale.</div>",formula_display:"|PT₁| = |PT₂| = √(|PO|² − r²)",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"190\" cy=\"120\" r=\"70\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><circle cx=\"190\" cy=\"120\" r=\"2.5\" fill=\"#1e3a5f\"/><line x1=\"60\" y1=\"120\" x2=\"190\" y2=\"120\" stroke=\"#1e3a5f\" stroke-width=\"1.3\" stroke-dasharray=\"4,3\"/><line x1=\"60\" y1=\"120\" x2=\"152.2\" y2=\"61\" stroke=\"#c8922a\" stroke-width=\"2\"/><line x1=\"60\" y1=\"120\" x2=\"152.2\" y2=\"179\" stroke=\"#c8922a\" stroke-width=\"2\"/><line x1=\"190\" y1=\"120\" x2=\"152.2\" y2=\"61\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"190\" y1=\"120\" x2=\"152.2\" y2=\"179\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><circle cx=\"60\" cy=\"120\" r=\"3\" fill=\"#1a1510\"/><text x=\"44\" y=\"112\" font-size=\"14\" font-weight=\"600\" fill=\"#1a1510\">P</text><text x=\"196\" y=\"116\" font-size=\"12\" font-weight=\"600\" fill=\"#1e3a5f\">O</text><text x=\"132\" y=\"52\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">T₁</text><text x=\"132\" y=\"196\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">T₂</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">PT₁ = PT₂</text></svg>",intuitiv_text:"Imaginează-ți că ții în mâini două lanterne identice, îndreptate spre o minge rotundă din fața ta, astfel încât fasciculul fiecăreia doar „atinge” mingea, fără să intre în ea. <span class=\"hl\">Cele două raze de lumină ating mingea la aceeași distanță de tine</span>, pentru că situația este perfect simetrică - ca imaginea în oglindă una a celeilalte.",intuitiv_nota:"Proprietatea stă la baza construcției cercului înscris în unghi și a cercurilor exscrise unui triunghi.",exercitii:[{"q":"PO=13, r=5. Găsește lungimea tangentei PT.","pasi":["Triunghiul OTP este dreptunghic în T (raza OT este perpendiculară pe tangenta PT).","Aplicăm Pitagora: PT²=PO²−r²=13²−5²=169−25=144.","Extragem radical: PT=12."],"r":"✓ PT = <strong>12</strong>"},{"q":"PO=10, PT=8. Găsește raza r.","pasi":["Din același triunghi dreptunghic: r²=PO²−PT².","Înlocuim: r²=100−64=36.","Extragem radical: r=6."],"r":"✓ r = <strong>6</strong>"},{"q":"Ce se întâmplă cu lungimea tangentei PT dacă punctul P se apropie tot mai mult de cerc, adică PO se apropie de r?","pasi":["Formula tangentei este PT=√(PO²−r²).","Dacă PO se apropie de r, diferența PO²−r² se apropie de 0, deci PT se apropie de 0.","Când P ajunge chiar pe cerc, cele două tangente „dispar” - nu mai există un punct exterior din care să le tragem."],"r":"✓ Lungimea tangentei <strong>tinde spre 0</strong> pe măsură ce P se apropie de cerc."},{"q":"Adevărat sau fals: dreapta PO este bisectoarea unghiului format de cele două tangente T₁PT₂.","pasi":["Triunghiurile POT₁ și POT₂ sunt congruente (OT₁=OT₂=r, PO comun, unghi drept la T₁ și T₂).","Din congruență rezultă că unghiurile OPT₁ și OPT₂ sunt egale, deci PO împarte unghiul T₁PT₂ exact în două."],"r":"✓ <strong>Adevărat</strong>. PO este axa de simetrie a întregii figuri."},{"q":"r=6, unghiul ∡OPT₁=30°. Găsește PO și PT₁.","pasi":["În triunghiul dreptunghic OPT₁: sin(∡OPT₁)=r/PO.","Rezolvăm: sin30°=6/PO, deci PO=6/0,5=12.","Lungimea tangentei este PT₁=PO×cos30°=12×(√3/2)=6√3≈10,39."],"r":"✓ PO = <strong>12</strong>, PT₁ = <strong>6√3 ≈ 10,39</strong>"}]};
CONTINUT_GEOMETRIE["aria-cercului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria discului (suprafeței interioare a cercului) cu raza r.</div>",formula_display:"S = π · r²",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"280\"><circle cx=\"170\" cy=\"110\" r=\"85\" fill=\"rgba(30,58,95,0.1)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"110\" x2=\"255\" y2=\"110\" stroke=\"#c8922a\" stroke-width=\"2.2\"/><circle cx=\"170\" cy=\"110\" r=\"2.5\" fill=\"#1e3a5f\"/><text x=\"176\" y=\"106\" font-size=\"12\" font-weight=\"600\" fill=\"#1e3a5f\">O</text><text x=\"205\" y=\"103\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">r</text><text x=\"170\" y=\"115\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#1e3a5f\">S</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = π·r²</text></svg>",intuitiv_text:"Imaginează-ți un cerc tăiat în felii foarte subțiri, ca o pizza cu foarte multe felii. Dacă așezi feliile alternativ, cu vârful în sus și în jos, ca dinții unui fermoar, ele formează aproape un dreptunghi. <span class=\"hl\">Cu cât tai felii mai subțiri, cu atât forma seamănă mai bine cu un dreptunghi perfect</span>, cu o latură egală cu raza și cealaltă egală cu jumătate din marginea cercului - de aici vine formula ariei.",intuitiv_nota:"π este irațional și transcendent - proprietate demonstrată de Lindemann în 1882. Cifrele lui nu se repetă niciodată și nu urmează niciun tipar.",exercitii:[{"q":"r=7. Calculează aria cercului.","pasi":["Aplicăm formula S=π×r².","Înlocuim: S=π×49=49π≈153,94."],"r":"✓ S = <strong>49π ≈ 153,94</strong>"},{"q":"Aria unui cerc este S=100π. Găsește raza r.","pasi":["Rearanjăm formula: r²=S/π.","Înlocuim: r²=100π/π=100.","Extragem radical: r=10."],"r":"✓ r = <strong>10</strong>"},{"q":"Circumferința (perimetrul) unui cerc este C=12π. Calculează aria discului.","pasi":["Din formula circumferinței C=2πr aflăm raza: 12π=2πr, deci r=6.","Aplicăm formula ariei: S=π×6²=36π."],"r":"✓ S = <strong>36π</strong>"},{"q":"Adevărat sau fals: dacă raza unui cerc crește de 3 ori, aria crește tot de 3 ori.","pasi":["Aria depinde de pătratul razei: S=πr².","Dacă raza devine 3r, noua arie este π(3r)²=9πr²=9S, nu 3S."],"r":"✓ <strong>Fals</strong>. Aria crește de 9 ori, nu de 3 ori - pentru că raza apare la pătrat în formulă."},{"q":"O pizza rotundă are diametrul d=14 cm. Câți centimetri pătrați de pizza sunt în total?","pasi":["Din diametru aflăm raza: r=d/2=14/2=7 cm.","Aplicăm formula: S=π×7²=49π≈153,94 cm²."],"r":"✓ Pizza are aproximativ <strong>153,94 cm²</strong>."}]};
CONTINUT_GEOMETRIE["suma-unghiurilor-poligon-convex"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Suma unghiurilor interioare ale unui poligon convex cu n laturi (n≥3).</div>",formula_display:"S = (n − 2) · 180°",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 255.6,87.2 222.9,187.8 117.1,187.8 84.4,87.2\" fill=\"rgba(30,58,95,0.06)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"222.9\" y2=\"187.8\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><line x1=\"170\" y1=\"25\" x2=\"117.1\" y2=\"187.8\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">1</text><text x=\"262\" y=\"86\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">2</text><text x=\"228\" y=\"204\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">3</text><text x=\"100\" y=\"204\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">4</text><text x=\"66\" y=\"86\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">5</text><text x=\"170\" y=\"112\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c8922a\">3 triunghiuri</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = (n−2)·180° = 3×180° = 540°</text></svg>",intuitiv_text:"Gândește-te la orice poligon ca la un tort care poate fi tăiat în felii triunghiulare, toate pornind dintr-un singur colț. <span class=\"hl\">Un poligon cu n colțuri se taie mereu în exact (n-2) triunghiuri</span>, iar fiecare triunghi are 180°, deci suma tuturor unghiurilor poligonului este (n-2)×180°.",intuitiv_nota:"Un poligon regulat are fiecare unghi interior egal cu (n-2)×180°/n. Pentru n=6: 120° - de aceea albinele construiesc faguri hexagonali.",exercitii:[{"q":"Un pentagon (n=5) este un poligon convex cu 5 laturi. Calculează suma unghiurilor lui interioare.","pasi":["Aplicăm formula: S=(n−2)×180°.","Înlocuim: S=(5−2)×180°=3×180°=540°."],"r":"✓ S = <strong>540°</strong>"},{"q":"Fiecare unghi interior al unui poligon regulat este 150°. Câte laturi are poligonul?","pasi":["La un poligon regulat cu n laturi, fiecare unghi este S/n=(n−2)×180°/n.","Punem ecuația: (n−2)×180/n=150.","Rezolvăm: 180n−360=150n, deci 30n=360, adică n=12."],"r":"✓ n = <strong>12</strong> (un dodecagon)"},{"q":"Cât este suma unghiurilor exterioare ale oricărui poligon convex, indiferent de numărul laturilor?","pasi":["Spre deosebire de unghiurile interioare, suma unghiurilor exterioare este mereu aceeași: 360°, oricâte laturi are poligonul.","Aceasta se întâmplă pentru că, parcurgând conturul poligonului, te „rotești” exact o dată completă (360°)."],"r":"✓ Suma unghiurilor exterioare este mereu <strong>360°</strong>."},{"q":"Adevărat sau fals: un poligon convex cu mai multe laturi are întotdeauna o sumă mai mare a unghiurilor interioare decât unul cu mai puține laturi.","pasi":["Formula S=(n−2)×180° crește pe măsură ce n crește, pentru că factorul (n−2) crește.","De exemplu, un pentagon (n=5) are 540°, iar un hexagon (n=6) are 720° - mai mult."],"r":"✓ <strong>Adevărat</strong>. Suma unghiurilor crește mereu odată cu numărul de laturi."},{"q":"De ce aleg albinele să construiască celulele fagurelui în formă de hexagon (n=6)? Cât măsoară fiecare unghi interior?","pasi":["Suma unghiurilor unui hexagon este S=(6−2)×180°=720°.","Fiecare din cele 6 unghiuri ale unui hexagon regulat este egal: 720°/6=120°.","Un unghi de 120° permite hexagoanelor să se îmbine perfect, fără goluri, atunci când sunt așezate unul lângă altul."],"r":"✓ Fiecare unghi are <strong>120°</strong>, iar hexagoanele se îmbină perfect, fără spații goale."}]};
CONTINUT_GEOMETRIE["diagonala-paralelipipedului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Lungimea diagonalei principale a unui paralelipiped dreptunghic cu dimensiunile a, b, c (generalizarea teoremei lui Pitagora în 3D).</div>",formula_display:"d = √(a² + b² + c²)",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"60,180 200,180 200,80 60,80\" fill=\"rgba(30,58,95,0.05)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"120,140 260,140 260,40 120,40\" fill=\"rgba(30,58,95,0.05)\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"60\" y1=\"180\" x2=\"120\" y2=\"140\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"200\" y1=\"180\" x2=\"260\" y2=\"140\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"200\" y1=\"80\" x2=\"260\" y2=\"40\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"60\" y1=\"80\" x2=\"120\" y2=\"40\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"60\" y1=\"180\" x2=\"260\" y2=\"40\" stroke=\"#c8922a\" stroke-width=\"2.4\"/><text x=\"126\" y=\"196\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">a</text><text x=\"86\" y=\"165\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">b</text><text x=\"46\" y=\"132\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">c</text><text x=\"175\" y=\"105\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">d</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">d = √(a² + b² + c²)</text></svg>",intuitiv_text:"Imaginează-ți o cutie de pantofi. Ca să afli cât de lungă este o sfoară întinsă din colțul de jos până în colțul opus, cel mai de sus, faci Pitagora de două ori: <span class=\"hl\">întâi afli diagonala podelei cutiei, apoi mai faci un Pitagora între diagonala aceea și înălțimea cutiei</span>. Fiecare pas adaugă o nouă dimensiune.",intuitiv_nota:"Formula se generalizează în n dimensiuni (lungimea diagonalei unui hipercub este a√n) și apare în geometria metrică și în relativitate.",exercitii:[{"q":"O cutie are dimensiunile a=3, b=4, c=12. Calculează diagonala principală d.","pasi":["Aplicăm formula: d=√(a²+b²+c²).","Înlocuim: d=√(9+16+144)=√169.","Extragem radical: d=13."],"r":"✓ d = <strong>13</strong>"},{"q":"Un cub are latura a. Exprimă diagonala lui principală în funcție de a.","pasi":["Într-un cub, toate cele trei dimensiuni sunt egale: a=b=c.","Formula devine d=√(a²+a²+a²)=√(3a²)=a√3."],"r":"✓ d = <strong>a√3</strong>"},{"q":"Adevărat sau fals: dacă dublezi toate cele trei dimensiuni ale unui paralelipiped (a, b, c), diagonala principală se dublează și ea.","pasi":["Formula este d=√(a²+b²+c²).","Dacă dublăm fiecare dimensiune: d'=√((2a)²+(2b)²+(2c)²)=√(4a²+4b²+4c²)=2√(a²+b²+c²)=2d."],"r":"✓ <strong>Adevărat</strong>. Diagonala se dublează exact atunci când toate cele trei laturi se dublează."},{"q":"Diagonala unei cutii este d=14, iar a=2, b=4. Găsește c.","pasi":["Din formulă: d²=a²+b²+c².","Înlocuim: 196=4+16+c², deci c²=176.","Extragem radical: c=√176=4√11≈13,27."],"r":"✓ c ≈ <strong>13,27</strong>"},{"q":"O cameră are dimensiunile 5 m × 4 m × 3 m. Ce lungime maximă poate avea un obiect drept (o bară) care încape pe diagonala camerei?","pasi":["Aplicăm formula: d=√(5²+4²+3²).","Calculăm: d=√(25+16+9)=√50=5√2≈7,07."],"r":"✓ d ≈ <strong>7,07 m</strong>"}]};
CONTINUT_GEOMETRIE["aria-sferei"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria suprafeței sferei de raza r, demonstrată de Arhimede prin metoda exhaustivă: sfera este egală cu 4 cercuri mari.</div>",formula_display:"S = 4π r²",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"120\" cy=\"110\" r=\"75\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><ellipse cx=\"120\" cy=\"110\" rx=\"75\" ry=\"22\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/><line x1=\"120\" y1=\"110\" x2=\"195\" y2=\"110\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"150\" y=\"103\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">r</text><text x=\"120\" y=\"200\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1e3a5f\">sferă, raza r</text><circle cx=\"270\" cy=\"60\" r=\"18\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><circle cx=\"310\" cy=\"60\" r=\"18\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><circle cx=\"270\" cy=\"100\" r=\"18\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><circle cx=\"310\" cy=\"100\" r=\"18\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><text x=\"290\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\">4 cercuri mari</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = 4·π·r²</text></svg>",intuitiv_text:"Imaginează-ți o portocală. Dacă ai da jos coaja ei cu grijă și ai încerca s-o întinzi perfect plat pe masă, ai avea nevoie de o bucată de hârtie cât <span class=\"hl\">patru cercuri, fiecare de mărimea celui mai mare cerc pe care îl poți tăia din portocală</span> - exact asta a descoperit Arhimede.",intuitiv_nota:"Pământul are S≈510 milioane km². Dacă l-am „desface” pe o hartă, nu am putea face-o fără distorsiuni - din cauza acestei formule.",exercitii:[{"q":"r=6. Calculează aria sferei.","pasi":["Aplicăm formula S=4π×r².","Înlocuim: S=4π×36=144π≈452,4."],"r":"✓ S = <strong>144π ≈ 452,4</strong>"},{"q":"Aria unei sfere este S=100π. Găsește raza r.","pasi":["Rearanjăm formula: r²=S/(4π).","Înlocuim: r²=100π/(4π)=25.","Extragem radical: r=5."],"r":"✓ r = <strong>5</strong>"},{"q":"Arată că aria sferei este exact de 4 ori aria celui mai mare cerc al ei (cercul cu aceeași rază r).","pasi":["Aria cercului mare (secțiunea prin centrul sferei) este S_cerc=π×r².","Aria sferei este S_sferă=4×π×r².","Comparăm: S_sferă/S_cerc=4πr²/πr²=4."],"r":"✓ Aria sferei este exact <strong>de 4 ori</strong> aria celui mai mare cerc al ei - descoperirea lui Arhimede."},{"q":"Adevărat sau fals: dacă raza unei sfere se dublează, aria ei se dublează și ea.","pasi":["Aria sferei este S=4πr², deci depinde de pătratul razei.","Dacă dublăm raza: S'=4π(2r)²=16πr²=4S, nu 2S."],"r":"✓ <strong>Fals</strong>. Aria crește de 4 ori, nu de 2 ori."},{"q":"O minge de tenis are raza r=3,2 cm. Calculează aria suprafeței ei.","pasi":["Aplicăm formula S=4π×r².","Înlocuim: S=4π×3,2²=4π×10,24≈128,7 cm²."],"r":"✓ S ≈ <strong>128,7 cm²</strong>"}]};
CONTINUT_GEOMETRIE["volumul-sferei"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Volumul sferei de raza r, demonstrat de Arhimede: este 2/3 din volumul cilindrului circumscris.</div>",formula_display:"V = (4/3) · π · r³",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><ellipse cx=\"140\" cy=\"30\" rx=\"80\" ry=\"18\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><line x1=\"60\" y1=\"30\" x2=\"60\" y2=\"190\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><line x1=\"220\" y1=\"30\" x2=\"220\" y2=\"190\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><path d=\"M 60 190 A 80 18 0 0 0 220 190\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><circle cx=\"140\" cy=\"110\" r=\"80\" fill=\"rgba(200,146,42,0.15)\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"140\" y=\"213\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\">sfera „umple” 2/3 din cilindru</text><text x=\"140\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">V = (4/3)·π·r³</text></svg>",intuitiv_text:"Arhimede a descoperit ceva atât de frumos, încât a cerut să fie desenat pe piatra lui de mormânt: <span class=\"hl\">dacă pui o minge exact într-un pahar cilindric care o atinge pe toate părțile, mingea umple exact 2 din cele 3 părți ale paharului</span>, restul de o treime rămânând gol.",intuitiv_nota:"Volumul Pământului ≈ 1.08×10¹² km³. Calculul planurilor orbitale și al densității corpurilor cerești folosește această formulă.",exercitii:[{"q":"r=3. Calculează volumul sferei.","pasi":["Aplicăm formula V=(4/3)×π×r³.","Înlocuim: V=(4/3)×π×27=36π≈113,1."],"r":"✓ V = <strong>36π ≈ 113,1</strong>"},{"q":"Volumul unei sfere este V=288π. Găsește raza r.","pasi":["Rearanjăm formula: r³=3V/(4π).","Înlocuim: r³=3×288π/(4π)=216.","Extragem radical de ordin 3: r=6."],"r":"✓ r = <strong>6</strong>"},{"q":"Un cilindru circumscris unei sfere de rază r are exact raza r și înălțimea h=2r (sfera atinge toți pereții). Arată că volumul sferei este 2/3 din volumul acestui cilindru.","pasi":["Volumul cilindrului este V_cil=π×r²×h=π×r²×2r=2πr³.","Volumul sferei este V_sf=(4/3)πr³.","Raportul este V_sf/V_cil=[(4/3)πr³]/(2πr³)=(4/3)/2=2/3."],"r":"✓ Sfera umple exact <strong>2/3</strong> din volumul cilindrului circumscris - descoperirea lui Arhimede."},{"q":"Adevărat sau fals: dacă raza unei sfere se triplează, volumul ei se triplează și el.","pasi":["Volumul sferei este V=(4/3)πr³, deci depinde de r la puterea a treia.","Dacă triplăm raza: V'=(4/3)π(3r)³=27×(4/3)πr³=27V, nu 3V."],"r":"✓ <strong>Fals</strong>. Volumul crește de 27 ori, nu de 3 ori."},{"q":"O bilă de plumb are raza r=2 cm, iar densitatea plumbului este ρ=11,3 g/cm³. Ce masă are bila?","pasi":["Calculăm volumul: V=(4/3)×π×2³=(4/3)×π×8≈33,5 cm³.","Masa este volum×densitate: m=33,5×11,3≈379 g."],"r":"✓ m ≈ <strong>379 g</strong>"}]};
CONTINUT_GEOMETRIE["volumul-conului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Volumul conului circular drept cu raza bazei r și înălțimea h este o treime din volumul cilindrului cu aceleași dimensiuni.</div>",formula_display:"V = (1/3) · π · r² · h",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><ellipse cx=\"170\" cy=\"185\" rx=\"75\" ry=\"18\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><line x1=\"95\" y1=\"185\" x2=\"170\" y2=\"30\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"245\" y1=\"185\" x2=\"170\" y2=\"30\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"185\" x2=\"170\" y2=\"30\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><line x1=\"170\" y1=\"185\" x2=\"245\" y2=\"185\" stroke=\"#1e3a5f\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\"/><text x=\"205\" y=\"200\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">r</text><text x=\"178\" y=\"105\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">h</text><text x=\"170\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">vârf</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">V = (1/3)·π·r²·h</text></svg>",intuitiv_text:"Imaginează-ți o pălărie de petrecere, în formă de con, și un pahar cilindric cu aceeași bază rotundă și aceeași înălțime. <span class=\"hl\">Dacă umpli pălăria cu nisip și o torni în pahar, ai nevoie de exact 3 pălării pline ca să umpli paharul</span> - conul este mereu a treia parte dintr-un cilindru cu aceeași bază și înălțime.",intuitiv_nota:"Pâlnia, vârful creionului, munții vulcanici - toate sunt aproximări ale conului. Formula apare în calculul volumelor în inginerie și design industrial.",exercitii:[{"q":"r=3, h=7. Calculează volumul conului.","pasi":["Aplicăm formula V=(1/3)×π×r²×h.","Înlocuim: V=(1/3)×π×9×7=21π≈65,97."],"r":"✓ V = <strong>21π ≈ 65,97</strong>"},{"q":"Volumul unui con este V=48π, iar raza bazei este r=6. Găsește înălțimea h.","pasi":["Rearanjăm formula: h=3V/(π×r²).","Înlocuim: h=3×48π/(π×36)=144π/36π=4."],"r":"✓ h = <strong>4</strong>"},{"q":"Un cilindru are raza r=5 și înălțimea h=12. Calculează volumul conului cu exact aceeași bază și înălțime.","pasi":["Volumul cilindrului este V_cil=π×r²×h=π×25×12=300π.","Volumul conului este o treime din acesta: V_con=V_cil/3=300π/3=100π."],"r":"✓ V_con = <strong>100π</strong>"},{"q":"Adevărat sau fals: dacă dublezi doar înălțimea unui con, păstrând raza fixă, volumul se dublează.","pasi":["Formula este V=(1/3)πr²h, iar h apare la puterea întâi.","Dublarea lui h dublează întregul produs r²×h, deci V se dublează."],"r":"✓ <strong>Adevărat</strong>."},{"q":"O înghețată în formă de con are raza r=3 cm și înălțimea h=10 cm. Câți centimetri cubi de înghețată încap în con?","pasi":["Aplicăm formula: V=(1/3)×π×9×10.","Calculăm: V=30π≈94,2 cm³."],"r":"✓ V ≈ <strong>94,2 cm³</strong>"}]};
CONTINUT_GEOMETRIE["volumul-cilindrului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Volumul cilindrului circular drept cu raza bazei r și înălțimea h.</div>",formula_display:"V = π · r² · h",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><ellipse cx=\"170\" cy=\"35\" rx=\"75\" ry=\"18\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><line x1=\"95\" y1=\"35\" x2=\"95\" y2=\"180\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><line x1=\"245\" y1=\"35\" x2=\"245\" y2=\"180\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><path d=\"M 95 180 A 75 18 0 0 0 245 180\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.8\"/><path d=\"M 95 35 A 75 18 0 0 0 245 35\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><line x1=\"170\" y1=\"35\" x2=\"170\" y2=\"180\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><line x1=\"170\" y1=\"35\" x2=\"245\" y2=\"35\" stroke=\"#1e3a5f\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\"/><text x=\"205\" y=\"28\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">r</text><text x=\"178\" y=\"110\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">h</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">V = π·r²·h</text></svg>",intuitiv_text:"Gândește-te la o cutie de conservă. <span class=\"hl\">Volumul ei este aria cercului de la bază, „întinsă” pe toată înălțimea cutiei</span> - la fel cum ai stivui foarte multe monede rotunde una peste alta, până ajungi la înălțimea dorită.",intuitiv_nota:"Cutiile de conserve, conductele, coloanele - toate sunt cilindri. Formula apare în hidrodinamică pentru calculul debitului.",exercitii:[{"q":"r=4, h=10. Calculează volumul cilindrului.","pasi":["Aplicăm formula V=π×r²×h.","Înlocuim: V=π×16×10=160π≈502,7."],"r":"✓ V = <strong>160π ≈ 502,7</strong>"},{"q":"Volumul unui cilindru este V=100π, iar înălțimea este h=4. Găsește raza r.","pasi":["Rearanjăm formula: r²=V/(π×h).","Înlocuim: r²=100π/(π×4)=25.","Extragem radical: r=5."],"r":"✓ r = <strong>5</strong>"},{"q":"Un cilindru are raza exact egală cu înălțimea (r=h). Exprimă volumul lui doar în funcție de r.","pasi":["Înlocuim h=r în formula V=π×r²×h.","Obținem: V=π×r²×r=π×r³."],"r":"✓ V = <strong>π·r³</strong> - o formulă care seamănă cu cea a sferei, dar fără factorul 4/3."},{"q":"Adevărat sau fals: dacă dublezi raza unui cilindru și înjumătățești înălțimea, volumul rămâne neschimbat.","pasi":["Noul volum este V'=π×(2r)²×(h/2)=π×4r²×h/2=2πr²h.","Comparăm cu volumul original V=πr²h: V'=2V, deci volumul nu rămâne la fel, ci se dublează."],"r":"✓ <strong>Fals</strong>. Volumul se dublează, nu rămâne neschimbat."},{"q":"Un rezervor cilindric are volumul de 616 cm³ și raza bazei r=7 cm (folosim π≈22/7). Ce înălțime are rezervorul?","pasi":["Aplicăm formula cu π≈22/7: V=(22/7)×r²×h.","Înlocuim: 616=(22/7)×49×h=154×h.","Rezolvăm: h=616/154=4."],"r":"✓ h = <strong>4 cm</strong>"}]};
CONTINUT_GEOMETRIE["volumul-piramidei"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Volumul oricărei piramide (cu baza de formă arbitrară) cu aria bazei S_B și înălțimea h.</div>",formula_display:"V = (1/3) · S_B · h",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"70,170 230,170 260,130 100,130\" fill=\"rgba(30,58,95,0.06)\" stroke=\"#1e3a5f\" stroke-width=\"1.6\"/><line x1=\"165\" y1=\"25\" x2=\"70\" y2=\"170\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"165\" y1=\"25\" x2=\"230\" y2=\"170\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"165\" y1=\"25\" x2=\"260\" y2=\"130\" stroke=\"#1e3a5f\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/><line x1=\"165\" y1=\"25\" x2=\"100\" y2=\"130\" stroke=\"#1e3a5f\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/><line x1=\"165\" y1=\"25\" x2=\"165\" y2=\"150\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><text x=\"172\" y=\"95\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">h</text><text x=\"165\" y=\"17\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">vârf</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1e3a5f\">bază S_B</text><text x=\"170\" y=\"208\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">V = (1/3)·S_B·h</text></svg>",intuitiv_text:"Imaginează-ți o cutie în formă de prismă (ca o cutie de carton dreptunghiulară) umplută cu nisip. <span class=\"hl\">Dacă tai cutia în exact 3 piramide de volum egal, fiecare piramidă are o treime din nisipul cutiei</span> - de aceea orice piramidă, cu orice formă a bazei, are volumul o treime din aria bazei ori înălțime.",intuitiv_nota:"Piramida din Giza are baza de aproximativ 230m×230m și înălțimea h≈138m, ceea ce dă un volum V≈230²×138/3≈2,44 milioane m³ - formula este esențială în arhitectură.",exercitii:[{"q":"O piramidă are baza un pătrat cu latura 6 și înălțimea h=10. Calculează volumul.","pasi":["Calculăm aria bazei: S_B=6×6=36.","Aplicăm formula: V=S_B×h/3=36×10/3=120."],"r":"✓ V = <strong>120</strong>"},{"q":"Un tetraedru regulat are toate muchiile egale cu a. Exprimă volumul lui în funcție de a.","pasi":["Baza tetraedrului este un triunghi echilateral cu aria S_B=a²√3/4, iar înălțimea piramidei este h=a√(2/3).","Aplicăm formula: V=S_B×h/3=(a²√3/4)×(a√(2/3))/3.","Simplificăm expresia: V=a³√2/12."],"r":"✓ V = <strong>a³√2/12</strong>"},{"q":"Volumul unei piramide este V=80, iar aria bazei este S_B=40. Găsește înălțimea h.","pasi":["Rearanjăm formula: h=3V/S_B.","Înlocuim: h=3×80/40=240/40=6."],"r":"✓ h = <strong>6</strong>"},{"q":"Adevărat sau fals: dacă dublezi doar înălțimea unei piramide, păstrând aceeași bază, volumul se dublează.","pasi":["Formula V=(1/3)×S_B×h are h la puterea întâi, iar S_B rămâne fixă.","Dublarea lui h dublează întregul produs, deci V se dublează."],"r":"✓ <strong>Adevărat</strong>."},{"q":"Marea Piramidă din Giza are baza pătrată de 230 m × 230 m și înălțimea de aproximativ 138 m. Calculează volumul ei aproximativ.","pasi":["Calculăm aria bazei: S_B=230×230=52 900 m².","Aplicăm formula: V=52 900×138/3=52 900×46=2 433 400."],"r":"✓ V ≈ <strong>2,43 milioane m³</strong>"}]};
CONTINUT_GEOMETRIE["teorema-lui-euler-poliedre"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru orice poliedru convex, dacă V=vârfuri, M=muchii, F=fețe, atunci V−M+F=2.</div>",formula_display:"V − M + F = 2",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"80,170 200,170 200,60 80,60\" fill=\"rgba(30,58,95,0.05)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"140,130 260,130 260,20 140,20\" fill=\"rgba(30,58,95,0.05)\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"80\" y1=\"170\" x2=\"140\" y2=\"130\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"200\" y1=\"170\" x2=\"260\" y2=\"130\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"200\" y1=\"60\" x2=\"260\" y2=\"20\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"80\" y1=\"60\" x2=\"140\" y2=\"20\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><circle cx=\"80\" cy=\"170\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"200\" cy=\"170\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"200\" cy=\"60\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"80\" cy=\"60\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"140\" cy=\"130\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"260\" cy=\"130\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"260\" cy=\"20\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"140\" cy=\"20\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"170\" y=\"200\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1e3a5f\">V=8 vârfuri, M=12 muchii, F=6 fețe</text><text x=\"170\" y=\"10\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">V − M + F = 2 (8−12+6=2)</text></svg>",intuitiv_text:"Ia un cub de jucărie și numără-i colțurile (vârfuri), liniile (muchii) și pătratele (fețe). <span class=\"hl\">Dacă aduni vârfurile cu fețele și scazi muchiile, obții mereu 2</span>, la orice minge sau cutie fără găuri - un cub, o piramidă, un balon de fotbal.",intuitiv_nota:"Euler a descoperit această relație în 1752, iar formula generalizează la suprafețe astfel: χ=V−M+F=2−2g, unde g este genul suprafeței (numărul de „toarte”) - g=0 pentru sferă, g=1 pentru tor.",exercitii:[{"q":"Un cub are V=8 vârfuri și M=12 muchii. Câte fețe F are?","pasi":["Aplicăm formula lui Euler: V−M+F=2.","Înlocuim: 8−12+F=2, deci F=6."],"r":"✓ F = <strong>6</strong> ✔ (un cub are într-adevăr 6 fețe)"},{"q":"Un tetraedru are V=4 vârfuri și F=4 fețe. Câte muchii M are?","pasi":["Aplicăm formula: V−M+F=2.","Înlocuim: 4−M+4=2, deci M=6."],"r":"✓ M = <strong>6</strong>"},{"q":"Ce se întâmplă cu formula V−M+F dacă poliedrul are o „gaură” prin mijloc, ca un covrig (tor)?","pasi":["Pentru poliedrele convexe (fără găuri, ca o sferă deformată), formula dă mereu V−M+F=2.","Dacă poliedrul are o gaură prin mijloc, ca un covrig, formula generală χ=2−2g devine V−M+F=2−2×1=0, nu 2."],"r":"✓ Pentru un poliedru cu o gaură, V−M+F = <strong>0</strong>, nu 2 - forma nu mai este topologic o sferă."},{"q":"Adevărat sau fals: orice poliedru, indiferent de formă, are V−M+F=2.","pasi":["Formula V−M+F=2 este valabilă doar pentru poliedrele convexe, fără găuri (topologic echivalente cu o sferă).","Poliedrele cu găuri au o valoare diferită, dată de formula generală χ=2−2g, unde g este numărul de găuri."],"r":"✓ <strong>Fals</strong>. Formula 2 este valabilă doar pentru poliedre convexe, fără găuri."},{"q":"Un designer 3D construiește un poliedru convex cu F=20 fețe și M=30 muchii. Câte vârfuri V trebuie să aibă?","pasi":["Aplicăm formula lui Euler: V−M+F=2.","Înlocuim: V−30+20=2, deci V=12."],"r":"✓ Poliedrul trebuie să aibă <strong>12 vârfuri</strong> (este chiar un icosaedru)."}]};
CONTINUT_GEOMETRIE["linia-mijlocie-in-triunghi"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Segmentul care unește mijloacele a două laturi ale unui triunghi este paralel cu a treia latură și egal cu jumătate din lungimea ei.</div>",formula_display:"MN ∥ BC și MN = BC/2",diagrama:"<svg viewBox=\"0 0 340 230\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 50,205 300,205\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"110\" y1=\"115\" x2=\"235\" y2=\"115\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"110\" cy=\"115\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"235\" cy=\"115\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"36\" y=\"218\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"218\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"94\" y=\"112\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">M</text><text x=\"240\" y=\"112\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">N</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">MN ∥ BC, MN = BC/2</text></svg>",intuitiv_text:"Imaginează-ți un triunghi de hârtie. Găsește mijlocul a două laturi și unește-le cu un creion. <span class=\"hl\">Linia pe care ai desenat-o este mereu paralelă cu a treia latură și exact pe jumătate din lungimea ei</span> - ca o versiune mai mică a bazei, „plutind” la jumătatea triunghiului.",intuitiv_nota:"Proprietatea se folosește în construcții pentru a determina mijloacele elementelor structurale și în triangulația topografică.",exercitii:[{"q":"Latura BC a unui triunghi are 14 cm. Cât măsoară linia mijlocie MN, paralelă cu BC?","pasi":["Aplicăm formula: MN=BC/2.","Înlocuim: MN=14/2=7."],"r":"✓ MN = <strong>7 cm</strong>"},{"q":"Linia mijlocie a unui triunghi are MN=5,5. Cât măsoară latura BC, cu care este paralelă?","pasi":["Rearanjăm formula: BC=2×MN.","Înlocuim: BC=2×5,5=11."],"r":"✓ BC = <strong>11</strong>"},{"q":"Un triunghi are laturile BC=20, AB=15, AC=13. Calculează perimetrul triunghiului format de cele trei linii mijlocii.","pasi":["Fiecare linie mijlocie este jumătate din latura căreia îi este paralelă: BC/2=10, AB/2=7,5, AC/2=6,5.","Adunăm: P=10+7,5+6,5=24."],"r":"✓ Perimetrul triunghiului mijlociu este <strong>24</strong> - exact jumătate din perimetrul triunghiului mare (48/2=24)."},{"q":"Adevărat sau fals: triunghiul format de cele trei linii mijlocii are aria egală cu jumătate din aria triunghiului inițial.","pasi":["Triunghiul liniilor mijlocii este asemenea cu cel original, cu raportul de similitudine 1:2 (fiecare latură e jumătate).","Raportul ariilor este pătratul raportului laturilor: (1/2)²=1/4, nu 1/2."],"r":"✓ <strong>Fals</strong>. Aria este 1/4 din aria originalului, nu jumătate - ariile scalează cu pătratul raportului laturilor."},{"q":"Un topograf vrea să traseze un drum drept, paralel cu latura BC a unui teren triunghiular, exact la jumătatea distanței dintre laturile AB și AC, fără să măsoare toată latura BC. Cum poate folosi linia mijlocie?","pasi":["Găsește mijloacele laturilor AB și AC ale terenului și le unește cu o linie dreaptă.","Această linie este garantat paralelă cu BC și are exact jumătate din lungimea ei, fără să fie nevoie s-o măsoare direct."],"r":"✓ Linia mijlocie oferă o metodă rapidă de a trasa o linie paralelă la <strong>jumătatea distanței</strong>, fără măsurători suplimentare pe teren."}]};
CONTINUT_GEOMETRIE["linia-mijlocie-in-trapez"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Segmentul care unește mijloacele laturilor ne-paralele ale unui trapez este paralel cu bazele și egal cu media lor aritmetică.</div>",formula_display:"m = (a + b) / 2",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"60,180 280,180 230,50 110,50\" fill=\"rgba(30,58,95,0.06)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"85\" y1=\"115\" x2=\"255\" y2=\"115\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"85\" cy=\"115\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"255\" cy=\"115\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"170\" y=\"196\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">a (bază mare)</text><text x=\"170\" y=\"42\" text-anchor=\"middle\" font-size=\"13\" font-style=\"italic\" fill=\"#1e3a5f\">b (bază mică)</text><text x=\"170\" y=\"108\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">m</text><text x=\"170\" y=\"212\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">m = (a+b)/2</text></svg>",intuitiv_text:"Un trapez are o bază mare jos și una mică sus, ca o felie de tort. <span class=\"hl\">Linia mijlocie este exact „media” dintre cele două baze</span> - nici cât cea mare, nici cât cea mică, ci undeva la mijloc, calculată prin adunarea lor și împărțirea la 2.",intuitiv_nota:"Această proprietate apare în teoria integrării: suma Riemann cu trapeze aproximează integrala prin medii locale.",exercitii:[{"q":"Un trapez are bazele a=6 și b=10. Calculează linia mijlocie m.","pasi":["Aplicăm formula: m=(a+b)/2.","Înlocuim: m=(6+10)/2=8."],"r":"✓ m = <strong>8</strong>"},{"q":"Linia mijlocie a unui trapez este m=7, iar baza mare este a=4. Găsește baza mică b.","pasi":["Pornim de la formulă și înlocuim ce știm: 7=(4+b)/2.","Înmulțim ambele părți cu 2: 14=4+b.","Rezolvăm: b=10."],"r":"✓ b = <strong>10</strong>"},{"q":"Ce se întâmplă cu formula liniei mijlocii dacă trapezul devine dreptunghi, adică cele două baze devin egale (a=b=5)?","pasi":["Înlocuim: m=(5+5)/2=5.","Observăm că linia mijlocie devine egală cu oricare dintre baze - normal, pentru că într-un dreptunghi toate liniile paralele cu bazele au aceeași lungime."],"r":"✓ m = <strong>5</strong>. La dreptunghi (caz special de trapez), linia mijlocie este egală cu baza."},{"q":"Adevărat sau fals: dacă mărești doar baza mică b, păstrând baza mare a fixă, linia mijlocie crește cu aceeași cantitate cu care a crescut b.","pasi":["Formula este m=(a+b)/2.","Dacă b crește cu o cantitate Δ, noua linie mijlocie este m'=(a+b+Δ)/2=m+Δ/2 - deci m crește doar cu jumătate din cât a crescut b."],"r":"✓ <strong>Fals</strong>. Linia mijlocie crește doar cu jumătate din creșterea bazei mici, nu cu toată creșterea."},{"q":"Un teren în formă de trapez are baza mare de 24 m și baza mică de 16 m. Un fermier vrea să tragă un gard exact la mijlocul distanței dintre cele două laturi neparalele, paralel cu bazele. Ce lungime va avea gardul?","pasi":["Acest gard este chiar linia mijlocie a trapezului.","Aplicăm formula: m=(24+16)/2=40/2=20."],"r":"✓ Gardul va avea <strong>20 metri</strong>."}]};
CONTINUT_GEOMETRIE["inegalitatea-triunghiului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice latură a unui triunghi este strict mai mică decât suma celorlalte două și strict mai mare decât valoarea absolută a diferenței lor.</div>",formula_display:"|a − b| &lt; c &lt; a + b",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><polygon points=\"20,170 140,170 90,40\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><text x=\"80\" y=\"186\" text-anchor=\"middle\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">c</text><text x=\"45\" y=\"112\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">a</text><text x=\"122\" y=\"112\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">b</text><text x=\"80\" y=\"205\" text-anchor=\"middle\" font-size=\"11\" fill=\"#2d5a3d\">se poate forma</text><line x1=\"210\" y1=\"170\" x2=\"330\" y2=\"170\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"210\" y1=\"170\" x2=\"245\" y2=\"95\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"330\" y1=\"170\" x2=\"290\" y2=\"115\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"245\" y1=\"95\" x2=\"290\" y2=\"115\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"3,3\"/><text x=\"270\" y=\"205\" text-anchor=\"middle\" font-size=\"11\" fill=\"#a03030\">nu se închide (a+b&lt;c)</text><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">|a−b| &lt; c &lt; a+b</text></svg>",intuitiv_text:"Ai trei bețișoare de lungimi diferite - poți face mereu un triunghi din ele? <span class=\"hl\">Doar dacă cele mai scurte două bețișoare, puse cap la cap, ajung mai departe decât cel mai lung bețișor</span> - altfel nu se închid niciodată într-un triunghi, rămân „deschise” ca o gură căscată.",intuitiv_nota:"În spațiile vectoriale, inegalitatea triunghiului |u+v|≤|u|+|v| este axioma fundamentală a normei și stă la baza geometriei non-euclidiene și a relativității speciale.",exercitii:[{"q":"Pot forma triunghi laturile 3, 4 și 8?","pasi":["Verificăm dacă suma celor mai mici două laturi depășește latura cea mai mare: 3+4=7.","Comparăm: 7 este mai mic decât 8, deci inegalitatea triunghiului nu este respectată."],"r":"✓ <strong>Nu</strong>, aceste trei lungimi nu pot forma un triunghi."},{"q":"Un triunghi are laturile a=5 și b=7. Ce interval de valori poate avea a treia latură, c?","pasi":["Inegalitatea triunghiului cere ca c să fie strict mai mare decât diferența celorlalte două și strict mai mic decât suma lor: |a−b|&lt;c&lt;a+b.","Calculăm diferența: |5−7|=2, iar suma: 5+7=12."],"r":"✓ c poate fi orice număr din intervalul <strong>(2, 12)</strong>."},{"q":"Un triunghi are a=b=6. Care este cea mai mare valoare întreagă posibilă pentru latura c?","pasi":["Din inegalitate, c trebuie să fie strict mai mic decât suma celorlalte două laturi: c&lt;6+6=12.","Cea mai mare valoare întreagă strict mai mică decât 12 este 11."],"r":"✓ c_max = <strong>11</strong>"},{"q":"Adevărat sau fals: un triunghi echilateral cu toate laturile de 4 (adică 4, 4 și 4) respectă inegalitatea triunghiului.","pasi":["Verificăm oricare pereche: 4+4=8, care este mai mare decât a treia latură, 4.","Condiția este îndeplinită pentru toate cele trei perechi de laturi, prin simetrie."],"r":"✓ <strong>Adevărat</strong>, triunghiul echilateral cu latura 4 este valid."},{"q":"Trei sate sunt legate prin drumuri drepte. De la satul A la satul B sunt 12 km, iar de la B la C sunt 5 km. Poate exista un drum direct de la A la C de doar 3 km?","pasi":["Dacă un drum direct AC ar exista, cele trei distanțe ar trebui să respecte inegalitatea triunghiului: AC trebuie să fie mai mare decât |AB−BC|.","Calculăm: |12−5|=7, deci AC trebuie să fie mai mare de 7 km.","Un drum de doar 3 km ar fi mai scurt decât diferența dintre celelalte două distanțe, ceea ce este imposibil geometric."],"r":"✓ <strong>Nu</strong>, este imposibil. Distanța AC trebuie să fie mai mare de 7 km."}]};
CONTINUT_GEOMETRIE["concurenta-medianelor"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Cele trei mediane ale unui triunghi sunt concurente. Punctul de concurență G (centroida) împarte fiecare mediană în raportul 2:1 față de vârf.</div>",formula_display:"AG = (2/3)·mₐ, BG = (2/3)·m_b, CG = (2/3)·m_c",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 60,200 300,200\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"180\" y2=\"200\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><line x1=\"60\" y1=\"200\" x2=\"235\" y2=\"112.5\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><line x1=\"300\" y1=\"200\" x2=\"115\" y2=\"112.5\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><circle cx=\"176.7\" cy=\"141.7\" r=\"3.5\" fill=\"#1a1510\"/><text x=\"183\" y=\"145\" font-size=\"13\" font-weight=\"600\" fill=\"#1a1510\">G</text><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"46\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">AG = (2/3)·mₐ</text></svg>",intuitiv_text:"O mediană este firul care unește un colț al triunghiului cu mijlocul laturii din fața lui. <span class=\"hl\">Dacă tai un triunghi de carton și-l ții pe vârful degetului exact în punctul unde se întâlnesc toate cele trei mediane, se echilibrează perfect</span> - acesta este centrul de greutate, G.",intuitiv_nota:"Centroida are coordonatele G=((x₁+x₂+x₃)/3, (y₁+y₂+y₃)/3), adică media aritmetică a coordonatelor celor trei vârfuri.",exercitii:[{"q":"Mediana dintr-un vârf al unui triunghi are lungimea mₐ=12. Găsește AG (de la vârf la centroidă) și GD (de la centroidă la mijlocul laturii opuse).","pasi":["Centroida G împarte fiecare mediană în raportul 2:1, măsurat de la vârf.","Calculăm: AG=(2/3)×12=8, iar GD=(1/3)×12=4."],"r":"✓ AG = <strong>8</strong>, GD = <strong>4</strong>"},{"q":"Centroida unui triunghi este G=(4,3), iar două dintre vârfuri sunt A=(0,0) și B=(6,0). Găsește al treilea vârf, C.","pasi":["Coordonatele centroidei sunt media aritmetică a coordonatelor celor trei vârfuri: G=((x_A+x_B+x_C)/3, (y_A+y_B+y_C)/3).","Pentru x: 4=(0+6+x_C)/3, deci 12=6+x_C, adică x_C=6.","Pentru y: 3=(0+0+y_C)/3, deci y_C=9."],"r":"✓ C = <strong>(6,9)</strong>"},{"q":"Un triunghi echilateral are latura a. Calculează suma GA²+GB²+GC², unde G este centroida.","pasi":["La triunghiul echilateral, fiecare mediană are lungimea mₐ=a√3/2.","Distanța de la G la fiecare vârf este 2/3 din mediană: GA=GB=GC=(2/3)×(a√3/2)=a√3/3.","Suma este 3×(a√3/3)²=3×(a²×3/9)=3×(a²/3)=a²."],"r":"✓ GA²+GB²+GC² = <strong>a²</strong>"},{"q":"Adevărat sau fals: centrul de greutate G se află întotdeauna la jumătatea fiecărei mediane.","pasi":["G împarte fiecare mediană în raportul 2:1, măsurat de la vârf, nu în două părți egale.","Distanța de la vârf la G este de două ori mai mare decât distanța de la G la mijlocul laturii opuse."],"r":"✓ <strong>Fals</strong>. G este la 2/3 din drum (măsurat de la vârf), nu la jumătate."},{"q":"Trei greutăți egale sunt puse în vârfurile unui triunghi de sârmă, cu vârfurile A(0,0), B(8,0), C(4,6), măsurate în centimetri pe o planșă. Unde trebuie pus suportul pentru ca triunghiul să stea în echilibru perfect?","pasi":["Punctul de echilibru pentru trei greutăți egale, puse în vârfuri, este chiar centrul de greutate (centroida) al triunghiului.","Calculăm: G=((0+8+4)/3, (0+0+6)/3)=(4,2)."],"r":"✓ Suportul trebuie pus în punctul <strong>G(4,2)</strong> pentru echilibru perfect."}]};
CONTINUT_GEOMETRIE["concurenta-inaltimilor"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Cele trei înălțimi ale oricărui triunghi sunt concurente. Punctul de concurență H se numește ortocentru.</div>",formula_display:"H = ortocentru (AD⊥BC, BE⊥AC, CF⊥AB)",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 60,200 300,200\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"170\" y2=\"200\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><line x1=\"60\" y1=\"200\" x2=\"214.6\" y2=\"85.1\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><line x1=\"300\" y1=\"200\" x2=\"128\" y2=\"91.9\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><polyline points=\"162,200 162,192 170,192\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><circle cx=\"170\" cy=\"118.3\" r=\"3.5\" fill=\"#1a1510\"/><text x=\"177\" y=\"122\" font-size=\"13\" font-weight=\"600\" fill=\"#1a1510\">H</text><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"46\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">H = ortocentru</text></svg>",intuitiv_text:"O înălțime este linia care pleacă dintr-un colț al triunghiului și cade în unghi drept pe latura din față. <span class=\"hl\">Cele trei înălțimi se întâlnesc mereu într-un singur punct, numit ortocentru</span> - dar acest punct poate fi înăuntrul, chiar pe vârful, sau chiar în afara triunghiului, în funcție de forma lui.",intuitiv_nota:"Ortocentrul H, centroida G și circumcentrul O sunt coliniare pe dreapta lui Euler, cu OG:GH=1:2.",exercitii:[{"q":"Un triunghi are unghiul de 90° chiar la vârful C. Unde se află ortocentrul H?","pasi":["Într-un triunghi dreptunghic, cele două catete (laturile care formează unghiul drept) sunt deja perpendiculare pe laturile opuse - ele sunt chiar înălțimile din A și din B.","Aceste două înălțimi se întâlnesc exact în vârful unghiului drept, C."],"r":"✓ H coincide cu <strong>vârful drept C</strong>."},{"q":"Un triunghi are un unghi obtuz (mai mare de 90°) la vârful A. Unde se află ortocentrul H?","pasi":["La triunghiurile obtuzunghice, înălțimile din celelalte două vârfuri trebuie prelungite în afara triunghiului ca să se întâlnească.","Punctul lor comun, H, cade deci în exteriorul triunghiului."],"r":"✓ H este <strong>exterior</strong> triunghiului."},{"q":"Adevărat sau fals: în orice triunghi, ortocentrul se află întotdeauna în interiorul triunghiului.","pasi":["Ortocentrul este în interior doar pentru triunghiurile ascuțitunghice (toate unghiurile sub 90°).","Pentru cele dreptunghice, H coincide cu vârful unghiului drept; pentru cele obtuzunghice, H este în exteriorul triunghiului."],"r":"✓ <strong>Fals</strong>. Poziția lui H depinde de forma triunghiului: interior, pe vârf, sau exterior."},{"q":"Un triunghi are vârfurile A(0,0), B(6,0), C(0,4). Găsește ortocentrul H.","pasi":["Laturile AB și AC sunt de-a lungul axelor, deci unghiul din A este drept.","Într-un triunghi dreptunghic, ortocentrul coincide mereu cu vârful unghiului drept.","Deci H=A=(0,0)."],"r":"✓ H = <strong>(0,0)</strong> = A"},{"q":"Un arhitect proiectează un acoperiș triunghiular cu toate unghiurile ascuțite (sub 90°). El vrea să știe dacă punctul unde s-ar întâlni cele trei „grinzi de înălțime” cade în interiorul acoperișului. Ce poate spune, fără calcule exacte?","pasi":["Pentru orice triunghi ascuțitunghic (toate cele trei unghiuri sub 90°), ortocentrul se află mereu în interiorul triunghiului.","Deci arhitectul poate fi sigur că punctul de întâlnire al înălțimilor cade în interiorul acoperișului, fără să facă niciun calcul."],"r":"✓ <strong>Da</strong>, pentru un triunghi ascuțitunghic, ortocentrul este garantat în interior."}]};
CONTINUT_GEOMETRIE["concurenta-bisectoarelor"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Bisectoarele interne ale celor trei unghiuri ale unui triunghi sunt concurente în incentru I, centrul cercului înscris.</div>",formula_display:"r = S/s (raza înscrisă = arie/semiperimetru)",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 55,205 300,205\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"175.2\" y2=\"205\" stroke=\"#c8922a\" stroke-width=\"1.5\"/><line x1=\"55\" y1=\"205\" x2=\"230.6\" y2=\"108.8\" stroke=\"#c8922a\" stroke-width=\"1.5\"/><line x1=\"300\" y1=\"205\" x2=\"115.3\" y2=\"110.6\" stroke=\"#c8922a\" stroke-width=\"1.5\"/><circle cx=\"173.3\" cy=\"140.2\" r=\"3.5\" fill=\"#1a1510\"/><text x=\"180\" y=\"144\" font-size=\"13\" font-weight=\"600\" fill=\"#1a1510\">I</text><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"40\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">I = incentru, r = S/s</text></svg>",intuitiv_text:"O bisectoare taie un colț al triunghiului exact pe din două, ca un cuțit care împarte o felie de pizza în două bucăți egale ca unghi. <span class=\"hl\">Cele trei bisectoare se întâlnesc mereu într-un singur punct, I, care este la fel de departe de toate cele trei laturi</span> - acolo încape cel mai mare cerc posibil în interiorul triunghiului.",intuitiv_nota:"Coordonatele incentrului: I=(a·xₐ+b·x_B+c·x_C)/(a+b+c), ponderate cu lungimile laturilor opuse fiecărui vârf.",exercitii:[{"q":"Un triunghi are laturile a=5, b=7, c=6 și aria S=14,7. Găsește raza cercului înscris, r.","pasi":["Calculăm semiperimetrul: s=(5+7+6)/2=9.","Aplicăm formula: r=S/s=14,7/9≈1,63."],"r":"✓ r ≈ <strong>1,63</strong>"},{"q":"Raza cercului înscris într-un triunghi este r=2, iar semiperimetrul este s=10. Găsește aria S a triunghiului.","pasi":["Rearanjăm formula: S=r×s.","Înlocuim: S=2×10=20."],"r":"✓ S = <strong>20</strong>"},{"q":"Un triunghi echilateral are latura a. Exprimă raza cercului înscris în funcție de a.","pasi":["Semiperimetrul este s=3a/2, iar aria este S=a²√3/4.","Aplicăm formula: r=S/s=(a²√3/4)/(3a/2)=a√3/6."],"r":"✓ r = <strong>a√3/6</strong>"},{"q":"Adevărat sau fals: incentrul I poate fi uneori în afara triunghiului, la fel ca ortocentrul sau circumcentrul unui triunghi obtuzunghic.","pasi":["Incentrul este centrul cercului înscris, tangent la toate cele trei laturi din interior.","Un asemenea cerc nu poate exista decât în interiorul triunghiului, indiferent de forma acestuia (ascuțit, drept sau obtuz)."],"r":"✓ <strong>Fals</strong>. Spre deosebire de ortocentru sau circumcentru, incentrul este mereu în interiorul triunghiului."},{"q":"Compară raza cercului înscris (r) cu raza cercului circumscris (R) pentru un triunghi dreptunghic cu laturile 3, 4, 5.","pasi":["Calculăm aria: S=3×4/2=6, iar semiperimetrul: s=(3+4+5)/2=6.","Raza înscrisă este r=S/s=6/6=1.","Raza circumscrisă, pentru triunghi dreptunghic, este jumătate din ipotenuză: R=5/2=2,5.","Raportul este r/R=1/2,5=0,4."],"r":"✓ r=<strong>1</strong>, R=<strong>2,5</strong>, iar r/R=<strong>0,4</strong> - raza înscrisă este mereu mai mică decât cea circumscrisă."}]};
CONTINUT_GEOMETRIE["teorema-lui-pappus"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Volumul solidului generat prin rotația unei figuri plane în jurul unei axe externe egal cu aria figurii înmulțită cu lungimea drumului parcurs de centroida sa.</div>",formula_display:"V = 2π · ȳ · A",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"310\"><line x1=\"60\" y1=\"15\" x2=\"60\" y2=\"205\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><rect x=\"150\" y=\"90\" width=\"70\" height=\"55\" fill=\"rgba(30,58,95,0.1)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"185\" cy=\"117.5\" r=\"3.5\" fill=\"#c8922a\"/><line x1=\"60\" y1=\"117.5\" x2=\"185\" y2=\"117.5\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><ellipse cx=\"60\" cy=\"117.5\" rx=\"10\" ry=\"30\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/><text x=\"40\" y=\"20\" font-size=\"12\" fill=\"#1e3a5f\">axă</text><text x=\"120\" y=\"112\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c8922a\">ȳ</text><text x=\"188\" y=\"112\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"185\" y=\"165\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\">figura plană</text><text x=\"170\" y=\"216\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">V = 2π · ȳ · A</text></svg>",intuitiv_text:"Imaginează-ți că ai o bucată mică de hârtie colorată (o formă plată) și o rotești foarte repede în jurul unui băț, ca o morișcă învârtită la viteză mare - forma plată „desenează” în aer un corp plin, rotund. <span class=\"hl\">Volumul acelui corp depinde doar de cât de mare este bucata de hârtie (aria ei) și cât de departe este centrul ei de băț</span> - dacă centrul e mai departe de băț, corpul obținut iese mai mare, ca un colac mai gros.",intuitiv_nota:"Pappus din Alexandria (~320 d.Hr.) a demonstrat această teoremă care a rămas necunoscută în Europa până în Renaștere.",exercitii:[{"q":"Un dreptunghi cu laturile 3 și 4 se rotește în jurul unei axe exterioare, la distanța ȳ=5 față de centrul dreptunghiului. Calculează volumul solidului obținut.","pasi":["Calculăm mai întâi aria figurii: A = 3×4 = 12.","Aplicăm formula lui Pappus: V = 2π × ȳ × A = 2π × 5 × 12 = 120π.","Aproximăm numeric: 120π ≈ 376,99."],"r":"✓ V = <strong>120π ≈ 376,99</strong>"},{"q":"Un disc cu raza r=3 (deci aria A=9π) generează, prin rotație în jurul unei axe exterioare, un solid în formă de covrig (tor) cu volumul V=180π². La ce distanță ȳ se află centrul discului față de axă?","pasi":["Calculăm aria discului: A = π×r² = π×3² = 9π.","Pornim de la formula lui Pappus și izolăm ȳ: ȳ = V / (2π×A).","Înlocuim: ȳ = 180π² / (2π×9π) = 180π² / 18π² = 10."],"r":"✓ ȳ = <strong>10</strong>. Aceasta este distanța de la centrul discului la axă, pentru covrigul (torul) obținut."},{"q":"Un semicerc cu raza r=6 are centrul de greutate la distanța ȳ=4r/(3π) de axa care trece prin diametru. Dacă rotești semicercul în jurul acestei axe, ce corp obții și ce volum are?","pasi":["Aria semicercului este A = πr²/2 = π×36/2 = 18π.","Distanța centroidei este ȳ = 4×6/(3π) = 24/(3π) = 8/π.","Aplicăm formula lui Pappus: V = 2π × (8/π) × 18π = 288π."],"r":"✓ Se obține o <strong>sferă</strong>, cu V = <strong>288π</strong> (verificare: (4/3)π×6³ = 288π ✔)"},{"q":"Adevărat sau fals: dacă dublezi distanța ȳ de la centroidă la axă, păstrând aceeași figură (deci aceeași arie A), volumul solidului obținut se dublează și el.","pasi":["Formula lui Pappus este V = 2π×ȳ×A, în care ȳ apare la puterea întâi, înmulțind restul expresiei.","Dacă dublăm ȳ și păstrăm A neschimbat, întregul produs 2π×ȳ×A se dublează, deci și volumul V se dublează."],"r":"✓ <strong>Adevărat</strong>."},{"q":"Un artizan modelează la strung o piesă de lemn: secțiunea transversală are aria A=8 cm², iar centrul ei de greutate se află la 3 cm de axul de rotație al strungului. Ce volum are piesa finită?","pasi":["Aplicăm direct formula lui Pappus: V = 2π × ȳ × A.","Înlocuim: V = 2π × 3 × 8 = 48π.","Aproximăm numeric: 48π ≈ 150,8 cm³."],"r":"✓ Piesa are volumul <strong>48π ≈ 150,8 cm³</strong>."}]};
CONTINUT_GEOMETRIE["teorema-lui-pick"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria unui poligon cu vârfuri în noduri ale rețelei întregi ℤ², cu I puncte interioare și B puncte de contur (incluzând vârfurile).</div>",formula_display:"A = I + B/2 − 1",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"40\" cy=\"26\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"76\" cy=\"26\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"112\" cy=\"26\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"148\" cy=\"26\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"184\" cy=\"26\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"220\" cy=\"26\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"40\" cy=\"62\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"220\" cy=\"62\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"40\" cy=\"98\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"220\" cy=\"98\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"40\" cy=\"134\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"220\" cy=\"134\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"40\" cy=\"170\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"76\" cy=\"170\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"112\" cy=\"170\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"148\" cy=\"170\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"184\" cy=\"170\" r=\"2\" fill=\"#cbd5cf\"/><circle cx=\"220\" cy=\"170\" r=\"2\" fill=\"#cbd5cf\"/><polygon points=\"76,170 184,170 184,62 76,62\" fill=\"rgba(30,58,95,0.07)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"76\" cy=\"62\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"112\" cy=\"62\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"148\" cy=\"62\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"184\" cy=\"62\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"76\" cy=\"170\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"112\" cy=\"170\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"148\" cy=\"170\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"184\" cy=\"170\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"76\" cy=\"98\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"76\" cy=\"134\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"184\" cy=\"98\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"184\" cy=\"134\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"112\" cy=\"98\" r=\"4\" fill=\"#1e3a5f\"/><circle cx=\"148\" cy=\"98\" r=\"4\" fill=\"#1e3a5f\"/><circle cx=\"112\" cy=\"134\" r=\"4\" fill=\"#1e3a5f\"/><circle cx=\"148\" cy=\"134\" r=\"4\" fill=\"#1e3a5f\"/><text x=\"170\" y=\"198\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\">auriu = pe contur (B=12), albastru = interior (I=4)</text><text x=\"170\" y=\"213\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">A = I + B/2 − 1 = 9</text></svg>",intuitiv_text:"Desenează un poligon ale cărui colțuri cad exact pe punctele unei foi de matematică (o rețea de puncte egal depărtate, ca niște cuie într-o placă). <span class=\"hl\">Ca să afli aria, nu mai trebuie să măsori nimic - numeri doar punctele</span>: câte cad chiar pe marginea poligonului și câte sunt înăuntrul lui. Georg Pick a descoperit o rețetă simplă: aria depinde doar de aceste două numărători, niciodată de forma exactă a poligonului.",intuitiv_nota:"Teorema lui Pick este echivalentă cu formula Euler V−E+F=2 pentru grafuri planare și este un caz particular al teoremei Riemann-Roch.",exercitii:[{"q":"Un pătrat cu vârfurile pe noduri de rețea, de laturi 3×3, are B=12 puncte pe contur și I=4 puncte interioare. Calculează aria cu formula lui Pick.","pasi":["Aplicăm formula: A = I + B/2 − 1.","Înlocuim: A = 4 + 12/2 − 1 = 4 + 6 − 1 = 9."],"r":"✓ A = <strong>9</strong> (se potrivește: 3×3=9 ✔)"},{"q":"Un poligon are aria A=10 (calculată deja) și I=7 puncte interioare. Câte puncte de contur B are?","pasi":["Pornim de la formulă și înlocuim ce știm: 10 = 7 + B/2 − 1.","Simplificăm: 10 = 6 + B/2, deci B/2 = 4.","Rezolvăm: B = 8."],"r":"✓ B = <strong>8</strong>"},{"q":"Un poligon are B=12 puncte pe contur, dar niciun punct interior (I=0). Ce arie are?","pasi":["Punem I=0 în formula lui Pick: A = 0 + B/2 − 1 = B/2 − 1.","Înlocuim B=12: A = 12/2 − 1 = 6 − 1 = 5."],"r":"✓ A = <strong>5</strong>. Fără puncte interioare, poligonul are o arie mai mică decât unul cu același contur dar cu puncte în interior."},{"q":"Adevărat sau fals: conform formulei lui Pick, aria unui poligon cu vârfuri pe noduri de rețea este întotdeauna un număr întreg sau un număr întreg plus jumătate (de exemplu 6 sau 6,5), niciodată altceva, precum 6,3.","pasi":["Formula este A = I + B/2 − 1, unde I și B sunt numere întregi, pentru că reprezintă numărători de puncte.","I este întreg, iar B/2 este fie întreg (dacă B e par), fie un întreg plus 1/2 (dacă B e impar); scăderea lui 1 nu schimbă acest tipar.","Așadar A este mereu fie întreg, fie întreg plus jumătate, niciodată un alt fel de zecimală."],"r":"✓ <strong>Adevărat</strong>."},{"q":"Un topograf analizează harta unei ferme printr-o rețea de puncte așezate din metru în metru. Conturul fermei trece exact prin 20 de noduri ale rețelei, iar în interior se află 15 noduri. Câți metri pătrați are ferma?","pasi":["Aplicăm formula lui Pick: A = I + B/2 − 1.","Înlocuim: A = 15 + 20/2 − 1 = 15 + 10 − 1 = 24."],"r":"✓ Ferma are <strong>24 m²</strong>."}]};
CONTINUT_GEOMETRIE["distanta-de-la-punct-la-dreapta"]={definitie:"<div class=\"def-box\"><strong>Formulă:</strong> Distanța de la punctul P(x₀,y₀) la dreapta cu ecuația ax+by+c=0.</div>",formula_display:"d = |ax₀ + by₀ + c| / √(a² + b²)",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"30\" y1=\"195\" x2=\"310\" y2=\"55\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"230\" cy=\"190\" r=\"4\" fill=\"#c8922a\"/><text x=\"240\" y=\"195\" font-size=\"14\" font-weight=\"600\" fill=\"#c8922a\">P</text><line x1=\"230\" y1=\"190\" x2=\"192\" y2=\"120\" stroke=\"#c8922a\" stroke-width=\"1.8\" stroke-dasharray=\"5,3\"/><circle cx=\"192\" cy=\"120\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"170\" y=\"115\" font-size=\"12\" fill=\"#1e3a5f\">Q</text><text x=\"222\" y=\"150\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">d</text><text x=\"60\" y=\"180\" font-size=\"12\" fill=\"#1e3a5f\">dreapta: ax+by+c=0</text><text x=\"170\" y=\"215\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">d = |ax₀+by₀+c| / √(a²+b²)</text></svg>",intuitiv_text:"Dacă vrei să știi cât de departe stă o minge de un perete, nu întinzi rigla pieziș - o ții perfect dreaptă, perpendiculară pe perete, ca să obții cea mai scurtă distanță posibilă. <span class=\"hl\">Formula face exact acest lucru cu numere</span>: pune coordonatele punctului în ecuația dreptei, ia rezultatul fără semn (distanța nu poate fi negativă) și îl împarte la un număr care „îndreaptă” rezultatul, indiferent cum a fost scrisă ecuația dreptei.",intuitiv_nota:"Formula generalizează în orice număr de dimensiuni: distanța de la punct la hiperplan. Apare în algoritmii de clasificare (SVM în machine learning).",exercitii:[{"q":"Calculează distanța de la punctul P(1,2) la dreapta x+y−1=0.","pasi":["Aplicăm formula: d = |1×1+1×2−1| / √(1²+1²).","Calculăm numărătorul: |1+2−1| = |2| = 2.","Calculăm numitorul: √(1+1) = √2.","Împărțim: d = 2/√2 = √2 ≈ 1,41."],"r":"✓ d = <strong>√2 ≈ 1,41</strong>"},{"q":"Punctul P(x,5) se află la distanța d=3 de dreapta 3x+4y−20=0, unde x este un număr pozitiv. Află x.","pasi":["Scriem formula distanței și înlocuim ce știm: 3 = |3x+4×5−20| / √(3²+4²).","Simplificăm numitorul: √(9+16) = 5, deci 3 = |3x+20−20| / 5 = |3x| / 5.","Rezolvăm: |3x| = 15, deci x = 5 (alegem soluția pozitivă, așa cum cere problema)."],"r":"✓ x = <strong>5</strong>. Verificare: |3×5+4×5−20|/5 = |15|/5 = 3 ✔"},{"q":"Punctul P(3,4) și dreapta 3x+4y−25=0. Calculează distanța d și explică ce înseamnă rezultatul obținut.","pasi":["Aplicăm formula: d = |3×3+4×4−25| / √(3²+4²).","Calculăm numărătorul: |9+16−25| = |0| = 0.","Un numărător egal cu 0 înseamnă că punctul verifică exact ecuația dreptei."],"r":"✓ d = <strong>0</strong>. Punctul P se află chiar pe dreaptă - cazul limită al formulei."},{"q":"Adevărat sau fals: dacă înmulțim toți coeficienții a, b, c ai unei drepte cu același număr (de exemplu, cu 2), distanța calculată de la un punct fix la acea dreaptă se schimbă.","pasi":["Dacă înmulțim a, b, c cu un număr k, numărătorul |ax₀+by₀+c| devine |k|×|ax₀+by₀+c|.","Numitorul √(a²+b²) devine √(k²a²+k²b²) = |k|×√(a²+b²).","Factorii |k| se simplifică între numărător și numitor, deci distanța rămâne exact aceeași."],"r":"✓ <strong>Fals</strong>. Distanța nu depinde de cum este „scrisă” ecuația dreptei, doar de dreapta în sine."},{"q":"Un vapor se află în punctul P(0,0). Coasta este aproximată de dreapta 4x+3y−30=0 (coordonatele fiind în kilometri). La ce distanță minimă trece vaporul de coastă?","pasi":["Aplicăm formula distanței, cu (x₀,y₀)=(0,0): d = |4×0+3×0−30| / √(4²+3²).","Calculăm numărătorul: |−30| = 30, iar numitorul: √(16+9) = √25 = 5.","Împărțim: d = 30/5 = 6."],"r":"✓ Vaporul trece la <strong>6 km</strong> distanță minimă de coastă."}]};
CONTINUT_GEOMETRIE["teorema-lui-varignon"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Mijloacele celor patru laturi ale oricărui patrulater (convex, concav sau auto-intersectant) formează un paralelogram.</div>",formula_display:"M₁M₂M₃M₄ paralelogram",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"60,60 260,40 300,190 90,200\" fill=\"rgba(30,58,95,0.06)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"160,50 280,115 195,195 75,130\" fill=\"rgba(200,146,42,0.12)\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"52\" y=\"55\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"264\" y=\"38\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"192\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"76\" y=\"214\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">D</text><circle cx=\"160\" cy=\"50\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"280\" cy=\"115\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"195\" cy=\"195\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"75\" cy=\"130\" r=\"3\" fill=\"#c8922a\"/><text x=\"150\" y=\"42\" font-size=\"11\" fill=\"#c8922a\">M₁</text><text x=\"284\" y=\"112\" font-size=\"11\" fill=\"#c8922a\">M₂</text><text x=\"198\" y=\"210\" font-size=\"11\" fill=\"#c8922a\">M₃</text><text x=\"45\" y=\"132\" font-size=\"11\" fill=\"#c8922a\">M₄</text><text x=\"170\" y=\"218\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">M₁M₂M₃M₄ - paralelogram</text></svg>",intuitiv_text:"Ia patru bețe legate liber la capete, ca să formeze un patrulater strâmb - nu contează cum arată, poate fi oricât de „boțit”. Marchează cu creta mijlocul fiecărui băț și unește aceste puncte între ele cu o sfoară. <span class=\"hl\">Oricât de ciudat ar fi patrulaterul de la care ai pornit, sfoara desenează mereu un paralelogram perfect</span> - cu laturile opuse paralele și egale.",intuitiv_nota:"Paralelogramul Varignon are aria egală cu jumătate din aria patrulaterului original. Proprietatea este folosită în animații și grafică computațională.",exercitii:[{"q":"Patrulaterul ABCD are aria 60 cm². Ce arie are paralelogramul lui Varignon, format din mijloacele laturilor?","pasi":["Proprietate cunoscută: aria paralelogramului lui Varignon este întotdeauna exact jumătate din aria patrulaterului original, indiferent de forma acestuia.","Calculăm: aria Varignon = 60 ÷ 2 = 30 cm²."],"r":"✓ Aria paralelogramului lui Varignon este <strong>30 cm²</strong>."},{"q":"Paralelogramul lui Varignon al unui patrulater ABCD este un dreptunghi. Ce proprietate specială trebuie să aibă diagonalele patrulaterului ABCD?","pasi":["Laturile paralelogramului Varignon sunt paralele cu diagonalele lui ABCD și au jumătate din lungimea lor.","Paralelogramul Varignon este dreptunghi exact atunci când laturile lui sunt perpendiculare între ele.","Cum laturile Varignon sunt paralele cu diagonalele lui ABCD, înseamnă că diagonalele lui ABCD trebuie să fie perpendiculare."],"r":"✓ Diagonalele lui ABCD trebuie să fie <strong>perpendiculare</strong>."},{"q":"Dacă patrulaterul ABCD este chiar un pătrat, ce formă are paralelogramul lui Varignon?","pasi":["Diagonalele unui pătrat sunt egale ca lungime și perpendiculare între ele.","Diagonale egale fac din Varignon un romb, iar diagonale perpendiculare fac din el un dreptunghi.","Un patrulater care este simultan romb și dreptunghi este chiar un pătrat."],"r":"✓ Paralelogramul lui Varignon este tot un <strong>pătrat</strong> (mai mic, rotit cu 45°)."},{"q":"Adevărat sau fals: teorema lui Varignon este valabilă doar pentru patrulatere convexe, nu și pentru cele concave sau auto-intersectate.","pasi":["Demonstrația teoremei folosește doar linia mijlocie în triunghiurile formate de o diagonală, o proprietate valabilă indiferent de forma patrulaterului.","De aceea, mijloacele laturilor formează un paralelogram chiar și pentru patrulatere concave sau care se auto-intersectează (ca un „fluture”)."],"r":"✓ <strong>Fals</strong>. Teorema funcționează pentru orice patrulater: convex, concav sau auto-intersectat."},{"q":"Patru sate sunt așezate în vârfurile unui patrulater oarecare pe hartă. Un topograf marchează exact la mijlocul fiecărui drum dintre sate câte un stâlp și unește stâlpii cu un gard. Ce formă va avea mereu acest gard, indiferent cât de „strâmb” este patrulaterul format de sate?","pasi":["Stâlpii marchează exact mijloacele laturilor patrulaterului format de cele patru sate.","Conform teoremei lui Varignon, unind mijloacele laturilor oricărui patrulater se obține întotdeauna un paralelogram."],"r":"✓ Gardul va forma mereu un <strong>paralelogram</strong>, oricât de neregulat ar fi patrulaterul satelor."}]};
CONTINUT_GEOMETRIE["teorema-lui-stewart"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă în triunghiul ABC, punctul D se află pe BC cu BD=m, DC=n, iar AD=d, atunci relația lui Stewart leagă d de laturile triunghiului.</div>",formula_display:"b²m + c²n = a(mn + d²)",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 60,205 300,205\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"200\" y2=\"205\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"200\" cy=\"205\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"46\" y=\"220\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"220\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"204\" y=\"222\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">D</text><text x=\"128\" y=\"217\" text-anchor=\"middle\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">m</text><text x=\"252\" y=\"217\" text-anchor=\"middle\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">n</text><text x=\"200\" y=\"120\" font-size=\"13\" font-style=\"italic\" fill=\"#c8922a\">d</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">b²m+c²n = a(mn+d²)</text></svg>",intuitiv_text:"Într-un triunghi, o cevian (un fir tras dintr-un colț spre latura opusă) nu are o lungime „liberă” - ea este strâns legată de toate laturile triunghiului. <span class=\"hl\">Teorema lui Stewart este o rețetă care calculează exact lungimea acelui fir</span>, oricât de „strâmb” ar cădea el pe latura opusă, folosind doar cât de departe cade el de fiecare capăt al laturii și lungimile celorlalte două laturi. Mediana (firul spre mijloc) și înălțimea (firul perpendicular) sunt doar cazuri speciale ale acestei rețete mai generale.",intuitiv_nota:"Matthew Stewart a publicat teorema în 1746, iar mediana, bisectoarea și înălțimea oricărui triunghi apar în ea ca simple cazuri particulare.",exercitii:[{"q":"Într-un triunghi cu b=13, c=14, a=15, un punct D pe BC împarte latura în m=BD=6 și n=DC=9. Cât măsoară ceviana AD, notată d?","pasi":["Aplicăm formula lui Stewart: b²m + c²n = a(mn + d²).","Înlocuim valorile: 13²×6 + 14²×9 = 15×(6×9 + d²).","Calculăm partea stângă: 169×6+196×9 = 1014+1764 = 2778.","Calculăm partea dreaptă fără d²: 15×54=810, deci 2778=810+15d², adică 15d²=1968.","Împărțim la 15 și extragem radical: d² ≈ 131,2, deci d ≈ √131,2 ≈ 11,45."],"r":"✓ d ≈ <strong>11,45</strong>"},{"q":"Într-un triunghi cu b=5, c=7, a=6, punctul D este chiar mijlocul laturii BC (deci m=n=3, iar AD este mediana). Cât măsoară mediana d?","pasi":["Cazul m=n corespunde situației în care D este mijlocul lui BC, adică AD este mediana din A.","Aplicăm Stewart cu m=n=3: 5²×3+7²×3 = 6×(3×3+d²).","Calculăm: 75+147=222, iar 6×9=54, deci 222=54+6d², adică 6d²=168, d²=28.","Extragem radical: d=√28=2√7≈5,29 - exact valoarea dată de formula medianei, ceea ce arată că mediana este un caz particular al teoremei lui Stewart."],"r":"✓ d = <strong>2√7 ≈ 5,29</strong> (coincide cu formula medianei)"},{"q":"Într-un triunghi, latura b=8, latura a=10 (împărțită de mediană în m=n=5), iar mediana din A are lungimea d=5. Cât măsoară latura c?","pasi":["Aplicăm formula lui Stewart: b²m + c²n = a(mn + d²).","Înlocuim: 8²×5 + c²×5 = 10×(5×5+5²).","Calculăm partea dreaptă: 10×(25+25)=10×50=500, iar partea stângă: 320+5c².","Rezolvăm: 320+5c²=500, deci 5c²=180, adică c²=36.","Extragem radical: c=6."],"r":"✓ c = <strong>6</strong>"},{"q":"Adevărat sau fals: dacă punctul D este exact mijlocul laturii BC (m=n), formula lui Stewart devine identică cu formula cunoscută a lungimii medianei.","pasi":["Când m=n=a/2, formula lui Stewart b²m+c²n=a(mn+d²) devine (b²+c²)(a/2)=a((a/2)²+d²).","Împărțim ambele părți la a: (b²+c²)/2 = a²/4+d², deci d²=(b²+c²)/2−a²/4=(2b²+2c²−a²)/4.","Aceasta este exact formula cunoscută a medianei, mₐ²=(2b²+2c²−a²)/4."],"r":"✓ <strong>Adevărat</strong>. Mediana este cazul particular m=n al teoremei lui Stewart."},{"q":"Un cort triunghiular are baza BC=10 m. Un țăruș D este bătut pe bază, la 4 m de colțul B și 6 m de colțul C. Laturile înclinate ale cortului sunt AB=9 m și AC=7 m. Ce lungime are frânghia AD, care leagă vârful cortului de țăruș?","pasi":["Identificăm datele pentru formula lui Stewart: a=BC=10, m=BD=4, n=DC=6, c=AB=9, b=AC=7.","Aplicăm formula: b²m+c²n=a(mn+d²).","Înlocuim: 7²×4+9²×6=10×(4×6+d²), adică 196+486=10×(24+d²).","Calculăm: 682=240+10d², deci 10d²=442, adică d²=44,2.","Extragem radical: d=√44,2≈6,65."],"r":"✓ Frânghia AD are aproximativ <strong>6,65 m</strong>."}]};
CONTINUT_GEOMETRIE["cercul-celor-noua-puncte"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Nouă puncte notabile ale oricărui triunghi sunt concicle (situate pe un cerc comun): mijloacele celor trei laturi, picioarele celor trei înălțimi și mijloacele segmentelor de la vârfuri la ortocentru.</div>",formula_display:"R₉ = R/2",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"125\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/><polygon points=\"170,35 75,175 275,160\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"170\" cy=\"125\" r=\"47\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"122.5\" cy=\"105\" r=\"3\" fill=\"#1e3a5f\"/><circle cx=\"222.5\" cy=\"167.5\" r=\"3\" fill=\"#1e3a5f\"/><circle cx=\"172.5\" cy=\"97.5\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"170\" y=\"27\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"60\" y=\"188\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"280\" y=\"172\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"200\" y=\"118\" font-size=\"11\" fill=\"#c8922a\">cercul celor 9 puncte</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">R₉ = R/2</text></svg>",intuitiv_text:"Orice triunghi ascunde un al doilea cerc, mai mic, care trece prin nouă puncte speciale ale lui deodată: mijloacele celor trei laturi, „picioarele” înălțimilor și mijloacele distanțelor de la colțuri până la punctul unde se întâlnesc înălțimile. <span class=\"hl\">Acest cerc ascuns are mereu exact jumătate din raza cercului mare care trece prin cele trei colțuri ale triunghiului</span> - ca o umbră mai mică a cercului mare, perfect la scară 1:2.",intuitiv_nota:"Feuerbach (1822) a demonstrat că cercul celor nouă puncte este intern tangent la cercul înscris și extern tangent la cele trei cercuri exscrise.",exercitii:[{"q":"Un triunghi are cercul circumscris de rază R=10. Cât măsoară raza cercului celor nouă puncte?","pasi":["Raza cercului celor nouă puncte este întotdeauna jumătate din raza cercului circumscris: R₉ = R/2.","Înlocuim: R₉ = 10/2 = 5."],"r":"✓ R₉ = <strong>5</strong>"},{"q":"Cercul celor nouă puncte al unui triunghi are raza R₉=6. Cât măsoară raza R a cercului circumscris?","pasi":["Din relația R₉=R/2 rezultă R=2×R₉.","Înlocuim: R=2×6=12."],"r":"✓ R = <strong>12</strong>"},{"q":"Un triunghi dreptunghic are ipotenuza c=10. Cât măsoară raza R a cercului circumscris și raza R₉ a cercului celor nouă puncte?","pasi":["La triunghiul dreptunghic, ipotenuza este chiar diametrul cercului circumscris, deci R=c/2=10/2=5.","Aplicăm relația generală: R₉=R/2=5/2=2,5."],"r":"✓ R = <strong>5</strong>, R₉ = <strong>2,5</strong>"},{"q":"Adevărat sau fals: centrul cercului celor nouă puncte se află întotdeauna exact la mijlocul segmentului care unește ortocentrul H de circumcentrul O.","pasi":["Centrul cercului celor nouă puncte, notat N₉, se află pe dreapta lui Euler, care trece prin O, centrul de greutate G și ortocentrul H.","Se poate demonstra că N₉ este exact la jumătatea distanței dintre O și H, adică ON₉=N₉H=OH/2."],"r":"✓ <strong>Adevărat</strong>. N₉ este mijlocul segmentului OH."},{"q":"Un arhitect proiectează un vitraliu triunghiular cu raza cercului circumscris R=8 m. Ce rază trebuie să aibă cercul mic care trece prin cele nouă puncte notabile ale triunghiului, pentru a-l desena corect pe planuri?","pasi":["Raza cercului celor nouă puncte este întotdeauna jumătate din raza cercului circumscris: R₉=R/2.","Înlocuim: R₉=8/2=4 m."],"r":"✓ R₉ = <strong>4 m</strong>."}]};
CONTINUT_GEOMETRIE["teorema-tangenta-secanta"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dintr-un punct P exterior unui cerc, o tangentă PT și o secantă care intersectează cercul în A și B satisfac relația PT²=PA·PB.</div>",formula_display:"PT² = PA · PB",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"130\" r=\"70\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.5\"/><circle cx=\"300\" cy=\"130\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"308\" y=\"126\" font-size=\"14\" font-weight=\"600\" fill=\"#c8922a\">P</text><line x1=\"300\" y1=\"130\" x2=\"221\" y2=\"79\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"221\" cy=\"79\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"220\" y=\"68\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">T</text><line x1=\"300\" y1=\"130\" x2=\"110\" y2=\"130\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"200\" cy=\"130\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"110\" cy=\"130\" r=\"3\" fill=\"#c8922a\"/><text x=\"200\" y=\"148\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">A</text><text x=\"106\" y=\"148\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">B</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">PT² = PA · PB</text></svg>",intuitiv_text:"Dintr-un punct aflat în afara unui cerc poți trage o linie care doar „atinge” cercul într-un singur loc (tangenta) sau o linie care „taie” prin cerc, intrând și ieșind prin două puncte (secanta). <span class=\"hl\">Pătratul lungimii tangentei este mereu egal cu produsul distanțelor de la acel punct până la cele două locuri unde secanta intră și iese din cerc</span> - indiferent ce secantă alegi, rezultatul e mereu același număr, ca o „amprentă” a punctului față de cerc.",intuitiv_nota:"Teorema este utilizată în optica geometrică pentru calculul focarelor și în construcțiile geometrice pentru dublarea cubului (imposibil cu rigla și compasul).",exercitii:[{"q":"Dintr-un punct P se duce o tangentă PT și o secantă care taie cercul în A și B, cu PA=4 și PB=9. Cât măsoară tangenta PT?","pasi":["Aplicăm teorema tangentei-secante: PT² = PA × PB.","Înlocuim: PT² = 4×9 = 36.","Extragem radical: PT = √36 = 6."],"r":"✓ PT = <strong>6</strong>"},{"q":"Tangenta din P are PT=8, iar o secantă din același punct taie cercul în A, cu PA=4. Cât măsoară PB, distanța până la al doilea punct de intersecție?","pasi":["Pornim de la aceeași formulă și izolăm PB: PB = PT² / PA.","Înlocuim: PB = 8²/4 = 64/4 = 16."],"r":"✓ PB = <strong>16</strong>"},{"q":"Distanța de la punctul P la centrul O al cercului este PO=13, iar raza cercului este r=5. Cât măsoară tangenta PT dusă din P?","pasi":["Centrul O, punctul de tangență T și punctul P formează un triunghi dreptunghic (OT este perpendiculară pe PT), deci putem aplica Pitagora: PT²+r²=PO².","Rearanjăm: PT²=PO²−r²=13²−5²=169−25=144.","Extragem radical: PT=√144=12."],"r":"✓ PT = <strong>12</strong>. Aceasta este o altă formă a teoremei, legată direct de Pitagora."},{"q":"Adevărat sau fals: dacă tragi două secante diferite din același punct P către un cerc, produsele distanțelor (PA×PB pentru fiecare secantă) sunt întotdeauna egale între ele.","pasi":["Produsul PA×PB pentru orice secantă dusă dintr-un punct fix P depinde doar de poziția lui P față de cerc (așa-numita „putere a punctului”), nu de direcția secantei alese.","De aceea, oricâte secante diferite am trage din același P, produsul distanțelor rămâne mereu același număr."],"r":"✓ <strong>Adevărat</strong>. Acesta este chiar conceptul de „putere a punctului” față de cerc."},{"q":"O barcă este ancorată la distanța de 17 m de centrul unei insule circulare de rază 8 m. Frânghia este întinsă tangent la insulă. Ce lungime are frânghia, de la barcă până la punctul unde atinge insula?","pasi":["Distanța de la barcă la punctul de tangență, raza insulei și distanța până la centru formează un triunghi dreptunghic, la fel ca în cazul tangentei la orice cerc.","Aplicăm relația PT²=PO²−r²: PT²=17²−8²=289−64=225.","Extragem radical: PT=√225=15."],"r":"✓ Frânghia tangentă are <strong>15 m</strong>."}]};
CONTINUT_GEOMETRIE["relatia-lui-euler-in-triunghi"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Distanța OI dintre circumcentrul O (raza R) și incentrul I (raza r) al unui triunghi satisface relația lui Euler.</div>",formula_display:"OI² = R² − 2Rr ⟺ OI² = R(R−2r)",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,30 70,190 290,175\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"177\" cy=\"118\" r=\"88\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/><circle cx=\"177\" cy=\"118\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"183\" y=\"114\" font-size=\"12\" font-weight=\"600\" fill=\"#1e3a5f\">O</text><circle cx=\"185\" cy=\"150\" r=\"40\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.4\"/><circle cx=\"185\" cy=\"150\" r=\"3\" fill=\"#c8922a\"/><text x=\"191\" y=\"147\" font-size=\"12\" font-weight=\"600\" fill=\"#c8922a\">I</text><line x1=\"177\" y1=\"118\" x2=\"185\" y2=\"150\" stroke=\"#333\" stroke-width=\"1.6\"/><text x=\"150\" y=\"128\" font-size=\"11\" fill=\"#333\">OI</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">OI² = R² − 2Rr</text></svg>",intuitiv_text:"Orice triunghi are două cercuri speciale: unul mare, care trece exact prin cele trei colțuri (cercul circumscris), și unul mic, ascuns înăuntru, care atinge cele trei laturi fără să le traverseze (cercul înscris). <span class=\"hl\">Centrele acestor două cercuri nu coincid aproape niciodată</span> - iar relația lui Euler spune exact cât de departe este unul de celălalt, folosind doar cele două raze, R (a cercului mare) și r (a cercului mic). Doar la triunghiul echilateral, perfect simetric, cele două centre se suprapun exact.",intuitiv_nota:"Formula a revoluționat geometria triunghiului în sec. XVIII și a deschis calea spre geometria inversivă și cercurile Apolonius.",exercitii:[{"q":"Un triunghi are R=5 (raza cercului circumscris) și r=2 (raza cercului înscris). Cât măsoară distanța OI dintre cele două centre?","pasi":["Aplicăm relația lui Euler: OI² = R² − 2Rr.","Înlocuim: OI² = 5² − 2×5×2 = 25 − 20 = 5.","Extragem radical: OI = √5 ≈ 2,24."],"r":"✓ OI = <strong>√5 ≈ 2,24</strong>"},{"q":"Ce se întâmplă cu distanța OI într-un triunghi echilateral?","pasi":["La triunghiul echilateral, raza cercului circumscris este R=a/√3, iar raza cercului înscris este r=a√3/6, adică exact r=R/2.","Aplicăm relația lui Euler: OI²=R²−2R×(R/2)=R²−R²=0."],"r":"✓ OI = <strong>0</strong>. Centrele O și I coincid, un semn al simetriei perfecte a triunghiului echilateral."},{"q":"Distanța dintre centre este OI=3, iar raza cercului circumscris este R=7. Cât măsoară raza cercului înscris, r?","pasi":["Pornim de la relația lui Euler și înlocuim ce știm: 9 = 49 − 2×7×r.","Simplificăm: 9 = 49 − 14r, deci 14r = 40.","Rezolvăm: r = 40/14 = 20/7 ≈ 2,86."],"r":"✓ r ≈ <strong>2,86</strong>"},{"q":"Adevărat sau fals: este posibil ca un triunghi să aibă raza cercului circumscris R mai mică decât dublul razei cercului înscris, adică R &lt; 2r.","pasi":["Din relația lui Euler, OI²=R²−2Rr=R(R−2r), iar OI² nu poate fi negativ, pentru că este un pătrat al unei lungimi.","Asta înseamnă că R(R−2r)≥0, deci R−2r≥0, adică R≥2r întotdeauna (inegalitatea lui Euler).","Prin urmare R&lt;2r nu este niciodată posibil pentru un triunghi real."],"r":"✓ <strong>Fals</strong>. Inegalitatea lui Euler garantează mereu R≥2r."},{"q":"Un parc triunghiular are cercul circumscris (limita terenului) de rază R=20 m și un bazin circular înscris de rază r=6 m. Cât de departe este centrul bazinului de centrul cercului care mărginește parcul?","pasi":["Aplicăm relația lui Euler: OI²=R²−2Rr.","Înlocuim: OI²=20²−2×20×6=400−240=160.","Extragem radical: OI=√160=4√10≈12,65."],"r":"✓ Centrele sunt la aproximativ <strong>12,65 m</strong> distanță."}]};
CONTINUT_GEOMETRIE["congruenta-triunghiurilor-lll"]={definitie:"<div class=\"def-box\"><strong>Criteriul LLL (Latură-Latură-Latură):</strong> Dacă cele trei laturi ale unui triunghi sunt respectiv egale cu cele trei laturi ale altui triunghi, atunci cele două triunghiuri sunt congruente.</div>",formula_display:"a₁=a₂, b₁=b₂, c₁=c₂ ⟹ △₁ ≅ △₂",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"60,90 150,90 100,205\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"200,90 300,110 245,215\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"52\" y=\"85\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"154\" y=\"85\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"100\" y=\"222\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"192\" y=\"88\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">D</text><text x=\"304\" y=\"108\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">E</text><text x=\"245\" y=\"232\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">F</text><text x=\"170\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">AB=DE, BC=EF, CA=FD → △ congruente</text></svg>",intuitiv_text:"Ia trei bețișoare de lungimi fixe - de exemplu unul de 5 cm, unul de 7 cm și unul de 8 cm - și încearcă să faci din ele un triunghi. <span class=\"hl\">Oricât ai încerca să-l „împingi” sau să-l „strâmbi”, forma triunghiului rămâne mereu aceeași</span>, pentru că cele trei lungimi fixe nu-i lasă loc de mișcare. De aceea, dacă alt triunghi are exact aceleași trei lungimi, cele două triunghiuri sunt identice (congruente) - poți să le suprapui perfect.",intuitiv_nota:"Acest criteriu explică de ce grinzile și podurile inginerești sunt construite exclusiv din structuri triunghiulare (zăbrele).",exercitii:[{"q":"Triunghiul ABC are laturile 5, 7 și 8. Triunghiul DEF are laturile 7, 8 și 5. Sunt cele două triunghiuri congruente?","pasi":["Comparăm mulțimile de laturi: {5, 7, 8} pentru primul și {7, 8, 5} pentru al doilea - sunt exact aceleași trei lungimi.","Conform criteriului LLL, trei laturi egale garantează congruența, indiferent de ordinea în care le scriem."],"r":"✓ <strong>Da</strong>, △ABC ≅ △DEF prin criteriul LLL."},{"q":"Dacă △ABC ≅ △DEF prin LLL și unghiul A măsoară 50°, cât măsoară unghiul corespunzător D din celălalt triunghi?","pasi":["Congruența înseamnă că cele două triunghiuri se suprapun perfect, deci nu doar laturile, ci și toate unghiurile corespunzătoare sunt egale.","Unghiul D corespunde unghiului A, deci are aceeași măsură."],"r":"✓ Unghiul D = <strong>50°</strong>"},{"q":"Câte triunghiuri diferite (ca formă) se pot construi având laturile fixate la 3, 4 și 5?","pasi":["Conform LLL, trei lungimi de laturi determină o singură formă posibilă de triunghi, până la mutare sau întoarcere (nu poți schimba forma fără să schimbi lungimile)."],"r":"✓ <strong>Unul singur</strong>. Toate triunghiurile cu aceste laturi sunt congruente între ele."},{"q":"Într-un romb ABCD, diagonala AC îl împarte în triunghiurile ABC și ADC. De ce sunt ele congruente?","pasi":["Toate laturile unui romb au aceeași lungime, deci AB = AD și CB = CD.","Diagonala AC este comună ambelor triunghiuri.","Cele trei perechi de laturi fiind egale (AB=AD, CB=CD, AC=AC), se aplică LLL."],"r":"✓ △ABC ≅ △ADC prin <strong>LLL</strong>."},{"q":"Poți construi un triunghi cu laturile 4, 6 și 11?","pasi":["Verificăm inegalitatea triunghiului: suma celor două laturi mai mici trebuie să depășească latura cea mai mare: 4 + 6 = 10.","Dar 10 este mai mic decât 11, deci cele trei bețișoare nu ar ajunge să se închidă într-un triunghi."],"r":"✓ <strong>Nu</strong>. Aceste trei lungimi nu pot forma un triunghi, deci LLL nici nu se poate aplica."}]};
CONTINUT_GEOMETRIE["congruenta-triunghiurilor-lul"]={definitie:"<div class=\"def-box\"><strong>Criteriul LUL (Latură-Unghi-Latură):</strong> Dacă două laturi și unghiul cuprins între ele ale unui triunghi sunt respectiv egale cu două laturi și unghiul cuprins ale altui triunghi, triunghiurile sunt congruente.</div>",formula_display:"a₁=a₂, α₁=α₂, b₁=b₂ ⟹ △₁ ≅ △₂",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"55,200 150,200 60,90\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"210,200 305,200 215,90\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"47\" y=\"214\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"154\" y=\"214\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"52\" y=\"86\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"200\" y=\"214\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">D</text><text x=\"309\" y=\"214\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">E</text><text x=\"207\" y=\"86\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">F</text><path d=\"M 75 200 A 22 22 0 0 1 63 178\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\"/><path d=\"M 230 200 A 22 22 0 0 1 218 178\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.2\"/><text x=\"170\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">AB=DE, ∡A=∡D, AC=DF → △ congruente</text></svg>",intuitiv_text:"Imaginează-ți două bețișoare prinse într-o balama, ca picioarele unui compas deschis la un unghi fix. <span class=\"hl\">Dacă cele două bețișoare au aceleași lungimi și balamaua e deschisă la exact același unghi, capătul liber ajunge mereu în același loc</span> - deci și al treilea segment (care închide triunghiul) va avea aceeași lungime. Important: unghiul trebuie să fie exact cel „prins” între cele două bețișoare, nu oricare altul.",intuitiv_nota:"Rezultatul apare ca Propoziția 4 din Cartea I a Elementelor lui Euclid. Dacă unghiul folosit nu este cel cuprins, congruența nu mai este garantată - cazul LLU poate genera două triunghiuri diferite.",exercitii:[{"q":"În △ABC, AB = 6, AC = 8, iar unghiul dintre ele ∡A = 45°. În △DEF, DE = 6, DF = 8, iar ∡D = 45°. Sunt cele două triunghiuri congruente?","pasi":["Comparăm cele două laturi: AB=DE=6 și AC=DF=8.","Unghiul ∡A este exact unghiul cuprins între laturile AB și AC, la fel cum ∡D este cuprins între DE și DF, și ambele măsoară 45°.","Toate cele trei condiții ale criteriului LUL sunt îndeplinite."],"r":"✓ <strong>Da</strong>, △ABC ≅ △DEF prin LUL."},{"q":"AB = 5, BC = 7, ∡A = 30° în primul triunghi; DE = 5, EF = 7, ∡D = 30° în al doilea. Se poate aplica LUL direct?","pasi":["Unghiul dat, ∡A, este format de laturile AB și AC (nu de AB și BC) - dar noi cunoaștem AB și BC, nu AC.","Deci unghiul cunoscut nu este „cuprins” între cele două laturi cunoscute, ci alăturat doar uneia dintre ele."],"r":"✓ <strong>Nu</strong> direct - unghiul nu este cel cuprins între laturile date (acesta ar fi ∡B)."},{"q":"Într-un triunghi isoscel ABC cu AB = AC, fie M mijlocul laturii BC. Demonstrează că △ABM ≅ △ACM.","pasi":["Avem AB = AC, prin ipoteză.","M fiind mijlocul lui BC, avem BM = CM.","Unghiul ∡B = ∡C, pentru că unghiurile de la baza unui triunghi isoscel sunt egale - dar mai simplu, putem folosi și AM comun cu AB=AC și BM=CM pentru LUL cu unghiul din M."],"r":"✓ △ABM ≅ △ACM prin <strong>LUL</strong> (sau echivalent prin LLL, cu AM latură comună)."},{"q":"Dacă △ABC ≅ △A′B′C′ prin LUL și aria triunghiului ABC este 24 cm², cât este aria triunghiului A′B′C′?","pasi":["Congruența înseamnă că cele două figuri se suprapun perfect, deci au exact aceeași formă și mărime.","Arii identice pentru figuri identice."],"r":"✓ Aria este tot <strong>24 cm²</strong>."},{"q":"Un paralelogram ABCD este tăiat de diagonala AC în două triunghiuri. De ce sunt acestea congruente?","pasi":["În orice paralelogram, laturile opuse sunt egale: AB = CD și AD = BC.","Unghiurile opuse sunt de asemenea egale: ∡B = ∡D.","Cu AB=CD, ∡B=∡D și BC=AD, se aplică LUL (sau LLL, folosind și AC comun)."],"r":"✓ Sunt congruente prin <strong>LUL</strong>."}]};
CONTINUT_GEOMETRIE["congruenta-triunghiurilor-ulu"]={definitie:"<div class=\"def-box\"><strong>Criteriul ULU (Unghi-Latură-Unghi):</strong> Dacă o latură și unghiurile alăturate ei dintr-un triunghi sunt respectiv egale cu o latură și unghiurile alăturate din alt triunghi, triunghiurile sunt congruente.</div>",formula_display:"α₁=α₂, a₁=a₂, β₁=β₂ ⟹ △₁ ≅ △₂",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,40 50,200 300,200\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"50\" y1=\"200\" x2=\"300\" y2=\"200\" stroke=\"#c8922a\" stroke-width=\"3\"/><text x=\"170\" y=\"32\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"36\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"212\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><path d=\"M 90 200 A 30 30 0 0 1 78 176\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.3\"/><path d=\"M 260 200 A 30 30 0 0 0 274 174\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.3\"/><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">BC, ∡B, ∡C fixate → triunghi unic</text></svg>",intuitiv_text:"Doi copii stau pe malul unui râu, la o distanță cunoscută unul de altul (asta e latura fixă). Fiecare privește spre un copac de pe malul celălalt și își notează unghiul la care se uită. <span class=\"hl\">O singură latură și cele două unghiuri de lângă ea sunt de ajuns ca să „prindă” un singur triunghi posibil</span> - nu poți desena alt triunghi cu exact aceleași măsuri. Așa găsesc topografii poziția exactă a unui punct pe care nu-l pot atinge direct.",intuitiv_nota:"Thales din Milet a folosit acest criteriu pentru a calcula distanța până la corăbiile aflate pe mare, măsurând doar de pe țărm.",exercitii:[{"q":"În △ABC, BC = 10, ∡B = 60°, ∡C = 40°. În △DEF, EF = 10, ∡E = 60°, ∡F = 40°. Sunt cele două triunghiuri congruente?","pasi":["Comparăm latura cunoscută: BC = EF = 10.","Comparăm unghiurile alăturate acestei laturi: ∡B = ∡E = 60° și ∡C = ∡F = 40°.","Toate cele trei condiții ale criteriului ULU sunt îndeplinite."],"r":"✓ <strong>Da</strong>, △ABC ≅ △DEF prin ULU."},{"q":"Într-un triunghi, două dintre unghiuri măsoară 50° și 70°. Cât măsoară al treilea unghi, necesar pentru a completa descrierea ULU?","pasi":["Suma unghiurilor unui triunghi este mereu 180°.","Scădem cele două unghiuri cunoscute: 180° − 50° − 70° = 60°."],"r":"✓ Al treilea unghi este <strong>60°</strong>."},{"q":"Avem BC = 8, ∡B = 45°, ∡A = 65°, și EF = 8, ∡E = 45°, ∡D = 65°. Putem folosi ULU deși unul dintre unghiurile date (∡A, respectiv ∡D) nu e „alăturat” direct laturii BC?","pasi":["Calculăm al treilea unghi din fiecare triunghi: ∡C = 180°−45°−65° = 70°, iar ∡F = 70° la fel.","Acum latura BC = 8 are, într-adevăr, ambele unghiuri alăturate cunoscute: 45° și 70° - deci criteriul ULU se aplică, doar că am aflat unul din unghiuri prin calcul."],"r":"✓ <strong>Da</strong>, congruente, după ce completăm al treilea unghi."},{"q":"În triunghiul isoscel ABC (AB = AC), AD este bisectoarea unghiului din A, cu D pe BC. De ce sunt △ABD și △ACD congruente prin ULU?","pasi":["Unghiurile ∡BAD și ∡CAD sunt egale, pentru că AD este bisectoare.","Latura AD este comună celor două triunghiuri mici.","Unghiurile ∡ADB și ∡ADC sunt amândouă de 90° (AD este și înălțime în triunghiul isoscel), deci sunt egale."],"r":"✓ Congruente prin <strong>ULU</strong> (latura AD cu unghiurile de o parte și de alta)."},{"q":"Un topograf măsoară o bază de 50 m între două puncte de observație și unghiurile spre un turn îndepărtat: 40° dintr-un punct și 75° din celălalt. Este poziția turnului determinată unic?","pasi":["Baza de 50 m este o latură fixă, iar cele două unghiuri sunt alăturate ei.","Prin criteriul ULU, o latură cu cele două unghiuri alăturate determină un singur triunghi posibil."],"r":"✓ <strong>Da</strong>, poziția turnului este unic determinată - exact principiul triangulației."}]};
CONTINUT_GEOMETRIE["asemanarea-triunghiurilor-aa"]={definitie:"<div class=\"def-box\"><strong>Criteriul AA (Unghi-Unghi):</strong> Dacă două unghiuri ale unui triunghi sunt respectiv egale cu două unghiuri ale altui triunghi, atunci triunghiurile sunt asemenea (au laturile proporționale).</div>",formula_display:"α₁=α₂, β₁=β₂ ⟹ △₁ ∼ △₂ ⟹ a₁/a₂ = b₁/b₂ = c₁/c₂",diagrama:"<svg viewBox=\"0 0 360 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><polygon points=\"40,205 130,205 40,130\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"170,205 340,205 170,55\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"30\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"134\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"30\" y=\"128\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"160\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">D</text><text x=\"344\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">E</text><text x=\"160\" y=\"53\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">F</text><path d=\"M 60 205 A 20 20 0 0 1 52 189\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\"/><path d=\"M 200 205 A 20 20 0 0 1 190 187\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.2\"/><text x=\"180\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">∡A=∡D, ∡B=∡E → △ABC ∼ △DEF</text></svg>",intuitiv_text:"Gândește-te la o poză mărită la xerox: forma rămâne exact aceeași, doar mărimea se schimbă. <span class=\"hl\">Dacă două triunghiuri au aceeași „formă” - adică două unghiuri egale - atunci sunt ca o poză și mărirea ei</span>, cu toate laturile mărite (sau micșorate) în același raport. Nu mai trebuie să verifici al treilea unghi, pentru că el rezultă automat: dacă două unghiuri sunt egale, și al treilea este obligat să fie egal.",intuitiv_nota:"Thales a folosit asemănarea pentru a măsura înălțimea Marii Piramide din Giza, comparând lungimea umbrei sale cu umbra unui băț vertical.",exercitii:[{"q":"Triunghiul ABC are unghiurile de 50° și 60°. Triunghiul DEF are unghiurile de 50° și 70°. Sunt cele două triunghiuri asemenea?","pasi":["Calculăm al treilea unghi din ABC: 180° − 50° − 60° = 70°.","Triunghiul ABC are deci unghiurile 50°, 60°, 70° - exact aceleași ca DEF."],"r":"✓ <strong>Da</strong>, sunt asemenea prin criteriul AA."},{"q":"Triunghiurile △ABC și △DEF sunt asemenea, cu raportul de mărire k = 3 (DEF e de 3 ori mai mare). Dacă AB = 4, cât măsoară DE?","pasi":["Într-o mărire de 3 ori, fiecare latură a lui DEF este de 3 ori latura corespunzătoare din ABC.","DE = 3 × AB = 3 × 4 = 12."],"r":"✓ DE = <strong>12</strong>"},{"q":"Dacă raportul laturilor a două triunghiuri asemenea este 2, care este raportul ariilor lor?","pasi":["Aria depinde de produsul a două lungimi (bază × înălțime), nu de o singură lungime.","Dacă fiecare lungime se dublează, aria se înmulțește cu 2×2 = 4."],"r":"✓ Raportul ariilor este <strong>4</strong> - pătratul raportului laturilor, nu raportul însuși."},{"q":"O dreaptă paralelă cu baza unui triunghi taie celelalte două laturi, formând un triunghi mai mic. Adevărat sau fals: acest triunghi mic este mereu asemenea cu cel inițial.","pasi":["Unghiul din vârful comun este identic pentru ambele triunghiuri (este chiar același unghi).","Unghiurile formate de dreapta paralelă cu laturile sunt egale cu unghiurile corespunzătoare de la bază, pentru că liniile sunt paralele.","Cu două perechi de unghiuri egale, criteriul AA se aplică."],"r":"✓ <strong>Adevărat</strong>, prin criteriul AA (aceasta este chiar teorema fundamentală a asemănării)."},{"q":"Un stâlp de 2 m înălțime are, la un moment dat, o umbră de 3 m. În același moment, un copac are o umbră de 15 m. Cât de înalt este copacul?","pasi":["Razele soarelui cad practic paralele, deci stâlpul cu umbra lui și copacul cu umbra lui formează triunghiuri asemenea (AA - un unghi comun cu solul, un unghi drept).","Raportul înălțime/umbră este același: h/15 = 2/3.","Rezolvăm: h = 15 × 2/3 = 10."],"r":"✓ Copacul are <strong>10 m</strong> înălțime."}]};
CONTINUT_GEOMETRIE["cercul-circumscris-triunghiului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice triunghi admite un cerc circumscris unic, al cărui centru O se află la intersecția mediatoarelor laturilor. Raza R se calculează prin formula R = abc / (4S).</div>",formula_display:"R = abc / (4S) = a / (2·sin A)",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"120\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.4\"/><polygon points=\"170,25 70,175 288,160\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"170\" cy=\"120\" r=\"3\" fill=\"#c8922a\"/><line x1=\"170\" y1=\"120\" x2=\"170\" y2=\"25\" stroke=\"#c8922a\" stroke-width=\"1.3\" stroke-dasharray=\"4,3\"/><text x=\"178\" y=\"75\" font-size=\"12\" fill=\"#c8922a\">R</text><text x=\"177\" y=\"117\" font-size=\"12\" font-weight=\"600\" fill=\"#c8922a\">O</text><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"56\" y=\"182\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"292\" y=\"155\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">R = abc / (4S)</text></svg>",intuitiv_text:"Imaginează-ți că vrei să pui un cerc exact în jurul unui triunghi, atingând toate cele trei vârfuri, ca o coroană așezată perfect pe trei piscuri. <span class=\"hl\">Există un singur asemenea cerc pentru fiecare triunghi</span>, iar centrul lui O se află mereu la aceeași distanță de toate cele trei vârfuri - distanța aceea se numește rază, R.",intuitiv_nota:"La triunghiurile ascuțitunghice, centrul cercului circumscris se află în interior; la cele dreptunghice, este mijlocul ipotenuzei; la cele obtuzunghice, se află în exterior.",exercitii:[{"q":"Un triunghi dreptunghic are catetele 6 și 8. Cât măsoară raza cercului circumscris?","pasi":["Calculăm ipotenuza cu Pitagora: c = √(6²+8²) = √100 = 10.","La orice triunghi dreptunghic, centrul cercului circumscris este chiar mijlocul ipotenuzei, deci R = c/2 = 5."],"r":"✓ R = <strong>5</strong>"},{"q":"Un triunghi are laturile a = 13, b = 14, c = 15 și aria S = 84. Calculează raza cercului circumscris.","pasi":["Aplicăm formula R = abc / (4S).","Înlocuim: R = (13 × 14 × 15) / (4 × 84) = 2730 / 336.","Simplificăm fracția: R = 65/8 = 8,125."],"r":"✓ R = <strong>8,125</strong>"},{"q":"Un triunghi echilateral are latura a = 6. Cât măsoară raza cercului circumscris, ca fracție din latură?","pasi":["Pentru triunghiul echilateral, formula generală se simplifică la R = a/√3.","Înlocuim: R = 6/√3 = 2√3 ≈ 3,46."],"r":"✓ R = <strong>2√3 ≈ 3,46</strong>"},{"q":"Un triunghi are un unghi de 120°. Unde se află centrul cercului circumscris - în interiorul sau exteriorul triunghiului?","pasi":["Un unghi de 120° este obtuz (mai mare de 90°), deci triunghiul este obtuzunghic.","La triunghiurile obtuzunghice, centrul cercului circumscris cade întotdeauna în afara figurii, „împins” spre partea opusă unghiului obtuz."],"r":"✓ Centrul O se află <strong>în exteriorul triunghiului</strong>."},{"q":"Într-un triunghi, latura a = 10 este opusă unui unghi A = 30°. Găsește raza cercului circumscris folosind legea sinusurilor.","pasi":["Legea sinusurilor leagă direct raza de o latură și unghiul opus: 2R = a/sinA.","Înlocuim: 2R = 10/sin30° = 10/0,5 = 20.","Împărțim la 2: R = 10."],"r":"✓ R = <strong>10</strong>"}]};
CONTINUT_GEOMETRIE["cercul-inscris-triunghiului"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice triunghi admite un cerc înscris unic (tangent interior tuturor celor trei laturi), al cărui centru I este intersecția bisectoarelor unghiurilor. Raza r este dată de r = S / s, unde s este semiperimetrul.</div>",formula_display:"r = S / s, S = s · r",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 55,205 300,205\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"172\" cy=\"160\" r=\"42\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"172\" cy=\"160\" r=\"2.5\" fill=\"#c8922a\"/><text x=\"178\" y=\"164\" font-size=\"12\" font-weight=\"600\" fill=\"#c8922a\">I</text><line x1=\"172\" y1=\"160\" x2=\"172\" y2=\"205\" stroke=\"#c8922a\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/><text x=\"178\" y=\"188\" font-size=\"11\" fill=\"#c8922a\">r</text><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"40\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">r = S / s</text></svg>",intuitiv_text:"Imaginează-ți că vrei să umfli cel mai mare balon rotund posibil în interiorul unui triunghi, fără să-l lași să iasă peste margini. <span class=\"hl\">Balonul atinge toate cele trei laturi în același timp</span>, iar centrul lui, I, se află la aceeași distanță de fiecare latură - distanța aceea este raza cercului înscris, r.",intuitiv_nota:"Centrul cercului înscris (incentrul) este întotdeauna situat în interiorul triunghiului, indiferent de natura unghiurilor sale.",exercitii:[{"q":"Un triunghi dreptunghic are laturile 3, 4, 5. Găsește raza cercului înscris.","pasi":["Calculăm aria: S = 3×4/2 = 6.","Calculăm semiperimetrul: s = (3+4+5)/2 = 6.","Aplicăm formula r = S/s = 6/6 = 1."],"r":"✓ r = <strong>1</strong>"},{"q":"Un triunghi are semiperimetrul s = 15 și raza cercului înscris r = 3. Cât măsoară aria triunghiului?","pasi":["Rearanjăm formula: S = s × r.","Înlocuim: S = 15 × 3 = 45."],"r":"✓ S = <strong>45</strong>"},{"q":"Un triunghi echilateral are latura a. Exprimă raza cercului înscris în funcție de a.","pasi":["Semiperimetrul este s = 3a/2, iar aria este S = a²√3/4.","Aplicăm formula: r = S/s = (a²√3/4) / (3a/2) = a²√3/4 × 2/(3a) = a√3/6."],"r":"✓ r = <strong>a√3/6</strong>"},{"q":"Adevărat sau fals: centrul cercului înscris se poate afla uneori în afara triunghiului, la fel ca centrul cercului circumscris.","pasi":["Cercul înscris este definit ca fiind tangent la toate cele trei laturi, din interior.","Un asemenea cerc nu poate exista decât în interiorul triunghiului, indiferent de forma acestuia (ascuțit, drept sau obtuz)."],"r":"✓ <strong>Fals</strong>. Centrul cercului înscris este mereu în interiorul triunghiului."},{"q":"Compară r și R (raza cercului circumscris) pentru triunghiul dreptunghic 3-4-5.","pasi":["Din exercițiul anterior, r = 1.","Pentru triunghiul dreptunghic, R = ipotenuza/2 = 5/2 = 2,5.","Raportul este r/R = 1/2,5 = 0,4."],"r":"✓ r/R = <strong>0,4</strong>. Raza înscrisă este mereu mai mică decât cea circumscrisă."}]};
CONTINUT_GEOMETRIE["teorema-lui-ptolemeu"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Într-un patrulater inscriptibil (înscris într-un cerc), produsul diagonalelor este egal cu suma produselor laturilor opuse: AC·BD = AB·CD + AD·BC.</div>",formula_display:"AC · BD = AB · CD + AD · BC",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"120\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><polygon points=\"170,25 60,150 200,210 290,90\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"200\" y2=\"210\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><line x1=\"60\" y1=\"150\" x2=\"290\" y2=\"90\" stroke=\"#c8922a\" stroke-width=\"1.6\" stroke-dasharray=\"4,3\"/><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"44\" y=\"153\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"200\" y=\"228\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"296\" y=\"88\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">D</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">AC · BD = AB·CD + AD·BC</text></svg>",intuitiv_text:"Desenează patru puncte pe un cerc și unește-le, formând un patrulater cu colțuri pe cerc. Trage și cele două diagonale, care se încrucișează în mijloc. <span class=\"hl\">Produsul lungimilor celor două diagonale este mereu egal cu suma produselor laturilor opuse</span> - un echilibru ascuns, valabil doar când toate cele patru puncte sunt exact pe același cerc.",intuitiv_nota:"Claudius Ptolemeu (~150 d.Hr.) a utilizat această teoremă în cartea sa „Almagest” pentru a deduce formulele sinusului și cosinusului sumei de unghiuri.",exercitii:[{"q":"Un dreptunghi are laturile 3 și 4. Verifică teorema lui Ptolemeu pentru diagonalele lui.","pasi":["Un dreptunghi este mereu inscriptibil (are toate colțurile pe un cerc), iar cele două diagonale sunt egale, notate d.","Laturile opuse dreptunghiului sunt 3 și 3, respectiv 4 și 4.","Ptolemeu: d×d = 3×3 + 4×4 = 9+16 = 25, deci d = 5 - exact rezultatul lui Pitagora."],"r":"✓ d² = <strong>25</strong>, adică d = 5. Ptolemeu confirmă Pitagora pentru dreptunghi."},{"q":"Un patrulater inscriptibil are laturile AB=2, BC=3, CD=4, DA=5. Cât este produsul diagonalelor AC·BD?","pasi":["Aplicăm direct formula lui Ptolemeu: AC·BD = AB·CD + AD·BC.","Înlocuim: AC·BD = 2×4 + 5×3 = 8+15 = 23."],"r":"✓ AC · BD = <strong>23</strong>"},{"q":"Un pătrat cu latura a. Calculează diagonala d folosind teorema lui Ptolemeu.","pasi":["Toate laturile pătratului sunt egale cu a, iar cele două diagonale sunt egale între ele, notate d.","Ptolemeu: d×d = a×a + a×a = 2a².","Extragem radical: d = a√2."],"r":"✓ d = <strong>a√2</strong> - formula binecunoscută a diagonalei pătratului."},{"q":"Adevărat sau fals: dacă pentru un patrulater oarecare produsul diagonalelor este mai mare decât suma produselor laturilor opuse, patrulaterul poate fi inscriptibil.","pasi":["Inegalitatea lui Ptolemeu spune că, pentru orice patrulater, AC·BD ≤ AB·CD + AD·BC, cu egalitate exact atunci când patrulaterul este inscriptibil.","A avea produsul diagonalelor strict mai mare ar încălca această inegalitate."],"r":"✓ <strong>Fals</strong>. O asemenea situație este imposibilă geometric."},{"q":"Un trapez isoscel inscriptibil are bazele 6 și 14, iar laturile oblice de 5. Calculează diagonala d.","pasi":["Trapezul isoscel este inscriptibil, iar cele două diagonale sunt egale.","Ptolemeu: d² = 6×14 + 5×5 = 84+25 = 109.","Extragem radical: d = √109 ≈ 10,44."],"r":"✓ d ≈ <strong>10,44</strong>"}]};
CONTINUT_GEOMETRIE["teorema-lui-menelaus"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> O dreaptă intersectează dreptele suport ale laturilor BC, CA, AB ale triunghiului ABC în punctele A', B', C' dacă și numai dacă produsul rapoartelor este 1: (A'B/A'C)·(B'C/B'A)·(C'A/C'B) = 1.</div>",formula_display:"(A'B / A'C) · (B'C / B'A) · (C'A / C'B) = 1",diagrama:"<svg viewBox=\"0 0 340 260\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,30 70,215 290,215\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"330\" y1=\"40\" x2=\"120\" y2=\"245\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"235\" cy=\"115\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"120\" cy=\"215\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"205\" cy=\"245\" r=\"3\" fill=\"#c8922a\"/><text x=\"170\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"55\" y=\"228\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"296\" y=\"228\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"240\" y=\"110\" font-size=\"12\" font-weight=\"600\" fill=\"#c8922a\">B′</text><text x=\"106\" y=\"222\" font-size=\"12\" font-weight=\"600\" fill=\"#c8922a\">C′</text><text x=\"208\" y=\"259\" font-size=\"12\" font-weight=\"600\" fill=\"#c8922a\">A′</text><text x=\"170\" y=\"15\" text-anchor=\"middle\" font-size=\"10\" fill=\"#999\" font-style=\"italic\">o secantă taie laturile / prelungirile lor</text></svg>",intuitiv_text:"Trage o linie dreaptă oarecare peste un triunghi, astfel încât să treacă pe lângă toate cele trei laturi ale lui (sau prelungirile lor, ca niște șosele continuate dincolo de intersecție). <span class=\"hl\">Dacă înmulțești cele trei rapoarte în care linia taie laturile, rezultatul este mereu exact 1</span> - dar numai dacă cele trei puncte de tăiere sunt cu adevărat pe aceeași linie dreaptă.",intuitiv_nota:"Menelaus din Alexandria (~100 d.Hr.) a demonstrat această teoremă pentru triunghiuri sferice și plane, fiind fundamentul trigonometriei antice.",exercitii:[{"q":"O secantă taie latura AB în C′ (raport C′A/C′B = 1/2) și latura AC în B′ (raport B′C/B′A = 3/2). În ce raport A′B/A′C taie ea latura BC?","pasi":["Scriem relația lui Menelaus: (C′A/C′B) × (A′B/A′C) × (B′C/B′A) = 1.","Înlocuim ce știm: (1/2) × (A′B/A′C) × (3/2) = 1.","Simplificăm: (A′B/A′C) × (3/4) = 1, deci A′B/A′C = 4/3."],"r":"✓ Raportul este <strong>4/3</strong>"},{"q":"Pe câte laturi (nu prelungiri) poate cădea, cel mult, o secantă Menelaus, ca punctele să rămână coliniare?","pasi":["O secantă adevărată (o linie dreaptă) intră și iese dintr-un triunghi, deci taie efectiv doar o latură „pe interior” și celelalte două pe prelungiri, sau taie toate trei pe prelungiri.","Nu poate tăia toate cele trei laturi chiar „pe interiorul” lor, pentru că ar trebui să intre și să iasă din triunghi de trei ori."],"r":"✓ <strong>1</strong> latură interioară (și 2 prelungiri), sau <strong>3</strong> prelungiri - niciodată 3 laturi interioare."},{"q":"Dacă C′ este mijlocul lui AB (raport 1) și B′C/B′A = 1 de asemenea, ce se întâmplă cu secanta?","pasi":["Înlocuim în relația lui Menelaus: 1 × (A′B/A′C) × 1 = 1, deci A′B/A′C = 1.","Un raport de 1 pentru toate cele trei puncte, situate la mijlocul laturilor, ar corespunde unei linii paralele cu BC (care nu mai taie latura BC la un punct finit din interior)."],"r":"✓ Secanta devine <strong>paralelă cu BC</strong> (cazul limită al teoremei)."},{"q":"Adevărat sau fals: teorema lui Menelaus și teorema lui Ceva verifică exact același lucru - coliniaritatea punctelor.","pasi":["Teorema lui Menelaus testează dacă trei puncte de pe laturi (sau prelungiri) sunt coliniare.","Teorema lui Ceva, deși are o formulă asemănătoare, testează dacă trei ceviene (segmente din vârfuri) sunt concurente - un lucru diferit."],"r":"✓ <strong>Fals</strong>. Menelaus e pentru coliniaritate, Ceva pentru concurență."},{"q":"Calculezi produsul celor trei rapoarte pentru trei puncte alese pe laturile unui triunghi și obții 0,98. Sunt punctele coliniare?","pasi":["Condiția teoremei lui Menelaus cere ca produsul să fie exact 1, nu aproximativ 1.","O valoare de 0,98 arată că punctele nu se află exact pe aceeași dreaptă."],"r":"✓ <strong>Nu</strong>, punctele nu sunt coliniare."}]};
CONTINUT_GEOMETRIE["teorema-lui-ceva"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> În triunghiul ABC, cevienele AA', BB', CC' (unde A'∈BC, B'∈AC, C'∈AB) sunt concurente într-un punct P dacă și numai dacă: (A'B/A'C)·(B'C/B'A)·(C'A/C'B) = 1.</div>",formula_display:"(AF / FB) · (BD / DC) · (CE / EA) = 1",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 55,205 300,205\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"25\" x2=\"200\" y2=\"205\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><line x1=\"55\" y1=\"205\" x2=\"245\" y2=\"70\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><line x1=\"300\" y1=\"205\" x2=\"120\" y2=\"60\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><circle cx=\"182\" cy=\"122\" r=\"3.2\" fill=\"#c8922a\"/><text x=\"188\" y=\"120\" font-size=\"12\" font-weight=\"600\" fill=\"#c8922a\">P</text><text x=\"170\" y=\"17\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"40\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"304\" y=\"218\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">(AF/FB)(BD/DC)(CE/EA)=1</text></svg>",intuitiv_text:"Trage câte un segment din fiecare vârf al triunghiului spre un punct de pe latura opusă (aceste segmente se numesc ceviene). <span class=\"hl\">Cele trei segmente se întâlnesc toate exact în același punct doar dacă produsul celor trei rapoarte pe laturi este 1</span> - altfel, nu se ating deloc într-un singur loc, ci formează un mic triunghi între ele.",intuitiv_nota:"Giovanni Ceva a publicat teorema în 1678, iar din ea rezultă imediat concurența medianelor, înălțimilor și bisectoarelor oricărui triunghi, ca simple cazuri particulare.",exercitii:[{"q":"C′ împarte AB în raport 2:1, iar B′ împarte AC în raport 1:3. Pentru ca cele trei ceviene să fie concurente, în ce raport trebuie să împartă A′ latura BC?","pasi":["Scriem teorema lui Ceva: (C′A/C′B) × (A′B/A′C) × (B′C/B′A) = 1.","Înlocuim: (2/1) × (A′B/A′C) × (3/1) = 1.","Simplificăm: 6 × (A′B/A′C) = 1, deci A′B/A′C = 1/6."],"r":"✓ Raportul este <strong>1/6</strong>"},{"q":"Folosește teorema lui Ceva pentru a arăta că cele trei mediane ale unui triunghi sunt concurente.","pasi":["Fiecare mediană unește un vârf cu mijlocul laturii opuse, deci fiecare din cele trei rapoarte este exact 1 (mijlocul împarte latura în părți egale).","Produsul celor trei rapoarte este 1×1×1 = 1, condiția fiind îndeplinită."],"r":"✓ Sunt <strong>concurente</strong> - punctul lor comun se numește centrul de greutate."},{"q":"Folosește teorema lui Ceva, împreună cu teorema bisectoarei, pentru a arăta că cele trei bisectoare ale unui triunghi sunt concurente.","pasi":["Din teorema bisectoarei știm: A′B/A′C = c/b, B′C/B′A = a/c, C′A/C′B = b/a (unde a, b, c sunt laturile opuse vârfurilor A, B, C).","Înmulțim cele trei rapoarte: (c/b) × (a/c) × (b/a) = (abc)/(abc) = 1."],"r":"✓ Sunt <strong>concurente</strong>, în punctul numit incentru (centrul cercului înscris)."},{"q":"Cum se numește punctul de concurență al celor trei mediane ale unui triunghi?","pasi":["Punctul unde se întâlnesc cele trei mediane este centrul de greutate al triunghiului, notat de obicei G."],"r":"✓ <strong>Centrul de greutate</strong> (G), sau centroidul."},{"q":"Adevărat sau fals: punctul de concurență P din teorema lui Ceva se află întotdeauna în interiorul triunghiului.","pasi":["Dacă unele ceviene „sar” pe prelungirile laturilor (rapoarte negative în convenția cu semn), punctul de concurență poate ieși din triunghi.","De exemplu, ortocentrul unui triunghi obtuzunghic (întâlnirea înălțimilor, un caz particular legat de ceviene) se află în exteriorul triunghiului."],"r":"✓ <strong>Fals</strong>, punctul de concurență poate fi și în exterior, în anumite cazuri."}]};
CONTINUT_GEOMETRIE["dreapta-lui-euler"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> În orice triunghi neechilateral, ortocentrul H, centrul de greutate G și circumcentrul O sunt coliniare. Dreapta care le unește se numește dreapta lui Euler, iar G împarte segmentul OH în raportul OG:GH = 1:2.</div>",formula_display:"O, G, H coliniare; GH = 2 · OG",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,25 60,195 295,175\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"140\" y1=\"70\" x2=\"235\" y2=\"150\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"150\" cy=\"79\" r=\"4\" fill=\"#1e3a5f\"/><text x=\"128\" y=\"72\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">O</text><circle cx=\"183\" cy=\"107\" r=\"4\" fill=\"#c8922a\"/><text x=\"190\" y=\"103\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">G</text><circle cx=\"225\" cy=\"141\" r=\"4\" fill=\"#1e3a5f\"/><text x=\"231\" y=\"137\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">H</text><text x=\"170\" y=\"20\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"46\" y=\"210\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"300\" y=\"190\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">O, G, H coliniare; GH = 2·OG</text></svg>",intuitiv_text:"Un triunghi are mai multe „centre” speciale - centrul de greutate (unde s-ar echilibra pe un deget), centrul cercului circumscris (egal depărtat de vârfuri) și ortocentrul (unde se întâlnesc înălțimile). <span class=\"hl\">Aceste trei puncte, oricât de diferite ar părea, se așază mereu pe aceeași linie dreaptă</span> - ca trei stații pe aceeași cale ferată, cu centrul de greutate exact la o treime de drum dintre celelalte două.",intuitiv_nota:"Leonhard Euler a descoperit această coliniaritate remarcabilă în 1765. În triunghiul echilateral, cele trei puncte coincid (O = G = H), deci dreapta nu este definită.",exercitii:[{"q":"Distanța de la circumcentrul O la centrul de greutate G este OG = 3 cm. Cât măsoară distanța GH, de la G la ortocentrul H?","pasi":["Pe dreapta lui Euler, G împarte segmentul OH astfel încât GH este de două ori mai lungă decât OG.","GH = 2 × OG = 2 × 3 = 6 cm."],"r":"✓ GH = <strong>6 cm</strong>"},{"q":"Distanța totală de la O la H este OH = 12 cm. Găsește OG și GH.","pasi":["OH este împărțit de G în segmente cu raportul 1:2, deci OH = OG + 2·OG = 3·OG.","Rezolvăm: OG = 12/3 = 4 cm, iar GH = 2×4 = 8 cm."],"r":"✓ OG = <strong>4 cm</strong>, GH = <strong>8 cm</strong>"},{"q":"Ce se întâmplă cu dreapta lui Euler pentru un triunghi echilateral?","pasi":["Într-un triunghi echilateral, toate centrele importante (circumcentrul, centrul de greutate, ortocentrul) coincid într-un singur punct, chiar centrul figurii.","Cu un singur punct în loc de trei, nu mai există o dreaptă unică determinată de ele."],"r":"✓ Cele trei puncte <strong>coincid</strong>, iar dreapta lui Euler nu mai este definită unic."},{"q":"Adevărat sau fals: centrul cercului celor nouă puncte se află exact la mijlocul segmentului OH.","pasi":["Este o proprietate suplimentară a dreptei lui Euler: centrul cercului celor nouă puncte, N, satisface ON = NH = OH/2."],"r":"✓ <strong>Adevărat</strong>. N este chiar mijlocul segmentului OH."},{"q":"Într-un triunghi dreptunghic, unde se află ortocentrul H?","pasi":["La triunghiul dreptunghic, două din cele trei înălțimi coincid chiar cu catetele (perpendiculare deja pe laturi).","Punctul lor comun este chiar vârful unghiului drept."],"r":"✓ H este <strong>vârful unghiului drept</strong> - iar dreapta lui Euler unește acest vârf cu mijlocul ipotenuzei (O)."}]};
CONTINUT_GEOMETRIE["aria-poligonului-regulat"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria unui poligon regulat cu n laturi de lungime l și apotema a (distanța de la centru la mijlocul fiecărei laturi) este egală cu jumătatea produsului dintre perimetru și apotemă.</div>",formula_display:"S = (P · a) / 2 = (n · l · a) / 2",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,40 245,80 245,160 170,200 95,160 95,80\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"170\" cy=\"120\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"176\" y=\"116\" font-size=\"12\" fill=\"#1e3a5f\">O</text><line x1=\"170\" y1=\"120\" x2=\"170\" y2=\"200\" stroke=\"#c8922a\" stroke-width=\"1.8\" stroke-dasharray=\"4,3\"/><text x=\"177\" y=\"165\" font-size=\"12\" fill=\"#c8922a\">a</text><line x1=\"170\" y1=\"200\" x2=\"95\" y2=\"160\" stroke=\"#1e3a5f\" stroke-width=\"2.4\"/><text x=\"122\" y=\"190\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">l</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = (n·l·a)/2</text></svg>",intuitiv_text:"Un poligon regulat (cu toate laturile și unghiurile egale) poate fi tăiat, ca un tort, în felii triunghiulare identice, pornind din centru spre fiecare latură. <span class=\"hl\">Aria fiecărei felii se calculează ușor (bază ori înălțime, împărțit la doi), iar aria întregului poligon este suma tuturor feliilor</span> - adică jumătate din perimetru înmulțit cu „înălțimea” fiecărei felii, numită apotemă. Cu cât poligonul are mai multe laturi (mai multe felii, mai subțiri), cu atât seamănă mai mult cu un cerc.",intuitiv_nota:"Arhimede a calculat primele zecimale ale lui π aproximând cercul prin poligoane regulate cu 96 de laturi înscrise și circumscrise.",exercitii:[{"q":"Un hexagon regulat are latura l=6 și apotema a=3√3. Calculează aria.","pasi":["Calculăm perimetrul: P = n×l = 6×6 = 36.","Aplicăm formula: S = (P×a)/2 = (36×3√3)/2 = 54√3.","Aproximăm numeric: 54√3 ≈ 93,53."],"r":"✓ S = <strong>54√3 ≈ 93,53</strong>"},{"q":"Un pătrat (poligon regulat cu n=4) are aria S=64 și apotema a=4. Cât măsoară perimetrul P și latura l?","pasi":["Rearanjăm formula ca să scoatem perimetrul: P = 2S/a.","Înlocuim: P = 2×64/4 = 32.","Latura este perimetrul împărțit la numărul de laturi: l = P/4 = 32/4 = 8."],"r":"✓ P = <strong>32</strong>, l = <strong>8</strong> (verificare: 8²=64 ✔, pătratul e caz particular de poligon regulat)"},{"q":"Un triunghi echilateral (poligon regulat cu n=3) are latura l=6. Găsește apotema și verifică aria cu formula poligonului regulat.","pasi":["Apotema triunghiului echilateral este a = l√3/6 = 6√3/6 = √3.","Calculăm perimetrul: P = 3×6 = 18.","Aplicăm formula: S = (P×a)/2 = (18×√3)/2 = 9√3 ≈ 15,59."],"r":"✓ S = <strong>9√3</strong> (verificare cu formula directă: l²√3/4 = 36√3/4 = 9√3 ✔)"},{"q":"Adevărat sau fals: dacă dublezi numărul de laturi n al unui poligon regulat, păstrând aceeași lungime a laturii l, aria se dublează și ea.","pasi":["Aria depinde de perimetrul P=n×l și de apotema a, iar apotema depinde ea însăși de n (a=l/(2tan(π/n))), nu este un număr fix când n se schimbă.","Dublarea lui n schimbă atât perimetrul cât și apotema, în moduri diferite, deci aria nu se dublează pur și simplu - poligonul devine, de fapt, mult mai mare per total."],"r":"✓ <strong>Fals</strong>. Mărirea numărului de laturi schimbă și apotema, nu doar perimetrul, deci relația nu este o simplă dublare."},{"q":"Dacă numărul de laturi n al unui poligon regulat înscris într-un cerc de rază R crește spre infinit, spre ce formulă tinde aria poligonului?","pasi":["Pe măsură ce n crește, perimetrul P se apropie tot mai mult de circumferința cercului, 2πR, iar apotema a se apropie de raza R.","Formula S=(P×a)/2 tinde deci spre (2πR×R)/2 = πR²."],"r":"✓ Tinde spre <strong>S = πR²</strong> - exact aria cercului."}]};
CONTINUT_GEOMETRIE["teorema-lui-napoleon"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pe fiecare latură a unui triunghi oarecare ABC se construiesc, în exterior, triunghiuri echilaterale. Centrele acestor trei triunghiuri echilaterale formează la rândul lor un triunghi echilateral, numit triunghiul lui Napoleon.</div>",formula_display:"Centrele triunghiurilor echilaterale exterioare formează un triunghi echilateral",diagrama:"<svg viewBox=\"0 0 340 260\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,80 100,190 250,190\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"100,190 250,190 175,240\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\"/><polygon points=\"170,80 100,190 40,110\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\"/><polygon points=\"170,80 250,190 310,110\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\"/><polygon points=\"175,203 83,143 237,143\" fill=\"rgba(200,146,42,0.15)\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"175\" cy=\"203\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"83\" cy=\"143\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"237\" cy=\"143\" r=\"3\" fill=\"#c8922a\"/><text x=\"170\" y=\"72\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"88\" y=\"203\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"256\" y=\"203\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"252\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">triunghiul lui Napoleon (auriu)</text></svg>",intuitiv_text:"Desenează un triunghi oarecare, chiar unul „strâmb”, cu laturi foarte diferite între ele. Pe fiecare latură, construiește în afară câte un triunghi echilateral (cu toate laturile egale) - ca trei acoperișuri identice lipite de pereții triunghiului. <span class=\"hl\">Dacă unești centrele celor trei acoperișuri, obții mereu un triunghi perfect echilateral</span>, oricât de neregulat ar fi fost triunghiul de la care ai pornit.",intuitiv_nota:"Deși atribuită tradițional lui Napoleon Bonaparte, pasionat de geometrie, nu există dovezi istorice solide că el a demonstrat-o; prima apariție tipărită datează din 1825, la câțiva ani după moartea sa.",exercitii:[{"q":"Pe laturile triunghiului ABC se construiesc în exterior trei triunghiuri echilaterale. Ce tip de triunghi obții unind centrele lor?","pasi":["Teorema lui Napoleon afirmă că, indiferent de forma triunghiului ABC, centrele celor trei triunghiuri echilaterale formează întotdeauna un triunghi echilateral."],"r":"✓ Un triunghi <strong>echilateral</strong> (triunghiul lui Napoleon)"},{"q":"Triunghiul ABC este el însuși echilateral. Ce se poate spune despre triunghiul lui Napoleon exterior?","pasi":["Teorema este valabilă pentru orice triunghi, deci și pentru cel echilateral.","Prin simetrie, centrele celor trei triunghiuri echilaterale exterioare formează în acest caz un triunghi echilateral concentric cu ABC."],"r":"✓ Este <strong>echilateral</strong> și concentric cu ABC"},{"q":"Care este centrul de greutate al triunghiului lui Napoleon, comparat cu cel al triunghiului original ABC?","pasi":["O proprietate remarcabilă a teoremei este că centrul de greutate al triunghiului lui Napoleon coincide întotdeauna cu cel al triunghiului ABC."],"r":"✓ <strong>Coincid</strong> - același centru de greutate"},{"q":"Dacă aria triunghiului ABC este T, iar T_e și T_i sunt ariile triunghiurilor lui Napoleon exterior și interior, ce relație există între ele?","pasi":["O identitate cunoscută leagă cele două arii: T_e − T_i = T, adică exact aria triunghiului original."],"r":"✓ T_e − T_i = <strong>T</strong>"},{"q":"Câte triunghiuri echilaterale trebuie construite pentru a obține triunghiul lui Napoleon?","pasi":["Se construiește câte un triunghi echilateral pe fiecare dintre cele 3 laturi ale triunghiului ABC."],"r":"✓ <strong>3</strong> triunghiuri echilaterale, unul pe fiecare latură"}]};
CONTINUT_GEOMETRIE["teorema-lui-morley"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> În orice triunghi ABC, punctele de intersecție ale trisectoarelor adiacente ale celor trei unghiuri (dreptele care împart fiecare unghi în trei părți egale) formează un triunghi echilateral, numit triunghiul lui Morley.</div>",formula_display:"Triunghiul lui Morley (trisectoarele adiacente) este echilateral",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,30 60,200 290,190\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"30\" x2=\"150\" y2=\"150\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><line x1=\"170\" y1=\"30\" x2=\"190\" y2=\"145\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><line x1=\"60\" y1=\"200\" x2=\"150\" y2=\"150\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><line x1=\"60\" y1=\"200\" x2=\"175\" y2=\"170\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><line x1=\"290\" y1=\"190\" x2=\"190\" y2=\"145\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><line x1=\"290\" y1=\"190\" x2=\"175\" y2=\"170\" stroke=\"#1e3a5f\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><polygon points=\"150,150 190,145 175,170\" fill=\"rgba(200,146,42,0.2)\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"170\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"46\" y=\"215\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"296\" y=\"205\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"230\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">triunghiul lui Morley (auriu)</text></svg>",intuitiv_text:"Împarte fiecare unghi al unui triunghi în trei părți egale cu câte două trisectoare, apoi intersectează trisectoarele vecine ale unghiurilor alăturate. <span class=\"hl\">Cele trei puncte obținute formează întotdeauna un triunghi echilateral</span> - un rezultat atât de neașteptat încât a rămas nedescoperit timp de peste 2000 de ani de geometrie euclidiană clasică.",intuitiv_nota:"Descoperită abia în 1899 de Frank Morley, mult după Euclid - semn că trisecția unghiului (imposibilă cu rigla și compasul, conform teoriei lui Galois) ascundea încă rezultate neexplorate.",exercitii:[{"q":"Ce înseamnă a trisecta un unghi al unui triunghi?","pasi":["Trisectarea unui unghi înseamnă împărțirea lui în trei unghiuri congruente, cu ajutorul a două trisectoare."],"r":"✓ Împărțirea unghiului în <strong>3 părți egale</strong>"},{"q":"Unghiul A al unui triunghi este 90°. Ce măsură are fiecare din cele trei părți obținute prin trisectare?","pasi":["Împărțim unghiul la 3, pentru că trisectarea îl desparte în trei părți egale: 90° ÷ 3 = 30°."],"r":"✓ Fiecare parte are <strong>30°</strong>"},{"q":"Adevărat sau fals: forma triunghiului lui Morley depinde de forma triunghiului ABC.","pasi":["Teorema lui Morley garantează că triunghiul format de intersecțiile trisectoarelor adiacente este întotdeauna echilateral, indiferent de forma triunghiului original."],"r":"✓ <strong>Fals</strong> - triunghiul lui Morley este mereu echilateral"},{"q":"Pentru un triunghi echilateral cu raza cercului circumscris R=1, calculează latura triunghiului lui Morley cu formula t=8R·sin(A/3)·sin(B/3)·sin(C/3).","pasi":["Pentru un triunghi echilateral, toate unghiurile sunt egale: A=B=C=60°, deci A/3=20°.","Aplicăm formula lungimii laturii triunghiului Morley: t=8R·sin³20°≈8×1×0,342³≈8×0,0400≈0,320."],"r":"✓ t ≈ <strong>0,320</strong> (mult mai mică decât R)"},{"q":"Câte trisectoare (drepte) se trasează în total pentru a construi triunghiul lui Morley?","pasi":["Fiecare dintre cele 3 unghiuri ale triunghiului este trisectat de 2 drepte, deci în total avem 3×2 = 6 trisectoare."],"r":"✓ <strong>6</strong> trisectoare (2 pentru fiecare unghi)"}]};
CONTINUT_GEOMETRIE["dreapta-lui-simson"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie P un punct de pe cercul circumscris triunghiului ABC. Proiecțiile ortogonale ale lui P pe cele trei laturi (sau prelungirile lor) sunt coliniare. Dreapta obținută se numește dreapta lui Simson a punctului P.</div>",formula_display:"P ∈ cerc circumscris ⟹ proiecțiile pe laturi sunt coliniare",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"120\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\"/><polygon points=\"170,30 85,175 275,165\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"245\" cy=\"45\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"252\" y=\"42\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">P</text><line x1=\"245\" y1=\"45\" x2=\"140\" y2=\"95\" stroke=\"#c8922a\" stroke-width=\"1.4\" stroke-dasharray=\"3,2\"/><line x1=\"245\" y1=\"45\" x2=\"215\" y2=\"170\" stroke=\"#c8922a\" stroke-width=\"1.4\" stroke-dasharray=\"3,2\"/><line x1=\"245\" y1=\"45\" x2=\"245\" y2=\"170\" stroke=\"#c8922a\" stroke-width=\"1.4\" stroke-dasharray=\"3,2\"/><line x1=\"140\" y1=\"95\" x2=\"245\" y2=\"170\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"95\" r=\"2.5\" fill=\"#c8922a\"/><circle cx=\"215\" cy=\"170\" r=\"2.5\" fill=\"#c8922a\"/><circle cx=\"245\" cy=\"170\" r=\"2.5\" fill=\"#c8922a\"/><text x=\"170\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"70\" y=\"188\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"280\" y=\"180\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">dreapta lui Simson (aurie)</text></svg>",intuitiv_text:"Ia orice punct P de pe cercul circumscris unui triunghi și coboară perpendiculare pe cele trei laturi (sau prelungirile lor). <span class=\"hl\">Cele trei picioare ale perpendicularelor cad exact pe aceeași dreaptă</span> - dar numai atunci când P este pe cerc; pentru orice alt punct din plan, cele trei proiecții formează un triunghi (triunghiul pedal), niciodată coliniare.",intuitiv_nota:"Deși poartă numele lui Robert Simson, teorema nu apare de fapt în lucrările sale; demonstrația a fost publicată de William Wallace în 1797, motiv pentru care unii o numesc „dreapta Wallace-Simson”.",exercitii:[{"q":"P este un punct oarecare în planul triunghiului ABC, nu neapărat pe cerc. Sunt proiecțiile ortogonale ale lui P pe cele trei laturi întotdeauna coliniare?","pasi":["Coliniaritatea proiecțiilor (dreapta lui Simson) are loc doar pentru punctele P situate pe cercul circumscris triunghiului ABC."],"r":"✓ <strong>Nu</strong>, doar dacă P se află pe cercul circumscris"},{"q":"P coincide cu vârful A al triunghiului. Ce devine dreapta lui Simson în acest caz particular?","pasi":["Proiecțiile lui A pe laturile AB și AC coincid chiar cu punctul A, deci rămâne relevantă doar proiecția lui A pe BC, adică piciorul înălțimii din A.","Dreapta lui Simson degenerează astfel în chiar această înălțime, din A pe BC."],"r":"✓ Devine <strong>înălțimea din A</strong> pe BC"},{"q":"Câte drepte Simson distincte se pot construi pentru un triunghi ABC dat?","pasi":["Pentru fiecare punct P de pe cercul circumscris există câte o dreaptă Simson, iar cercul are o infinitate de puncte."],"r":"✓ O <strong>infinitate</strong>, câte una pentru fiecare poziție a lui P pe cerc"},{"q":"P₁ și P₂ sunt diametral opuse pe cercul circumscris lui ABC. Ce relație există între dreptele lor Simson?","pasi":["Un rezultat clasic asociat teoremei spune că dreptele Simson ale două puncte diametral opuse sunt perpendiculare."],"r":"✓ Sunt <strong>perpendiculare</strong>"},{"q":"Cine a publicat de fapt prima demonstrație a acestei teoreme, deși ea poartă numele lui Simson?","pasi":["Deși atribuită tradițional lui Robert Simson, demonstrația a fost publicată de fapt de William Wallace, în 1797."],"r":"✓ <strong>William Wallace</strong>, în 1797"}]};
CONTINUT_GEOMETRIE["teorema-lui-desargues"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie triunghiurile ABC și A′B′C′ astfel încât dreptele AA′, BB′, CC′ sunt concurente într-un punct O. Atunci punctele de intersecție ale laturilor omoloage, AB∩A′B′, BC∩B′C′ și CA∩C′A′, sunt coliniare (și reciproc).</div>",formula_display:"AA′,BB′,CC′ concurente ⟺ AB∩A′B′, BC∩B′C′, CA∩C′A′ coliniare",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"30\" r=\"3\" fill=\"#c8922a\"/><text x=\"176\" y=\"26\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">O</text><polygon points=\"130,110 90,190 220,170\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><polygon points=\"150,145 130,195 245,180\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"170\" y1=\"30\" x2=\"150\" y2=\"145\" stroke=\"#c8922a\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/><line x1=\"170\" y1=\"30\" x2=\"130\" y2=\"195\" stroke=\"#c8922a\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/><line x1=\"170\" y1=\"30\" x2=\"245\" y2=\"180\" stroke=\"#c8922a\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/><line x1=\"30\" y1=\"205\" x2=\"310\" y2=\"205\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"30\" y=\"220\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">axa de perspectivitate</text><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">triunghiuri perspective dintr-un punct O</text></svg>",intuitiv_text:"Două triunghiuri „proiectate” unul din celălalt dintr-un punct de vedere comun O au o proprietate ascunsă: <span class=\"hl\">laturile lor omoloage, prelungite, se întâlnesc în trei puncte coliniare</span>. Figura pare să se echilibreze mereu pe o singură dreaptă, chiar dacă cele două triunghiuri au dimensiuni și orientări complet diferite.",intuitiv_nota:"Girard Desargues a fost inginer și arhitect francez; lucrarea sa din 1648 a fost redescoperită abia în secolul XIX și a pus bazele geometriei proiective moderne.",exercitii:[{"q":"Triunghiurile ABC și A′B′C′ au dreptele AA′, BB′, CC′ concurente într-un punct O. Ce garantează teorema lui Desargues despre laturile omoloage?","pasi":["Conform teoremei, cele trei puncte de intersecție AB∩A′B′, BC∩B′C′, CA∩C′A′ sunt coliniare."],"r":"✓ Sunt <strong>coliniare</strong> (triunghiurile sunt perspective dintr-o dreaptă)"},{"q":"Cum se numesc punctul O și dreapta de coliniaritate din teorema lui Desargues?","pasi":["O se numește centrul de perspectivitate, iar dreapta pe care se află cele trei puncte poartă numele de axă de perspectivitate (dreapta lui Desargues)."],"r":"✓ <strong>Centrul</strong> de perspectivitate și <strong>axa</strong> de perspectivitate"},{"q":"Dacă ABC și A′B′C′ sunt omotetice (laturile omoloage paralele), unde se află axa de perspectivitate?","pasi":["Laturile paralele se intersectează la infinit, în sensul geometriei proiective, așa că toate cele trei puncte de intersecție ajung pe dreapta de la infinit."],"r":"✓ Axa este <strong>dreapta de la infinit</strong>"},{"q":"Este teorema lui Desargues valabilă și reciproc: dacă două triunghiuri sunt perspective dintr-o dreaptă, sunt automat perspective dintr-un punct?","pasi":["Da, enunțul complet al teoremei este de tip „dacă și numai dacă” - cele două tipuri de perspectivitate sunt echivalente."],"r":"✓ <strong>Da</strong>, reciproca este de asemenea adevărată"},{"q":"În spațiul tridimensional, dacă cele două triunghiuri se află în plane diferite, de ce este teorema aproape evidentă?","pasi":["Cele două plane ale triunghiurilor se intersectează după o dreaptă comună, iar punctele de intersecție ale laturilor omoloage trebuie să se afle chiar pe această dreaptă."],"r":"✓ Pentru că laturile omoloage se întâlnesc pe <strong>dreapta de intersecție a celor două plane</strong>"}]};
CONTINUT_GEOMETRIE["teorema-lui-pascal-hexagon"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie un hexagon ABCDEF înscris într-o conică (cerc, elipsă, parabolă sau hiperbolă). Punctele de intersecție ale laturilor opuse, AB∩DE, BC∩EF și CD∩FA, sunt coliniare. Dreapta obținută se numește dreapta lui Pascal.</div>",formula_display:"AB∩DE, BC∩EF, CD∩FA coliniare (hexagon înscris în conică)",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"120\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><polygon points=\"170,26 95,55 80,140 130,205 245,195 260,90\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1e3a5f\">A</text><text x=\"78\" y=\"50\" font-size=\"12\" fill=\"#1e3a5f\">B</text><text x=\"60\" y=\"145\" font-size=\"12\" fill=\"#1e3a5f\">C</text><text x=\"122\" y=\"222\" font-size=\"12\" fill=\"#1e3a5f\">D</text><text x=\"250\" y=\"210\" font-size=\"12\" fill=\"#1e3a5f\">E</text><text x=\"266\" y=\"86\" font-size=\"12\" fill=\"#1e3a5f\">F</text><line x1=\"20\" y1=\"200\" x2=\"320\" y2=\"160\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"5,3\"/><text x=\"170\" y=\"230\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">dreapta lui Pascal (aurie)</text></svg>",intuitiv_text:"Înscrie un hexagon oarecare (chiar neregulat) într-un cerc sau o elipsă. Prelungește laturile opuse până se întâlnesc. <span class=\"hl\">Cele trei puncte de întâlnire cad mereu pe aceeași dreaptă</span> - „dreapta lui Pascal” - indiferent cât de neregulat este hexagonul.",intuitiv_nota:"Pascal a descoperit acest rezultat la doar 16 ani, în 1640, numindu-l „hexagonul mistic” (Hexagrammum Mysticum). Este un caz particular al unor rezultate mai generale din geometria algebrică.",exercitii:[{"q":"Hexagonul ABCDEF este înscris într-un cerc. Care sunt cele trei perechi de laturi opuse ale căror intersecții trebuie să fie coliniare?","pasi":["Laturile opuse ale unui hexagon ABCDEF sunt: AB și DE, BC și EF, CD și FA."],"r":"✓ <strong>AB∩DE, BC∩EF, CD∩FA</strong>"},{"q":"Teorema lui Pascal se aplică doar cercurilor sau oricărei conice?","pasi":["Teorema este valabilă pentru orice conică nedegenerată: cerc, elipsă, parabolă sau hiperbolă."],"r":"✓ Pentru <strong>orice conică</strong> - cercul este doar un caz particular"},{"q":"Câte puncte de intersecție coliniare rezultă din aplicarea teoremei lui Pascal unui hexagon înscris?","pasi":["Se obțin exact 3 puncte de intersecție, câte unul pentru fiecare pereche de laturi opuse, și acestea sunt coliniare."],"r":"✓ <strong>3</strong> puncte, toate pe dreapta lui Pascal"},{"q":"Cum se numește teorema duală, referitoare la un hexagon circumscris unei conice (diagonalele lui principale)?","pasi":["Dualul proiectiv al teoremei lui Pascal este teorema lui Brianchon: diagonalele principale ale unui hexagon circumscris unei conice sunt concurente."],"r":"✓ <strong>Teorema lui Brianchon</strong>"},{"q":"Dacă hexagonul degenerează astfel încât două vârfuri consecutive coincid, ce înlocuiește latura dintre ele în teoremă?","pasi":["Latura dintre cele două vârfuri coincidente devine tangenta la conică în acel punct."],"r":"✓ Este înlocuită de <strong>tangenta la conică</strong> în acel punct"}]};
CONTINUT_GEOMETRIE["formula-lui-brahmagupta"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru un patrulater inscriptibil (ciclic) cu laturile a, b, c, d și semiperimetrul s=(a+b+c+d)/2, aria se calculează direct din lungimile laturilor, generalizând formula lui Heron pentru triunghi.</div>",formula_display:"S = √((s−a)(s−b)(s−c)(s−d)), s = (a+b+c+d)/2",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><circle cx=\"170\" cy=\"120\" r=\"95\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/><polygon points=\"170,28 260,100 210,205 90,175\" fill=\"rgba(30,58,95,0.08)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><text x=\"170\" y=\"20\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"268\" y=\"98\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"212\" y=\"222\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"64\" y=\"180\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">D</text><text x=\"222\" y=\"60\" font-size=\"12\" font-style=\"italic\" fill=\"#c8922a\">a</text><text x=\"243\" y=\"155\" font-size=\"12\" font-style=\"italic\" fill=\"#c8922a\">b</text><text x=\"148\" y=\"196\" font-size=\"12\" font-style=\"italic\" fill=\"#c8922a\">c</text><text x=\"122\" y=\"98\" font-size=\"12\" font-style=\"italic\" fill=\"#c8922a\">d</text><text x=\"170\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S = √((s−a)(s−b)(s−c)(s−d))</text></svg>",intuitiv_text:"Formula lui Heron calculează aria unui triunghi doar din cele trei laturi, fără să măsori nimic altceva. Formula lui Brahmagupta face același truc pentru un patrulater - <span class=\"hl\">dar funcționează perfect doar dacă toate cele patru colțuri ale lui ating aceeași margine rotundă a unui cerc</span> (se numește patrulater „inscriptibil”). Dintre toate patrulaterele cu aceleași patru laturi, cel care se potrivește pe un cerc are mereu cea mai mare arie posibilă.",intuitiv_nota:"Brahmagupta, matematician indian din secolul VII, a introdus și regulile de calcul cu zero și numere negative; formula sa generalizează Heron cu peste 1000 de ani înainte ca legătura dintre ele să fie recunoscută formal.",exercitii:[{"q":"Un patrulater inscriptibil are laturile a=3, b=4, c=5, d=6. Calculează aria cu formula lui Brahmagupta.","pasi":["Calculăm semiperimetrul: s=(3+4+5+6)/2=9.","Aplicăm formula: S=√((9−3)(9−4)(9−5)(9−6))=√(6×5×4×3)=√360.","Simplificăm radicalul: S=6√10≈18,97."],"r":"✓ S = <strong>6√10 ≈ 18,97</strong>"},{"q":"Un dreptunghi cu laturile 6 și 8 este un caz particular de patrulater inscriptibil (orice dreptunghi se poate înscrie într-un cerc). Verifică formula lui Brahmagupta pentru el.","pasi":["Laturile sunt a=6,b=8,c=6,d=8, deci semiperimetrul este s=(6+8+6+8)/2=14.","Aplicăm formula: S=√((14−6)(14−8)(14−6)(14−8))=√(8×6×8×6)=√2304.","Extragem radical: S=48."],"r":"✓ S = <strong>48</strong> (coincide cu aria dreptunghiului: 6×8=48 ✔)"},{"q":"Dacă latura d tinde spre 0, patrulaterul degenerează într-un triunghi cu laturile a, b, c. În ce formulă se transformă formula lui Brahmagupta?","pasi":["Pentru d=0, semiperimetrul devine s=(a+b+c)/2, iar factorul (s−d) devine pur și simplu s.","Formula S=√((s−a)(s−b)(s−c)(s−d)) devine S=√(s(s−a)(s−b)(s−c))."],"r":"✓ Devine <strong>formula lui Heron</strong> pentru triunghi."},{"q":"Adevărat sau fals: formula lui Brahmagupta dă aria corectă pentru orice patrulater cu laturile a, b, c, d, chiar dacă acesta nu poate fi înscris într-un cerc.","pasi":["Formula lui Brahmagupta presupune că patrulaterul este inscriptibil (înscris într-un cerc) - doar în acest caz relația dintre unghiurile opuse permite simplificarea formulei generale a ariei.","Pentru un patrulater cu aceleași patru laturi, dar care nu este inscriptibil, aria reală este mai mică decât valoarea dată de formulă."],"r":"✓ <strong>Fals</strong>. Formula este validă doar pentru patrulatere inscriptibile; pentru altele, ea supraestimează aria reală."},{"q":"Un teren cu patru laturi de 7 m, 9 m, 12 m și 8 m poate fi înscris exact într-un gard circular (este inscriptibil). Câți metri pătrați are terenul?","pasi":["Calculăm semiperimetrul: s=(7+9+12+8)/2=18.","Aplicăm formula: S=√((18−7)(18−9)(18−12)(18−8))=√(11×9×6×10)=√5940.","Aproximăm numeric: S≈77,07."],"r":"✓ Terenul are aproximativ <strong>77,07 m²</strong>."}]};
CONTINUT_GEOMETRIE["teorema-unghiului-exterior"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Unghiul exterior al unui triunghi, format prin prelungirea unei laturi dincolo de un vârf, este egal cu suma celor două unghiuri interioare neadiacente lui (cele care nu ating acel vârf).</div>",formula_display:"∡ exterior = suma celor 2 unghiuri interioare neadiacente",diagrama:"<svg viewBox=\"0 0 340 220\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,30 70,190 260,190\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><line x1=\"70\" y1=\"190\" x2=\"320\" y2=\"190\" stroke=\"#1e3a5f\" stroke-width=\"1.4\" stroke-dasharray=\"4,3\"/><text x=\"170\" y=\"22\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"56\" y=\"204\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"264\" y=\"204\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"322\" y=\"204\" font-size=\"14\" font-weight=\"600\" fill=\"#1e3a5f\">D</text><path d=\"M 240 190 A 20 20 0 0 1 254 174\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.6\"/><text x=\"255\" y=\"165\" font-size=\"12\" fill=\"#c8922a\">ext</text><text x=\"180\" y=\"55\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">A</text><text x=\"100\" y=\"180\" font-size=\"12\" font-style=\"italic\" fill=\"#1e3a5f\">B</text><text x=\"170\" y=\"212\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">∡ext(C) = ∡A + ∡B</text></svg>",intuitiv_text:"Când prelungești o latură a unui triunghi dincolo de un colț, apare un unghi nou, aflat „în afara” triunghiului. <span class=\"hl\">Acest unghi exterior nu este ceva nou și independent - este mereu exact egal cu suma celorlalte două colțuri ale triunghiului, cele care nu sunt lângă el</span>. E ca și cum cele două colțuri îndepărtate și-ar „trimite” măsura lor, adunată, până la colțul din afară.",intuitiv_nota:"Rezultat din Cartea I a Elementelor lui Euclid (propoziția 32); este adesea mai rapid de aplicat decât teorema sumei unghiurilor, mai ales în probleme cu unghiuri exterioare sau transversale.",exercitii:[{"q":"Cele două unghiuri interioare neadiacente unui unghi exterior sunt 50° și 65°. Cât măsoară unghiul exterior?","pasi":["Aplicăm teorema unghiului exterior: unghiul exterior este suma celor două unghiuri neadiacente.","Calculăm: unghi exterior = 50°+65° = 115°."],"r":"✓ Unghiul exterior este <strong>115°</strong>"},{"q":"Unghiul exterior la vârful C al unui triunghi este 130°, iar unghiul din A este 70°. Cât măsoară unghiul din B?","pasi":["Pornim de la teoremă: unghiul exterior din C este suma unghiurilor din A și B: 130°=70°+β.","Rezolvăm: β=130°−70°=60°."],"r":"✓ β = <strong>60°</strong>"},{"q":"Un triunghi isoscel are unghiurile de la bază egale, de 50° fiecare. Cât măsoară unghiul exterior la vârful de sus?","pasi":["Unghiul exterior de la vârf este suma celor două unghiuri de la bază, care sunt neadiacente lui.","Calculăm: unghi exterior = 50°+50° = 100°."],"r":"✓ Unghiul exterior este <strong>100°</strong>"},{"q":"Adevărat sau fals: unghiul exterior al unui triunghi poate fi mai mic decât oricare dintre cele două unghiuri interioare neadiacente lui.","pasi":["Unghiul exterior este egal cu suma celor două unghiuri interioare neadiacente: ∡ext = ∡A+∡B.","Cum ambele unghiuri A și B au măsuri pozitive, suma lor este întotdeauna mai mare decât fiecare termen luat separat.","Deci unghiul exterior este întotdeauna mai mare decât oricare dintre cele două unghiuri neadiacente, niciodată mai mic."],"r":"✓ <strong>Fals</strong>. Unghiul exterior este mereu mai mare decât fiecare dintre cele două unghiuri interioare neadiacente."},{"q":"Un drum cotește la punctul C. Dacă direcția de mers se abate cu 35° față de traseul BC atunci când pleci din B, iar la sosire în A se abate cu 50°, cu ce unghi trebuie să cotească șoferul exact în C?","pasi":["Unghiul cu care trebuie să cotească șoferul în C este chiar unghiul exterior al triunghiului ABC în acel vârf.","Aplicăm teorema: unghiul exterior este suma celor două unghiuri neadiacente, cele din B și din A: 35°+50°=85°."],"r":"✓ Șoferul trebuie să cotească cu <strong>85°</strong>."}]};
CONTINUT_GEOMETRIE["aria-prin-coordonate"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Aria unui triunghi cu vârfurile A(x₁,y₁), B(x₂,y₂), C(x₃,y₃) date prin coordonate carteziene se calculează direct, fără a folosi unghiuri sau înălțimi.</div>",formula_display:"S = ½|x₁(y₂−y₃)+x₂(y₃−y₁)+x₃(y₁−y₂)|",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"200\" x2=\"320\" y2=\"200\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><line x1=\"60\" y1=\"220\" x2=\"60\" y2=\"20\" stroke=\"#1e3a5f\" stroke-width=\"1.3\"/><polygon points=\"60,200 220,200 60,80\" fill=\"rgba(30,58,95,0.1)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"60\" cy=\"200\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"220\" cy=\"200\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"60\" cy=\"80\" r=\"3\" fill=\"#c8922a\"/><text x=\"46\" y=\"214\" font-size=\"12\" fill=\"#1e3a5f\">A(0,0)</text><text x=\"222\" y=\"214\" font-size=\"12\" fill=\"#1e3a5f\">B(4,0)</text><text x=\"20\" y=\"84\" font-size=\"12\" fill=\"#1e3a5f\">C(0,3)</text><text x=\"316\" y=\"214\" font-size=\"11\" fill=\"#1e3a5f\">x</text><text x=\"52\" y=\"24\" font-size=\"11\" fill=\"#1e3a5f\">y</text><text x=\"170\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\" font-family=\"monospace\">S=½|x₁(y₂−y₃)+x₂(y₃−y₁)+x₃(y₁−y₂)|</text></svg>",intuitiv_text:"Dacă știi exact pe hartă unde sunt cele trei colțuri ale unui triunghi (adică perechile lor de numere x și y), nu mai trebuie să măsori nimic cu rigla pentru a-i afla aria. <span class=\"hl\">O singură formulă „citește” direct aria din cele trei perechi de coordonate</span>, ca un GPS care calculează suprafața unui teren doar din pozițiile colțurilor lui. Semnul absolut din formulă există pentru că, dacă numeri colțurile în sens invers, rezultatul brut iese cu minus - dar aria nu poate fi niciodată negativă.",intuitiv_nota:"Este cazul particular pentru 3 puncte al formulei șiretului (shoelace formula), valabilă pentru orice poligon și esențială în grafica pe calculator și sistemele GIS.",exercitii:[{"q":"Un triunghi are vârfurile A(0,0), B(4,0), C(0,3). Calculează aria triunghiului ABC.","pasi":["Aplicăm formula ariei prin coordonate: S=½|x₁(y₂−y₃)+x₂(y₃−y₁)+x₃(y₁−y₂)|.","Înlocuim coordonatele: S=½|0×(0−3)+4×(3−0)+0×(0−0)|.","Calculăm: S=½|0+12+0|=½×12=6."],"r":"✓ S = <strong>6</strong>"},{"q":"Vârfurile A(0,0), B(5,0), C(2,y) formează un triunghi cu aria 10. Găsește valoarea lui y.","pasi":["Aplicăm formula: S=½|0×(0−y)+5×(y−0)+2×(0−0)|=½×5y=2,5y.","Punem această expresie egală cu aria dată: 2,5y=10.","Rezolvăm: y=10/2,5=4."],"r":"✓ y = <strong>4</strong>"},{"q":"Punctele A(0,0), B(2,2), C(4,4) sunt considerate vârfurile unui triunghi. Ce se poate spune despre aceste trei puncte, după ce calculezi aria?","pasi":["Aplicăm formula: S=½|0×(2−4)+2×(4−0)+4×(0−2)|.","Calculăm: S=½|0+8−8|=½×0=0.","O arie egală cu 0 înseamnă că cele trei puncte nu formează de fapt un triunghi propriu-zis."],"r":"✓ Aria este <strong>0</strong> - punctele sunt <strong>coliniare</strong> (se află pe aceeași dreaptă)."},{"q":"Adevărat sau fals: dacă schimbi ordinea de enumerare a vârfurilor (de exemplu, listezi A, C, B în loc de A, B, C), formula poate da un rezultat „brut” cu semn schimbat, dar valoarea absolută a ariei rămâne aceeași.","pasi":["Formula fără valoarea absolută depinde de sensul de parcurgere a vârfurilor: sensul antiorar dă un rezultat pozitiv, iar sensul orar dă un rezultat negativ.","Schimbând ordinea a doar două vârfuri se inversează sensul de parcurgere, deci semnul rezultatului brut se schimbă.","Valoarea absolută din formulă elimină acest semn, deci aria calculată rămâne exact aceeași, indiferent de ordinea aleasă."],"r":"✓ <strong>Adevărat</strong>. Doar semnul rezultatului brut se schimbă; aria (valoarea absolută) rămâne identică."},{"q":"Un topograf a notat pe hartă colțurile unui teren triunghiular: A(0,0), B(6,0) și C(2,8), în metri. Ce suprafață are terenul?","pasi":["Aplicăm formula ariei prin coordonate: S=½|x₁(y₂−y₃)+x₂(y₃−y₁)+x₃(y₁−y₂)|.","Înlocuim coordonatele: S=½|0×(0−8)+6×(8−0)+2×(0−0)|.","Calculăm: S=½|0+48+0|=½×48=24."],"r":"✓ Terenul are <strong>24 m²</strong>."}]};
CONTINUT_GEOMETRIE["teorema-lui-van-aubel"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie un patrulater oarecare ABCD, cu câte un pătrat construit în exterior pe fiecare latură. Dacă P₁, P₂, P₃, P₄ sunt centrele pătratelor de pe AB, BC, CD și respectiv DA, atunci segmentele P₁P₃ și P₂P₄ (care unesc centrele pătratelor de pe laturile opuse) sunt egale ca lungime și perpendiculare.</div>",formula_display:"P₁P₃ = P₂P₄ și P₁P₃ ⊥ P₂P₄",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"120,50 250,60 260,170 90,180\" fill=\"rgba(30,58,95,0.07)\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><text x=\"106\" y=\"45\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">A</text><text x=\"254\" y=\"52\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">B</text><text x=\"264\" y=\"178\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">C</text><text x=\"68\" y=\"188\" font-size=\"13\" font-weight=\"600\" fill=\"#1e3a5f\">D</text><circle cx=\"185\" cy=\"20\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"192\" y=\"17\" font-size=\"11\" fill=\"#c8922a\">P₁</text><circle cx=\"300\" cy=\"115\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"285\" y=\"105\" font-size=\"11\" fill=\"#c8922a\">P₂</text><circle cx=\"175\" cy=\"210\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"182\" y=\"222\" font-size=\"11\" fill=\"#c8922a\">P₃</text><circle cx=\"45\" cy=\"115\" r=\"3.5\" fill=\"#c8922a\"/><text x=\"14\" y=\"105\" font-size=\"11\" fill=\"#c8922a\">P₄</text><line x1=\"185\" y1=\"20\" x2=\"175\" y2=\"210\" stroke=\"#c8922a\" stroke-width=\"2\"/><line x1=\"300\" y1=\"115\" x2=\"45\" y2=\"115\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"170\" y=\"234\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">P₁P₃ = P₂P₄ și P₁P₃⊥P₂P₄</text></svg>",intuitiv_text:"Construiește câte un pătrat „în afară” pe fiecare latură a unui patrulater oarecare (nu neapărat paralelogram). Unește centrele pătratelor de pe laturile opuse cu câte un segment. <span class=\"hl\">Cele două segmente rezultate au aceeași lungime și sunt perpendiculare</span> - o simetrie ascunsă, valabilă pentru orice formă de patrulater.",intuitiv_nota:"Teorema a fost publicată de H.H. van Aubel în 1878 și este strâns înrudită cu teorema lui Napoleon, doar că folosește pătrate (unghi de 90°) în loc de triunghiuri echilaterale (unghi de 60°).",exercitii:[{"q":"Patrulaterul ABCD are pătrate construite în exterior pe fiecare din cele 4 laturi, cu centrele P₁ (pe AB), P₂ (pe BC), P₃ (pe CD), P₄ (pe DA). Ce relație leagă segmentele P₁P₃ și P₂P₄?","pasi":["Conform teoremei lui Van Aubel, cele două segmente care unesc centrele pătratelor de pe laturile opuse sunt congruente și perpendiculare."],"r":"✓ Sunt <strong>egale</strong> ca lungime și <strong>perpendiculare</strong>"},{"q":"Este teorema lui Van Aubel valabilă pentru orice patrulater, sau doar pentru cazuri speciale (paralelogram, dreptunghi)?","pasi":["Teorema este valabilă pentru orice patrulater oarecare, indiferent de formă."],"r":"✓ Pentru <strong>orice patrulater</strong>, fără restricții de formă"},{"q":"Câte pătrate trebuie construite pentru a aplica teorema lui Van Aubel unui patrulater?","pasi":["Se construiește câte un pătrat pe fiecare dintre cele 4 laturi ale patrulaterului."],"r":"✓ <strong>4</strong> pătrate, unul pe fiecare latură"},{"q":"Dacă patrulaterul ABCD este el însuși un pătrat, ce se poate spune despre segmentele P₁P₃ și P₂P₄?","pasi":["Prin simetria pătratului, cele două segmente sunt automat egale și perpendiculare, iar teorema confirmă că această simetrie se păstrează pentru orice patrulater."],"r":"✓ Rămân <strong>egale și perpendiculare</strong>, ca în cazul general"},{"q":"Ce teoremă similară, dar cu triunghiuri echilaterale în loc de pătrate, seamănă conceptual cu teorema lui Van Aubel?","pasi":["Este teorema lui Napoleon: se construiesc triunghiuri echilaterale pe laturile unui triunghi, iar centrele lor formează un alt triunghi echilateral."],"r":"✓ <strong>Teorema lui Napoleon</strong>"}]};
CONTINUT_GEOMETRIE["teorema-lui-miquel"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie triunghiul ABC și punctele P∈BC, Q∈CA, R∈AB (eventual pe prelungirile laturilor). Cercurile circumscrise triunghiurilor AQR, BRP și CPQ se intersectează într-un punct comun M, numit punctul Miquel.</div>",formula_display:"Cercurile (AQR), (BRP), (CPQ) se intersectează în punctul Miquel M",diagrama:"<svg viewBox=\"0 0 340 240\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><polygon points=\"170,30 70,195 290,180\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2\"/><circle cx=\"150\" cy=\"112\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"120\" y=\"108\" font-size=\"12\" fill=\"#1e3a5f\">R</text><circle cx=\"205\" cy=\"188\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"210\" y=\"205\" font-size=\"12\" fill=\"#1e3a5f\">P</text><circle cx=\"225\" cy=\"105\" r=\"3\" fill=\"#1e3a5f\"/><text x=\"232\" y=\"100\" font-size=\"12\" fill=\"#1e3a5f\">Q</text><circle cx=\"188\" cy=\"140\" r=\"4\" fill=\"#c8922a\"/><text x=\"195\" y=\"137\" font-size=\"13\" font-weight=\"600\" fill=\"#c8922a\">M</text><circle cx=\"180\" cy=\"90\" r=\"55\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><circle cx=\"230\" cy=\"150\" r=\"50\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><circle cx=\"150\" cy=\"160\" r=\"48\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/><text x=\"170\" y=\"228\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">cercurile (AQR),(BRP),(CPQ) se întâlnesc în M</text></svg>",intuitiv_text:"Alege câte un punct pe fiecare latură a unui triunghi (sau pe prelungirile lor) și desenează cele trei cercuri care trec prin fiecare vârf și cele două puncte alese de pe laturile alăturate. <span class=\"hl\">Oricât de arbitrar ai alege cele trei puncte, cele trei cercuri se întâlnesc mereu într-un singur punct comun</span> - punctul Miquel.",intuitiv_nota:"Auguste Miquel a descoperit-o în 1838, iar ea rămâne punctul de plecare al unei întregi familii de „teoreme Miquel”, folosite azi în geometria transformărilor și în studiul asemănărilor spirale.",exercitii:[{"q":"Pe laturile triunghiului ABC se aleg punctele P∈BC, Q∈CA, R∈AB. Ce garantează teorema lui Miquel despre cercurile circumscrise triunghiurilor AQR, BRP, CPQ?","pasi":["Teorema afirmă că cele trei cercuri au un punct comun M, numit punctul Miquel."],"r":"✓ Cele 3 cercuri se intersectează într-un <strong>punct comun M</strong>"},{"q":"Câte puncte trebuie alese pe laturile triunghiului (sau prelungirile lor) pentru a construi configurația Miquel?","pasi":["Se alege câte un punct pe fiecare dintre cele 3 laturi (sau prelungirile lor): P, Q, R."],"r":"✓ <strong>3</strong> puncte, unul pe fiecare latură"},{"q":"Dacă P, Q, R sunt exact mijloacele laturilor BC, CA, AB, unde se află punctul Miquel M?","pasi":["În acest caz particular, se poate arăta că punctul Miquel coincide cu centrul cercului circumscris (circumcentrul) triunghiului ABC."],"r":"✓ M coincide cu <strong>circumcentrul lui ABC</strong>"},{"q":"Cum mai este cunoscută uneori teorema lui Miquel, datorită modului în care cele trei cercuri se rotesc în jurul punctului comun?","pasi":["Teorema lui Miquel este cunoscută și sub numele de „teorema pivotului” (pivot theorem), pentru că M acționează ca un punct pivot pentru cele trei cercuri."],"r":"✓ <strong>Teorema pivotului</strong> (pivot theorem)"},{"q":"Câte cercuri, în total, formează configurația de bază a teoremei lui Miquel pentru un triunghi cu 3 puncte alese pe laturi?","pasi":["Se formează exact 3 cercuri circumscrise: (AQR), (BRP), (CPQ)."],"r":"✓ <strong>3</strong> cercuri"}]};
